WFJ.Data.add("quest", {
  [8021] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8022] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8023] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8024] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8025] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8026] = { "iCoke Prize Voucherを引き換える", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [8041] = { "Mount Mugambaの力", nil, nil, nil, "よくぞ来た、{class}。我はJin'rokh the Breaker、Mugambaのトロールだ。Zandalar部族の我々は、そなたの功績を認める。そなたの粘り強さと意志の強さに敬意を表する。\n\nこの護符を首にかけよ、{class}。Mount Mugambaの力をそなたの身に流れさせるのだ。我らの敵を討つとき、その力を得るがよい!", 0x8072a5e9, nil, nil, nil, 0x31fed87d, ".mmm." },
  [8042] = { "Mount Mugambaの力", nil, nil, "元気な姿を見られてうれしいぞ、{name}。お前が挑んできた輝かしい戦いは、この世界のあらゆる生命に影響を与えている。Hakkarを決してZul'Gurubの外に出してはならない。奴の底知れぬ飢えの前に、世界は必ずや崩れ落ちるだろうからな。\n\nお前の護符を渡せ。その力を増幅してやろう。Strength of Mugambaで我らの敵を懲らしめるのだ!", "俺たちはまた会うことになろう、{class}。", 0x8072a5e9, nil, nil, 0x71abc13c, 0xe212a238, ".mm.." },
  [8043] = { "Mount Mugambaの力", nil, nil, "{name}殿、戻ったか! Molthorがお前の功績を王に伝えている。お前の名はSouth Seasにまで知れ渡っているぞ。いつの日か、お前は伝説の{class}、後世に語り継がれる物語となるかもしれんな。\n\nもう一度その力を増幅してやれるよう、護符を渡してくれ。", "新たに見つけた力でGurubashiを滅ぼせ!", 0x8072a5e9, nil, nil, 0xbefeb2f1, 0x38bf1b42, ".mm.." },
  [8044] = { "Rage of Mugamba", nil, nil, "King Rastakhanがよろしくと言っている、{name}殿。このような栄誉が、Zandalar族以外の者に与えられたことはかつてない。\n\n<Jin'rokhが一礼する。>\n\nもう一度強化してやれるよう、護符を渡してくれ。Rage of Mugambaは今やお前の魂そのものと本質的に結びついていることを知っておけ。", "{class}、Zul'jinが羨ましがるだろうよ。前へ進み、征服しろ!", 0x4d6cacec, nil, nil, 0x0e203fad, 0xb3a29215, ".mm.." },
  [8045] = { "Heathen's Brand", nil, nil, nil, "心得よ、異教徒よ。大いなる災厄が我らを引き合わせた。そなたの異端の流儀はZandalarに理解されることも認められることもないが、我らは公正な民だ。この烙印を首にかけよ。それは我らの敵への警告であると同時に、そなたのZandalarへの友情の証ともなろう。\n\n我らの民に仕え続けよ。さすれば我はこの烙印の力を高めてやろう。", 0x703228db, nil, nil, nil, 0x4290a07f, ".mmm." },
  [8046] = { "Heathen's Brand", nil, nil, "私の判断は早計だったかもしれんな、{class}。この光へのお前の盲目的な信仰にも、結局は何らかの価値があるようだ。\n\nお前の印を渡せ。その力を増幅してやろう。", "我らの敵を倒すために必要なことをせよ、{class}。たとえそれが光を導くことを意味するとしてもだ。\n\n<Jin'rokhが身震いする。>", 0x703228db, nil, nil, 0x0b7a3a34, 0xc0127eea, ".mm.." },
  [8047] = { "Heathen's Brand", nil, nil, "正直に言おう。お前にこの大義を最後までやり遂げる決意があるとは思っていなかった、{class}。Zandalarは今やお前をかけがえのない盟友と見なしている。実に見事だ。\n\nお前の印を渡せ。もう一度その力を増幅してやろう。", "俺たちの信仰は違っているが、目的は正しい。俺たちの敵を打ち倒せ、誇り高き{class}よ。", 0x703228db, nil, nil, 0x5d138380, 0xfe2a5d48, ".mm.." },
  [8048] = { "Hero's Brand", nil, nil, "王がお前の存在を認められたぞ、{class}。お前はRastakhanにZandalarの真の盟友として受け入れられた、同族の中で最初の者だ。\n\nその努力には大いに報いがあるだろう。印を差し出せ。最後の増幅を施してやろう。", "警戒、栄誉、忠誠、勇敢……お前はこれらすべての特徴を体現した。烙印もそのようになることだろう。", 0x2c26bbb2, nil, nil, 0x2ed0d459, 0xb1aa9f00, ".mm.." },
  [8049] = { "The Eye of Zuldazar", nil, nil, nil, "我らの感謝のしるしとして、この護符を受け取れ、プリーストよ。\n\nEye of Zuldazarは、そなたとZandalarのトロールとの絆が強まるにつれて力を増す。折を見て我のもとへ戻れ。さすれば我が宝玉に力を込めてやろう。", 0xaede248e, nil, nil, nil, 0xc307eb14, ".mmm.", nil, nil, nil, nil, 0x8af55bae },
  [8050] = { "The Eye of Zuldazar", nil, nil, "ようこそ、プリーストよ。Eye of Zuldazarが力に脈打っている。お前には次の段階へ進む準備ができている。護符を渡せ。力を注ぎ込んでやろう。", "Soulflayerとその手下どもとの戦いを続けるのだ、{name}。奴をZul'Gurubの外へ出すことは、決して許してはならぬ。", 0xaede248e, nil, nil, 0x4350ef28, 0x4a6d592c, ".mm..", nil, nil, nil, 0x0b4b8ddb, nil },
  [8051] = { "The Eye of Zuldazar", nil, nil, "Gurubashiとのそなたの戦いの話が、風に乗って囁かれているぞ、プリーストよ。王族さえもそなたの功績を話題にし始めた。King Rastakhanがそなたの名を口にされたという噂まである。\n\nEyeに力を注ぐ時が来た。タリスマンを渡すがよい。儀式を執り行おう。", "そなたの試みに揺るぎなくあれ、{name}。Soulflayerはそなたの生きる意志を吸い取ろうとするだろう。", 0xaede248e, nil, nil, 0xd49d5e04, 0xd9c04d29, ".mm..", nil, nil, nil, 0x9bab358b, nil },
  [8052] = { "The All-Seeing Eye of Zuldazar", nil, nil, "そなたのような者があと10000人いればな、{name}。Hakkarの軍勢など瞬く間に風に散らされるであろうに。\n\n<Al'tabimはため息をつく。>\n\nとはいえ、Eyeは真の力を発揮する準備が整った。私に渡すがよい。", "奴らをすべて打ち倒して、Hakkarに始末させるのだ……", 0x34ea2a9f, nil, nil, 0x419f87bc, 0x9210ae1d, ".mm.." },
  [8053] = { "力の象徴: Freethinker's Armguards", "Primal Hakkari BindingsをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "お前は異教徒だ。異教徒にも部族の中に居場所がある。異教徒はZandalarの自由思想家だ。自由思想家は抑圧を恐れない。自由思想家は信じるもののために死ぬ。お前も信じるもののために死ぬだろうと、我々は知っている。それが我々の承認を得る。それがお前に、さらに己を証明する機会を与える。\n\n我々にはParagons of Powerが必要だ。Zul'Gurubへ行け。Hakkarの手下どもを殺せ。私が求めるものを手に入れたら戻れ。Zandalarの自由思想家の最初の戦装束を手にせよ。\n\n行け。", "戻ってきたのか？Paragons of Powerは持っているのか？私の時間を無駄にしているのではあるまいな？\n\nそうでないことを願うぞ、異教徒め。", "そなたは我らに大いなる誉れをもたらす。その手からはHakkarの手下どもの血が滴っている。そなたは部族の友だ。\n\nこの腕甲を身に着けよ。freethinkerの腕当てだ。これこそが我の言う真の力というものだ。", 0xde2be376, 0x4cb7e339, 0xe682da0c, 0xe0f11fe4, 0x65fa2dcb, "....." },
  [8054] = { "力の象徴: Freethinker's Belt", "Primal Hakkari ShawlをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "お前の信仰は我々にとって異質だ、異教徒よ。古のZandalarもかつて異端者の烙印を押された。Gurubashi Empireが強大だった頃のことだ。異教徒たちは大胆にもHakkarのプリーストに挑んだ。異教徒たちはその時、害虫のように狩られ殺された。その異教徒たちはBlood Godとの戦いで決して揺らがなかった。我々は彼らが払った代償を称える。彼らこそが自由思想家だ。\n\nZul'GurubでHakkarの手下どもを滅ぼせ。私が求めるParagons of Powerを持ってこい。成功すれば大いに報いられる。\n\n行け。", "お前が来たということは勝利か？Paragonsは持っているか？敵の残骸にまみれているか？", "そなたの誉れは部族において確かなものとなった。そなたはZul'Gurubで多くの命を奪った。敵はそなたの信念の前に倒れる。敵はそなたの力の前に倒れる。\n\nこれがfreethinkerのベルトだ。誉れの象徴だ。強力なmojoだ。今よりそなたのものだ。", 0x9ed27549, 0x6d075c5a, 0x86b0f105, 0x62e7a93a, 0xc4f4ee72, "....." },
  [8055] = { "力の象徴: Freethinker's Breastplate", "Primal Hakkari TabardをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "戦装束は部族の中での力をお前に与える。自由思想家はこうして称えられる。彼らは狂信者だ。彼らは胸当てに強力なmojoを込める。敵を前に信念が揺らいでも、胸当ては揺らがない。\n\nそのような胸当てを持つには、我々の間で崇められる者でなければならない。Zul'Gurubへ行け。私が必要とするParagons of Powerを奪え。中の愚か者どもから、最も苦痛を与える形でParagonsを奪え。それを私のもとへ持ってこい。自由思想家としての価値を、今度こそはっきりと証明してみせろ。", "Paragonsは持っているか？その中にはモジョが宿っている。我らにはそれが必要だ。お前は我らを助けるのだ。", "そなたはほとんど誰にも成し得ぬことを成し遂げた。Hakkarの手下どもをひざまずかせた。freethinkerに何ができるかを奴らに示した。異端者がいかにして部族で敬われうるかを我らに示した。そなたは真の力以上のものを持つ。そなた自身が真の力なのだ。\n\nその胸当てを取れ、freethinkerよ。そなたに逆らう者を打ち砕け。", 0x79d60ba4, 0x3082c49f, 0xc5fe864a, 0x948d58f7, 0x0ebc9145, "....." },
  [8056] = { "力の象徴的存在: Augur's Bracers", "Primal Hakkari ArmsplintをMaywiki of Zuldazarのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nMaywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。", "俺たちの部族の予言者は、神の視力という授かりもので崇められてるんだぜ、ヤ・モン。奴らは呪術医じゃねえ。人に呪いをかけるんじゃなく、骨を投げたり葉を読んだりして洞察を得ることに時間を使ってるのさ。お前もシャーマンなら、予言の力について多少は知ってるだろう。俺たちZandalarは、奴らが部族に与える洞察を大事にしてるんだ。\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちにお前の価値を示してくれ。そうしてくれりゃ、俺たちの予言者が何より大事にしてる腕輪をくれてやるよ！", "俺が必要なZul'GurubのParagons of Powerは手に入れたか？この腕甲は、どんな苦労をしてでも手に入れる価値があるぜ！", "お前さんにはZandalarの占い師の素質が少しあるようだな。お前さんがZul'Gurubで俺たちのためにやってきた働きは知ってるぞ。このParagons of Powerは、Zandalar族を大いに助けてくれるだろう。付け加えるなら、Zandalar族はお前さんが友として頼れる一族だ。この腕甲を受け取れ、{name}。お前さんはそれ以上の働きをしたんだからな！", 0x364aa100, 0x149fe38e, 0x00ebd8ea, 0xbf46324b, 0xff612ec7, "....." },
  [8057] = { "力の象徴: Haruspex's Bracers", "Primal Hakkari StanchionをMaywiki of Zuldazarのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nMaywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。", "臓卜師は俺たちの部族の要となる一員だ。奴らの予兆には耳を傾けるのが賢明ってもんさ。獣と心を通わせ、必要な時には獣を霊に捧げることで、奴らは俺たちに神の導きを授けてくれる。昔は、臓卜師の洞察と知恵のおかげで、Gurubashiの分裂した部族との戦で優位に立てたんだ。\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちにお前の価値を示してくれ。そうしてくれりゃ、Zandalarの臓卜師なら誰でも欲しがる腕輪をくれてやるよ。", "Zul'GurubのParagons of Powerは手に入ったか？この腕甲はその苦労に見合うぜ、{name}。信じてくれよ、兄弟！", "ああ、{name}、力の象徴から来る力を感じられるよ。あんたは部族が「友」と呼べる者だってことを証明した。取引は取引だ、{name}……haruspex's bracersの力をよく見なよ!", 0xa22f9fd5, 0xa981faf7, 0x0dca424c, 0x4cdbbfcc, 0xca41f30b, "....." },
  [8058] = { "力の象徴: Vindicator's Armguards", "Primal Hakkari ArmsplintをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "復讐は力だ。Zandalarの報復者こそがそのような力だ。部族には多くの敵がいる。報復者は奴らに報いを与える。我々に対する罪で罰せられぬものはない。報復者がその罰を下す。敵は我々の復讐を恐れる。恐れるべきなのだ。永遠に恐れ続けるだろう。\n\n我々の報復者の一人となれ。Zul'GurubでParagons of Powerを求めよ。Hakkarの手下どもを倒し、部族の名のもとに復讐を果たせ。お前は報いられるだろう。", "Paragons of Powerは持ってきたか？Zandalarの名において復讐は果たされたか？", "そなたは今日、大いなる復讐を成した。vindicatorの相貌をまとった。Blood Godの手下どもをひざまずかせた。\n\nこれを取れ。この先そなたの復讐を燃え立たせるだろう。そなたは今やZandalarの友だ。", 0x04c2f9ac, 0x61a551e6, 0x7832db1f, 0x9733e57e, 0x3d2a6524, "....." },
  [8059] = { "力の象徴: Demoniac's Wraps", "Primal Hakkari StanchionをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "ウォーロックは悪魔を扱うことで危うい橋を渡るもんだが、俺たちのデモニアックはさらに一歩先を行く。古く秘術的な儀式によって、奴らは悪魔を自らの内に招き入れるんだ。だが、取り憑かれるに任せるんじゃなく、内側から悪魔を隷属させ、その獣の力を吸い取って自分の意のままにする。これを極められる者はほとんどいない。\n\nデモニアックの力を学ぶには、Zul'GurubのParagons of Powerがなきゃならねえ。そこへ行って、俺たちが求めるものを取り戻してこい。", "Paragons of Powerを持って戻ったか？Hakkarの邪悪な手下どもを倒せば、我らに自らを証明するだけでなく、悪魔術の道を学ぶ意志も示すことになるのだ。", "よくやった……Paragons of Powerを手放す前に、奴らはさぞかし苦痛に満ちたやり方で代償を払わされたことだろう。これを受け取れ――悪魔憑きの巻布だ。悪魔憑きの獲物を召喚するのに使われる強力な呪力から作られたもので、お前が力を手に入れるための強力な道具となる。", 0x508f1617, 0xca4f5ed3, 0x295c5c12, 0x6c5cc3e7, 0x4af30c71, "....." },
  [8060] = { "力の象徴: Illusionist's Wraps", "Primal Hakkari BindingsをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "我らが部族のメイジは幻術師と呼ばれている。彼らは呪文に強力なmojoを用い、しばしば部族の敵を惑わせ、混乱させるのだ！\n\n<Al'tabimが邪悪に笑う。>\n\n力ある幻術師が働くさまは見ものだぞ。敵を己の狂気によって膝を屈させるのだからな！\n\n我らが幻術師の道を知りたければ、Zul'Gurubへ行き、選りすぐりのParagons of Powerを持ち帰れ。その見返りに、我らが幻術師が呪文を紡ぐのに使う腕の布をくれてやろう。", "{name}、もう戻ったのか？俺が必要なParagons of Powerは手に入ったか？", "見事だ……その中を流れるmojoを感じ取れたか? Paragons of Powerは、Gurubashi Empireがこの地を支配していた頃、一種の通貨として使われていた。今や我らZandalarは、その内に眠るmojoを使って、Blood God Hakkarの二度目の台頭と戦うのだ!\n\n今日はよくやった。Zandalarに友を得たと思うがよい。その証に、約束したillusionistの巻き布をやろう!", 0x37267b33, 0x8c856188, 0xe3909faa, 0xf2dc1007, 0x0232e56f, "....." },
  [8061] = { "力の象徴: Confessor's Wraps", "Primal Hakkari StanchionをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "我らZandalarは、神性の権威をもって語る者に力を授ける。我らのプリーストは単なる癒し手ではない――我らの聴罪者なのだ。悪は外からの脅威――Hakkarのような――からも、部族の内からも生まれる。我らの聴罪者は我らの中で裁き手として働き、Gurubashiを内側から食い尽くしたのと同じ悪から我らを守っている。\n\nZul'Gurubへ行き、GurubashiからParagons of Powerを持ち帰れ。聴罪者であるとはどういうことかを学び、我らを悪から守るのだ。", "Zul'Gurubから戻ったのか？Hakkarの手下どもからParagons of Powerを取り戻すことはできたか？", "素晴らしい、{name}よ! これを持ち帰ったことは小さな手柄ではないぞ。今日、間違いなく君はHakkarの脅威から我々を守る部族の聴罪司祭として行動してくれたのだ。この腕輪は君のような友に相応しい!", 0x540e9544, 0xca4f5ed3, 0x86d784dd, 0xe80d1aaa, 0xca192b7f, "....." },
  [8062] = { "力の象徴: Predator's Bracers", "次のZul'GurubのParagons of PowerをFalthir the Sightlessのところへ持って行って下さい：Primal Hakkari Bindings。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "Gurubashi Empireが滅びた後の暗黒の時代、Zandalarの捕食者たちはその腕前で部族の糧を得ていた。ハンターは我らが部族の捕食者によく似ていると言う――狩りを求めることは捕食者の本質を体現することだ、そうだろう。だが、お前のZul'Gurubでの狩りこそが、我らの最も優れた捕食者たちの中でお前が本当はどれほどの者かを示すことになる。\n\nZul'Gurubの中からParagons of Powerをいくつか持ってこい。そうすれば、究極に次ぐ捕食者となる最初の一歩を踏み出せるだろう。", "Zul'GurubでParagons of Powerを持つ者どもを狩れ、{name}。奴らはお前の獲物だ。奴らは我らが共に必要とするものを持っている。", "ああ……力の象徴の存在を感じるのに視力など必要ない。Zul'Gurubでの成功は大勢の部族の者に感銘を与えた。君をZandalarの友と見なすだけでなく、predator's bracersを持つに値すると考えている。腕輪は強力な品で、捕食者となることの意味を象徴するものだ。よくやったぞ、{name}。", 0x0d61fa99, 0x14ce3c6a, 0x7c14821c, 0x5e16ced3, 0xd9d5a368, "....." },
  [8063] = { "力の象徴: Madcap's Bracers", "Primal Hakkari ArmsplintをFalthir the Sightlessのところへ持って行って下さい。また、Zandalar Tribeとの評判がFriendly以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "Zandalarの狂人たちはローグに似ているが、何よりも狂気を……混沌を……存在の予測不能さを受け入れている。戦場では見るも恐ろしい存在で、部族が分裂した後の野蛮な時代には、敵の間に混乱と騒乱の種を蒔いた。彼らがいなければ、我らは今日ここにいなかっただろう。\n\n私が求めるParagons of PowerをZul'Gurubから持ってこい。そうすれば狂人が大事にする鎧の最初の一つを授けてやろう。狂気を受け入れよ！", "Zul'Gurubの内なる狂気を探し出し、お前自身の狂気でそれを覆い尽くせ、{name}！そうすれば成功、成功すれば報酬だ！Blood Godを再び君臨させてはならん！", "よくやった、{name}……Zul'Gurubでの功績は、Zandalar部族を友と呼ぶ権利をお前に与えたのだ。私はこの象徴の処置を引き受けよう。働きの礼にこの報酬を受け取ってくれ!", 0x2329b2ef, 0x6d2ba324, 0xac62a211, 0x5ad41329, 0x3b4f87cb, "....." },
  [8064] = { "力の象徴: Haruspex's Belt", "Maywiki of ZuldazarにPrimal Hakkari Sashを渡して下さい。Maywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。Zandalar Tribeの評判がHonoredでなければなりません。", "俺たちZandalarはドルイドのやり方なんざ知らねえ。自然は俺たちの必要に合わせて形作るもんで、その逆じゃねえんだ。それでも、臓卜師は俺たちの中で一番自然と通じ合ってる者だし、それも当然のことさ。獣の魂を手放すってのは、そいつらの一員であるとはどういうことかを知ることだ。それこそが自然の本当の力なんだよ。\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちに自分を証明してくれ。そうしてくれりゃ、強力な品をくれてやる――Zandalarの多くの臓卜師が使ってる帯だ。\n\n強いmojoだぜ、ヤ・モン！", "俺が必要なZul'GurubのParagons of Powerは手に入れたか？持ってりゃ、haruspex's beltはお前のもんだ。", "感謝するよ……これらの品に秘められた力は、それ自体が宝物になるのさ、間違いない。私が頼んだようにやってくれただけじゃなく、部族にも栄誉をもたらしてくれた。約束通り、これが報酬だよ!", 0xb03aaf35, 0x4f2188d0, 0x06722f41, 0x272e39ed, 0x258bdc17, "....." },
  [8065] = { "力の象徴: Haruspex's Tunic", "Maywiki of ZuldazarにPrimal Hakkari Tabardを渡して下さい。Maywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。Zandalarの評判がReveredでなければなりません。", "臓卜師の力の究極の象徴は、奴らが身にまとうものなんだ、{name}。その中でもチュニックは、奴ら自身と、奴らが求める神の知恵とのつながりを象徴してる。捧げた獣の一部をチュニックに織り込むことも多くてな。そうすることで、自分の授かりものとのつながりを思い出すのさ。\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちにお前の価値を示してくれ。そうしてくれりゃ、臓卜師の真の力がにじみ出るチュニックはお前のもんだ。", "必要なZul'GurubのParagons of Powerは手に入れたか？haruspex's tunicは、どんな苦労をしてでも手に入れる価値があるぜ。", "驚いた……必要な力の象徴を首尾良く集めてきたんだね、{name}。Zandalarのために成し遂げたZul'Gurubでの偉業は伝説に残るほどさ。だから今後、部族では尊敬されるだろうよ。これがあんたの皮鎧だよ、強い{class}!", 0x6c23d61c, 0x14495bd9, 0xd020a584, 0xbe2aa486, 0x56d32719, "....." },
  [8066] = { "力の象徴: Predator's Belt", "次のZul'GurubのParagons of PowerをFalthir the Sightlessのところへ持って行って下さい：Primal Hakkari Shawl。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "捕食者は獲物に忍び寄る術を知っているが、成功する捕食者は間合いを詰めた後に獲物を打つ術を知っている。Zul'Gurubで成功する見込みを持つには……そしてZandalarの捕食者のようになる見込みを持つには、その両方を極めねばならない。\n\nZul'GurubからParagons of Powerの選りすぐりの品を持ってこい。私への報いはその装身具がもたらす力、そしてお前への報いはZandalarの捕食者の帯だ――取引するに十分値する装備だぞ。", "Zul'Gurubにいる狂ったHakkarの手下どもを討て。奴らこそParagons of Powerを持つ者たちだ、{name}。奴らに、そして部族に、捕食者を目指す者としてお前の成功を証明してみせろ。", "少し前にそなたの到来を感じ取った、{name}。だが容易ではなかった。そなたの存在を我に明かしたのは、そなたが携えてきたParagons of Powerだ。その装身具を目にせずとも力を感じられる。内に眠るmojo、言うなれば生のままの魔力は、Blood God Hakkarの邪悪な企みを打ち砕く我らの努力を支え続けるだろう。\n\nそなたの成功は称えられ、そして報われるべきだ。そなたは部族の中で誉れある者となり、predatorのベルトを身に着けるにふさわしい。", 0x7c5f5ac8, 0x478538e5, 0x009b304b, 0x75ee497d, 0xd86fe739, "....." },
  [8067] = { "力の象徴: Predator's Mantle", "次のZul'GurubのParagons of PowerをFalthir the Sightlessのところへ持って行って下さい：Primal Hakkari Aegis。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "我らZandalarは、身にまとうものを功績の象徴として大事にする。何をまとっているかが見えなくても、そこから発せられるものは感じ取れる――力は視覚を超えるのだ。Zandalarの捕食者の装束もそういうもので、中でも彼らが最も大事にするのが身にまとう肩当てだ。それは彼らの姿を人目から隠す助けとなり……望む時には、その存在を知らしめる助けともなる。\n\nParagons of PowerがZul'Gurubでお前に回収されるのを待っている。私の求めるものを持ってくれば、捕食者の肩当てはお前のものだ。", "Zul'Gurubへの攻撃は実を結んだか、{name}？私が求めるものを持ってきて、部族にお前自身を完全に証明した時にこそ、Zandalarの中で並ぶ者のないマントを得られるのだ。", "成功したか……{name}、君は部族から尊敬されるようになる。マントのために必要な力の象徴を手に入れるのは、ちっぽけな手柄ではない。しかし君は、捕食者の最も破壊的なやり方でそれを行った。君は捕食者たちの中に居場所を手に入れ、確かにマントを着る権利を手にしたのだ。", 0xdcda6553, 0xccfd4930, 0xdd75e5f1, 0x0bdda9fe, 0x8ec9fc27, "....." },
  [8068] = { "力の象徴: Illusionist's Mantle", "Primal Hakkari ShawlをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "魔法とは、それを形作れるだけの強さを持つ者が形作るべき、荒々しく原初の力だ。mojoは我らがこの力を広げたものであり、その強力な操り方の一つが幻術という形なのだ。そこに本当はいない敵に、どうして勝てると本気で望めよう？我らZandalarはこの力を知っており、それゆえ幻術師は部族の中で名誉ある地位を占めている。\n\n必要なParagons of PowerをZul'Gurubから奪ってこい――その見返りに、部族からの名誉と、我らの最高の幻術師が使う強力な肩当てがお前のものとなろう！", "Zul'Gurubへの遠征はどうだった？幻術の力で敵を狂わせてやったか？幻であろうとなかろうと、奴らの死と、奴らから奪ったParagons of Powerは、Hakkarの台頭を阻む助けとなるだろう。", "成功だ! これより先、そなたは部族で誉れある者となる! 今日Zul'Gurubは確かにZandalarの力を味わった。そなたのおかげだ、{name}。\n\n部族の祝福とともに、Zandalar illusionistの肩当てを取れ。よく役立つことを願う。", 0x3cdbf5d2, 0x9bf552d4, 0x0b223173, 0xecda0028, 0x244bf3cf, "....." },
  [8069] = { "力の象徴: Illusionist's Robes", "Primal Hakkari KossackをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "部族は、身にまとうものによって地位と力を認める。我らの装束は最上の素材で作られ、我らを強くするmojoが織り込まれている。幻術師も例外ではない。彼らのローブは、その見た目に幻術の本質を体現していると言われる。伝説によれば、彼らの古のローブは二度と同じ姿に見えることはなかったという。\n\n幻術師のローブをくれてやろう、{name}……だがまずは、部族の中で崇められる地位を勝ち取れ！Zul'GurubからParagons of Powerを持ってこい！", "我らに必要なParagons of Powerを持って戻ったか？容易でないことは分かっている……だが、Hakkarとの戦いで我らを助けに部外者が来ると、私はずっと前から予言していたのだ。それがお前であれ、と私は言おう！", "ついに、illusionist's robeを着るに相応しい者が! Zul'Gurubでの成功によって、部族内で君が長い間称賛されることが確実になったのだ。誇りをもってこれを着るがよい、{name}!", 0xdefb4030, 0xccd8bf07, 0x04720e50, 0xcc7a9a2d, 0xbe35343e, "....." },
  [8070] = { "力の象徴: Confessor's Bindings", "Primal Hakkari SashをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "Gurubashiが滅びて間もなく、我らZandalarは部族の内なる悪によって最後の敗北を喫するところだった。その時、我らの中から聴罪者が立ち上がり、同胞を滅ぼそうとする者たちを追放することで部族を守ったのだ。彼らは我らを霊と通じ合わせてくれるだけでなく、肉体をも守ってくれる。\n\nZul'Gurubへ乗り込み、HakkarとGurubashiの堕落をその目で見届けよ。我らが求めるParagons of Powerを奴らからもぎ取れ。成功すれば報いられよう！", "Paragons of Power……持っているか？それを手にして初めて、中に蓄えられた潜在的な力を使えるようになる。Blood Godの手下どもに形勢を逆転してやるのは愉快だろうな……", "成功だ! これはHakkarの台頭に対抗する我らの力を築くのに大いに役立つ。そなたの助けによって、我らはBlood Godが我ら全員を滅ぼすことはないと確かにするための大きな一歩を踏み出した。\n\n今日そなたは部族から誉れを得た、{name}。これを取れ。confessorの手甲だ。我らの感謝の証として。", 0xe63b6831, 0x26d1304d, 0xa772637b, 0xf10e3594, 0x8de5636f, "....." },
  [8071] = { "力の象徴: Confessor's Mantle", "Primal Hakkari AegisをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "Zandalarの聴罪者は皆、特徴ある肩当てを身に着けており、それが部族の守り手の印となっている。この肩当てには強力なmojoが織り込まれ、部族を脅かす者を裁く助けとなる。プリーストとして、お前もまた、ふさわしい者とそうでない者を裁くことに時間を費やさねばならない。このような肩当ては、きっとお前にとって恵みとなるだろう。\n\nZul'GurubでHakkarの手下どもと戦い、私が求めるParagons of Powerを持ってくれば、その見返りに我らの最高の聴罪者にふさわしい肩当てを授けよう。", "Zul'GurubのParagons of Powerは持っているか？", "よくやった、{name}……今日、Hakkarの手下はZandalarの報復を確かに感じただろう。感謝する。その行いによって君は、部族内で永久に尊敬される立場を得たのだ。我々の祝福とともに、confessor's mantleを受け取ってくれ!", 0x07a14cd0, 0xb9723536, 0xe7a24c5b, 0xf4cc4d64, 0x3210f6ea, "....." },
  [8072] = { "力の象徴: Madcap's Mantle", "Primal Hakkari GirdleをFalthir the Sightlessのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "Zandalarの伝説のmadcapの一人に、Khar'vaxal the Crackedがいた。伝説によれば、部族の敵と初めて相まみえたとき、Kar'xavanは「狂気の織り」で特別に織られたマントをまとったという。その姿を覆っていたのはマントだけではない。双つの短剣の目にも止まらぬ速さもまた、彼の姿を覆い隠していた。今日のmadcapたちは、部族における自らの地位の証としてマントを大切にしている。\n\n私が求めるParagons of Powerを持ってくれば、そのようなマントがそなたのものとなり、自らの敵に狂気を織りなすことができるだろう。", "戻ったか。私が必要なParagons of Powerは持っているか？\n\nKhar'vaxal the Crackedの伝説は、今日の我らに思い出させてくれる。どれほど大きな脅威であろうと、打ち倒せない敵などいないのだと。混沌はあらゆる者を跪かせる、それだけは確かだ……そしておそらくは、混沌の中で最も混沌らしからぬ要素さえもな。", "この日、勝利は我々のものとなった。君が共通の敵へ蒔いた狂気に感謝するぞ! 君はZandalarで称賛されることとなった。madcap's mantleを差し上げるより他に、君の行いに感謝を示す良い方法などない!", 0xe0ed8217, 0xdac3e0f6, 0x2877f3e4, 0xc746d123, 0xba22b0c2, "....." },
  [8073] = { "力の象徴: Madcap's Tunic", "Primal Hakkari AegisをFalthir the Sightlessのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nFalthir the SightlessはStranglethorn ValeのYojamba Isleにいます。", "私の目はとうの昔に見えなくなったが、惜しいとは思わない。我らのような部族――まとう装束が地位と目的を示す部族――の中でさえ、最も力ある衣は、ただの目には見えない力を放っているのだ。Zandalarの狂人が大事にするチュニックも例外ではなく、彼らが操ることのできる混沌と狂気の生の力を放っている。\n\n私が必要とするParagons of PowerはZul'Gurubにある。私の求めるものを持ってくれば、お前自身の伝説のチュニックで報いてやろう……狂気を織りなす者にふさわしい一着でな。", "Isleへよく戻った、{name}……Paragons of Powerを携えて意気揚々と戻ってきたのか？", "驚きだ……君は今日、誰もが可能と思わなかったことを成し遂げたのだ。{name}よ、部族から君への尊敬は生涯にわたるものとなった。madcap's tunicを着る権利を手にしたのだよ……我々の祝福とともに着てくれ。", 0xd34d6572, 0xebcfab16, 0x4e96fd72, 0x077d2949, 0x8b13f6a7, "....." },
  [8074] = { "力の象徴的存在: Augur's Belt", "Primal Hakkari GirdleをMaywiki of Zuldazarのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nMaywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。", "予言者は元素のmojoを知ってるんだ、モン。奴らはそれを使って部族を栄光へと導く。Gurubashi Empireが自ら引き裂かれた後の暗黒の日々、予言者たちは俺たちをSouth Seasの安住の地へと導いた。そして今度はここ、Valeへと俺たちを連れ戻したんだ。Zul'Gurubで煮えたぎる悪の真っただ中へな。\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちにお前の価値を示してくれ。そうしてくれりゃ、俺たちの予言者が使う帯をくれてやる――強力なmojoが込められたやつだ！", "俺が必要なのはParagons of Powerだぜ、兄弟。Zul'Gurubの悪との戦いのために、その中から力を丸ごと引き出してやるんだ。俺のために持ってきてくれたか？", "お前さんから討ち倒された悪の匂いがするぜ、{name}。いい匂いだ、なあ……お前さんもよく知っている匂いだろうよ。\n\nベルトに必要なParagons of Powerを持ってくるのが並大抵のことじゃないのは分かってる。お前さんの行いは部族に誉れをもたらしただけじゃなく、俺の部族の中でお前さん自身にも誉れをもたらしたんだ。ほらよ、augurのベルトを取って、自分のものとして身に着けな!", 0xde27fd77, 0x29cbd2fe, 0x340c5276, 0xfa1bc99a, 0x20e2f89c, "....." },
  [8075] = { "力の象徴的存在: Augur's Hauberk", "Primal Hakkari TabardをMaywiki of Zuldazarのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nMaywiki of ZuldazarはStranglethorn ValeのYojamba Isleにいます。", "Zandalarの予言者は皆、ホーバークって呼ばれる特徴ある胴鎧を着てるんだ。最上の絹と布で仕立てられ、丈夫な鎖が織り込まれてる。それは奴らの神性だけじゃなく、権威の象徴でもあるんだぜ、モン。霊と語ることに生涯を捧げた者に逆らうのは、決して賢いことじゃねえ……\n\nZul'Gurubの中からParagons of Powerを捧げ物として持ってきて、俺たちにお前の価値を示してくれ。そうしてくれりゃ、俺たちの予言者が着たいと願う中でも最高のホーバークの一つをくれてやるよ！", "Paragons of Powerは魔力の重要な源だ。augur's hauberkを作るのに使うのと同じ種類の力さ。必要なものを持ってきてくれりゃ、Zandalarの占い師なら誰でも自分のものにしたがる最高の衣を分けてやれるぜ。", "Paragons of Powerを俺に届けるのに、お前さんが何をくぐり抜けたかは分かってるぜ、{name}。簡単じゃなかったよな、なあ。Zul'Gurubから汚らしい粘液みたいに滲み出る悪を倒すなんてよ。だが全部終わった今、お前さんはこの先何代にもわたってZandalarの間で敬われるって、はっきり言えるぜ!\n\nほらよ、augurの鎖帷子を取って、誇りを持って身に着けな!", 0x1da1bd15, 0x3b35489a, 0x34c3dc89, 0x7f2ab0bb, 0x403d4c9f, "....." },
  [8076] = { "力の象徴: Demoniac's Mantle", "Primal Hakkari SashをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "デモニアックは力をただ持つのではなく、真っ向から体現しようとする。我らのデモニアックの中には、悪魔との戦いに敗れた者も一人や二人ではない。だが、敵が我らを脅かしている今――とりわけZul'Gurubで――デモニアックが敵に解き放てる力は、その犠牲に見合うものだ。我らの生き残りは、我らを滅ぼそうとする者を打ち砕くことにかかっている。Gurubashi Empireの滅亡がそれを教えてくれた。\n\nZul'Gurubへ赴き、我らが必要とするParagons of Powerを手に入れよ。そうすれば、価値あるデモニアックの品がお前のものとなろう。", "Zul'GurubのParagons of Powerは取り戻したか？我らはそれらの品から潜在的な力を取り出して我がものとするが、成功した暁にはお前にもお前自身の力の報酬を与えよう……", "よくやった、{name}。Zul'Gurubから得たParagons of Powerは、浪費された力の戒めとなるはずだ。Gurubashiは全盛期には強大だったが、その力に呑み込まれるがままになった。demoniacは自分たちの演じる駆け引きもよく似ていると知っているが、解き放たれた力こそが生き残るために必要なものであることも多い。\n\nZandalarの誉れある盟友として、この肩当てを使うがいい……よく役立つだろう。", 0x3d6338bf, 0x26d1304d, 0x6c965525, 0x09492f49, 0xc3488de8, "....." },
  [8077] = { "力の象徴: Demoniac's Robes", "Primal Hakkari KossackをAl'tabim the All-Seeingのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nAl'tabim the All-SeeingはStranglethorn ValeのYojamba Isleにいます。", "部族の中での力の究極の象徴は、戦で身にまとう装束だ。デモニアックのローブは、上質なruneclothと破壊的なまでに強力なmojoを一枚の布に融け合わせたものだ。そのローブの姿は、見る者すべての心に恐怖を植えつけると言われている……とりわけ、デモニアックがいずれ支配する悪魔どもの心にな。\n\nZul'Gurubから、ごく特定の組み合わせのParagons of Powerを持ってこなければならない。困難だろう……だが成功すれば、お前は必ず自分のローブを手にするだろう。", "Paragons of Power……持って戻ったのか？それを手にして初めて、悪魔術の力の究極の象徴をお前に授けよう、{name}。", "見事だ。Zul'Gurubでのそなたの勝利は、我らに、いや世界に、Hakkarが勝つことはないと確信させた。Blood Godと直に相対する時が来るかもしれぬ……そしてそうなったとき、Zandalar部族の間でそなたが敬われることは確かだと知っておけ。\n\nああ、それとこの質素なローブも役に立つだろうと思う。\n\n<Al'tabimが心得た様子でそなたにウィンクする。>", 0xf863db14, 0xccd8bf07, 0x7c84bb78, 0x2afe29c7, 0xf2cb3d45, "....." },
  [8078] = { "力の象徴: Vindicator's Belt", "Primal Hakkari GirdleをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がHonored以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "究極の復讐がZul'Gurubで待っている。Hakkarを再び蘇らせてはならない。HakkarはGurubashi Empireを内から滅ぼした。どんな生贄も足りなかった。トロールはかつての栄光の影にすぎない。それがHakkarのせいだと私は知っている。\n\nなるべくしてなる報復者となれ。悪の手下どもに破壊をもたらせ。Zul'GurubにZandalarの復讐を味わわせろ。Paragons of Powerで証を持ってこい。お前は報復者の帯を受け取る。お前は真の力を受け取る。\n\n行け。", "Paragons of Powerは持ってきたか？部族の敵を打ち倒したか？Hakkarに断罪者の怒りを思い知らせねばならん！", "vindicatorの道は、今やそなたの知るところとなった。そなたは部族に誉れをもたらした。自らに誉れをもたらした。我らの敵に苦痛をもたらした。\n\nvindicatorのベルトはそなたのものだ。そなたは確かにvindicatorの道と一つになりつつある。", 0xd8ed9e90, 0x478b959e, 0x904b423d, 0x83d8fdf5, 0x22013fcd, "....." },
  [8079] = { "力の象徴: Vindicator's Breastplate", "Primal Hakkari KossackをJin'rokh the Breakerのところへ持って行って下さい。また、Zandalar Tribeとの評判がRevered以上である必要があります。\n\nJin'rokh the BreakerはStranglethorn ValeのYojamba Isleにいます。", "報復者の力の象徴は胸当てだ。それは強力なmojoで鍛えられる。それは我々が崇める者にのみ託される。それはZandalarの復讐の象徴だ。\n\n報復者となることは、復讐そのものとなることだ。我々に必要なParagons of PowerをZul'Gurubから奪え。それを我々のもとへ持ってこい。我々は奪われたmojoを取り戻す。我々はHakkarの手下どもに償わせる。我々は報復者の胸当てでお前に報いる。\n\n行け。我々の復讐となれ、{name}。", "お前が来たということは勝利か？Paragons of Powerは持っているか？今日お前が果たした復讐のことを聞かせてくれ！", "そなたはその行いゆえに敬われるべきだ。部族は英雄に報いる。Zul'GurubはかつてないほどにZandalarの復讐を味わった。\n\nそなたの行いは、後に続く者たちの行いを告げ知らせるだろう。彼らはそなたを真の力の証と見るだろう。彼らはそなたを復讐の化身と見るだろう!", 0x5ff4d8e4, 0x8ba99b35, 0x15370977, 0xf6ef6b44, 0x16f24e88, "....." },
  [8080] = { "Arathi Basin Mark of Honor！", "Arathi Basinの戦いに勝ち、Arathi Basin Mark of Honorを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。", "戦争は兵士で戦うものだ。兵士なら誰でもそう言うだろう。そして、ろくな装備もなく、あるいは腹を空かせたまま戦う戦いは、始まる前から負けているとも言うはずだ！\n\nだからこそArathi Basinが重要なのだ。盆地には、欠かせない資源を抱えた要所がいくつもある。金属、武器、食料、木材――どれも必要で、どれもそこで手に入る。\n\nそれこそ私が君に求めることだ、{name}。Arathi Basinに入り、敵より多くの拠点を押さえて戦いに勝ち、Mark of Honorを持って私のもとへ戻ってくれ。", "Marks of Honorは持っているか、{name}？League of Arathorはそれがなければまともな戦いもできないのだ……", "Markを手に入れたんだな! よくやった! 資材は補給係に送っておこう。すぐに部隊へ配ってくれるはずだ。\n\nありがとう、{name}。まさに、君が成し遂げたような作戦を成功させることこそが、戦争に真に勝つ方法なんだ。", 0x47b434b4, 0x9a052c21, 0x52039791, 0x37247045, 0x2c6df8ea, "....." },
  [8101] = { "Pebble of Kajaro", nil, nil, nil, "{race}よ、この護符の枠に収められた小石は、South SeasのMount Kajaroから来たものだ。Mount Kajaroは不安定さに苛まれた地であり、激しく、しばしば魔法じみた火山の噴火で知られている。\n\nそなたとZandalarのトロールとの絆が深まるにつれ、この小石の力もまた増すだろう。小石の力を操り、我らの敵を討て。あの山のようにあれ。素早く、爆発的に、死をもたらすものに……", 0x2eb0ac60, nil, nil, nil, 0xa013bec7, ".mmm." },
  [8102] = { "Pebble of Kajaro", nil, nil, "おかえり、{class}。小石がよく使われたのが分かる。我らの敵の多くがお前の異界の力に倒れた。奴らの苦しみは大きかった。小石の力を高める時だ。私に渡すがよい。", "止められぬようにあれ。Kajaroの溶岩流のように。", 0x2eb0ac60, nil, nil, 0x91f18130, 0x208ad13f, ".mm.." },
  [8103] = { "Pebble of Kajaro", nil, nil, "Hakkariはお前を恐れている、{name}。奴らは、顔なきGodにしか為しえないと信じていた恐怖について語っている。お前はKajaroの力で奴らを焼いたのだ。奴らは今や2つの場所で恐怖を知った。\n\n小石をさらに強化する時だ。タリスマンを渡してくれ。", "Zul'Gurubのトロルの大量虐殺を続けよ。Hakkarは己の不屈の意志に世界が屈することはないと知らねばならぬ。", 0x2eb0ac60, nil, nil, 0x72c69bed, 0x1629466e, ".mm.." },
  [8104] = { "Jewel of Kajaro", nil, nil, "タリスマンを渡してくれ、{name}。見せなければならないものがある。", "<Al'tabimが目に見えぬ強大な力で小石を砕く。>\n\n分かるか? この小石は我らが晶洞と呼ぶものだ。小石の内には、この世界の眠れる力を吸い込み続けてきた強力な結晶がある。小石を半分に切ることで、我はついにその全き力を解き放たせた。これを使って我らの敵を薙ぎ払え。", 0x11c42304, nil, nil, 0x9b44ada9, 0xc32a2d4b, ".mm.." },
  [8105] = { "Arathi Basinをかけた戦い!", "鉱山・製材工場・鍛冶屋・農場を攻撃し、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、Arathi Basinをかけた戦いは資源と領地をかけた戦いだ。この土地にある重要地点を確保し、大量に必要な天然資源と物資を我が軍に供給すべく稼働させなければならない。お前に、Arathi Basinの本拠地から最も遠い重要地点を攻撃するよう命ずる。\n\n農場・鉱山・製材工場・鍛冶屋が敵に支配されていた場合は攻撃せよ。敵の旗を見つけ、旗柱から引きちぎれ!\n\n全4ヶ所でそれを終えたら、戻ってくるのだ。", "{name}、まだ4つの拠点を攻撃していないな。目標を達成したら戻ってこい。", "{name}、Arathi Basinでの快挙の知らせを受け取った。よくやったぞ! ここの闘争にお前のような者たちが加わることで、我々はいつの日か故郷を取り戻すことができるだろうと信じている。", 0xe8197bb2, 0x24235866, 0xc4127755, 0x735eaefc, 0x82cf24dd, "....." },
  [8106] = { "Kezan's Taint", nil, nil, nil, "このお守りを受け取るがよい、{class}。受け取り、その力で我らの共通の敵を討ち倒すのだ。\n\nそなたが首に掛けているのは歴史の一片であると知るがよい。Kezanはかつて、Zandalar Empireの広大な領土であった。悲しいかな、ゴブリンの交易王子どもの穢れが、誇り高き我が同胞たちを追い出すこととなったのだ。\n\n今やKezanはゴブリンの都Undermineの地となっている。だが、穢れる前のかの地は偉大であったことを知るがよい。今日に至るまで、Kezanは我が民にとって聖なる地とされているのだ。", 0x6067a15d, nil, nil, nil, 0xea1fab20, ".mmm." },
  [8107] = { "Kezan's Taint", nil, nil, "Zandalarのトロールの間では、名誉は勝ち取るものだ、{name}。名誉には報酬が伴う。友情、同盟……\n\nタリスマンを渡してくれ。その力を高めてやろう。", "闇から引き出せ、{class}。影の抱擁を。暗黒の干渉をKezan's Taintで補うのだ。", 0x6067a15d, nil, nil, 0xff7aa25c, 0xb612eed1, ".mm.." },
  [8108] = { "Kezan's Taint", nil, nil, "準備はできているぞ、{class}。もう一度お前のタリスマンを強化してやろう。望むのはただ、Hakkarとその手下どもの破壊を続けてくれることだけだ。\n\nタリスマンを渡すがよい。", "Soulflayerを止めるのは、我々の力を合わせた努力のみ。", 0x6067a15d, nil, nil, 0x4c9d4f28, 0x4bdb4d59, ".mm.." },
  [8109] = { "Kezan's Unstoppable Taint", nil, nil, "悪魔を呼び出せ、{class}。Kezan's Taintのエネルギーを浴びさせるのだ。戦場で奴らを指揮しろ！敵を殲滅せよ！\n\nそうだ……Kezan's Taintに最後の強化を施す時が来た。タリスマンを渡せ。", "奴らの死体から肉を剥ぎ取れ。影がHakkariを消滅させるのを見るのだ。奴らの恐怖から力を引き出せ、{class}。Kezan's Taintがその力を増大させるのだ……。", 0xed8cd3ad, nil, nil, 0xa5925c38, 0xce705016, ".mm.." },
  [8110] = { "Enchanted South Seas Kelp", nil, nil, nil, "この海藻が見えるか、なあ? South Seasから来たもんだ。ちょいとmojoとちょいと魔法を加えるだけで、持ち主に一番合った性質を帯びるのさ。\n\nお前さんは{class}だから簡単だぜ、なあ。首に巻いて、自然だとかリスだとか、お前さんたちが好きなもんを思い浮かべりゃいい。", 0xd8a92e91, nil, nil, nil, 0x08cac145, ".mmm." },
  [8111] = { "Enchanted South Seas Kelp", nil, nil, "よう、兄弟！また会えて嬉しいよ。部族のみんながお前のHakkari殺しやら何やらの話をしてるよ。Molthorからお前のタリスマンにもっとモジョを足すよう言われたんだ。こっちに渡しな、Maywikiがもっと良くしてやるよ。", "首飾りってのは煙草を吸うためにあるんじゃないよ! 邪悪なものと戦うために使うんだよ。", 0xd8a92e91, nil, nil, 0x3dabce99, 0x282fae5c, ".mm.." },
  [8112] = { "Enchanted South Seas Kelp", nil, nil, "そのタリスマンの具合はどうだい、兄弟？その葉っぱに魔法とモジョをもう少し足してやる頃合いみたいだね。しおれたところに花を咲かせてやらなきゃ。こっちに渡しな、Maywikiがすぐ直してやるよ。", "Zul'Gurubの邪悪なトロルをやっつけて、自然の力でできることを見せつけてやるんだよ!", 0xd8a92e91, nil, nil, 0x55d7f2aa, 0x0f1d50b3, ".mm.." },
  [8113] = { "Pristine Enchanted South Seas Kelp", nil, nil, "{name}！久しぶりだねえ。King Rastakhanご本人が、お前のタリスマンに最後のモジョと魔法を足せってあたしに命じたんだって、知ってたかい？本当だよ、兄弟！この目で見なきゃ信じられなかったね。こっちに渡しな。", "{name}、いい旅になったね。これからもHakkarと手下どもを殺して鎮圧し続けておくれ。", 0x3759aed2, nil, nil, 0xe55d18d9, 0xf5892e0b, ".mm.." },
  [8114] = { "拠点を4つ支配せよ", "Arathi Basinに入り、同時に4つの拠点を占領して支配した後、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、お前はArathi Basinの戦いで敵に神経を集中し、戦場で大きな戦果を獲得した。我々には{class}としての実力を示し、敵に対しては卑劣な行為に屈しはしないということを示したのだ。\n\n真価を示してくれたゆえ、難しい任務を与えよう。Arathi Basinにある少なくとも4つの拠点を手に入れ、確保してほしい。それが出来れば、重要な資源を確保するだけでなく、Hordeに我々が優位に立っていることを見せつけられよう!\n\n行け、{name}。幸運を祈る。", nil, "非常に素晴らしい働きだ、{name}! 興奮した偵察員がお前の手柄を知らせにきたぞ。League of Arathorにとって非常に喜ばしい!\n\nLeague of Arathorの兵士の間では、急速に英雄視されている。今日の行いにより再びお前の評価が証明されたのだ。", 0xc98ab4c9, 0xd307226a, 0xc7be4a3a, nil, 0x9427c6fc, "...m." },
  [8115] = { "拠点を5つ支配せよ", "Arathi Basinに入り、同時に5つの拠点を占領して支配した後、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、Arathi Basinの資源を巡る戦いは血生臭い仕事だ。League of Arathorに対する働きは、高く評価されるくらい必要とされている。\n\nそれでもうひとつ任務がある。\n\nLeague of Arathorは、Arathi BasinにおけるDefilersの支配に対して強烈な攻撃を仕掛けたいと考えている。戦場のあらゆる戦略的地点から奴らを追い払いたいのだ!\n\nこれは容易ではなかろうが、これを成し遂げられる者がいるとすれば、それはお前なのだ。", nil, "やったぞ! 拠点をすべて抑えたのだ! よくやったぞ、{name}!\n\n勝算があるか疑問を抱く者もいたが、お前ならできると思っていた。ありがとう。League of Arathorは敬服しているよ。同時に、ForsakenのDefilersもお前の名を聞いて恐れおののくに違いない!", 0x5965ad2a, 0xb5d88cf5, 0xecee114f, nil, nil, "...m." },
  [8116] = { "Vision of Voodress", nil, nil, nil, "お前さんとMaywikiには共通点があるぜ、なあ。どちらもシャーマンだ! もっとも、Maywikiはどちらかといえば神秘家で、お前さんはどちらかといえば半人前だがな。それでも、偉大な精霊が何をもたらすかは互いに知っている。\n\n贈り物として、首にかけるこの宝珠をやろう。奥深くを覗き込んで、South SeasのVoodressの村を見るがいい! それで心を晴れやかにするんだな!", 0xd4b0851d, nil, nil, nil, 0x9cd2f7c0, ".mmm." },
  [8117] = { "Vision of Voodress", nil, nil, "いい知らせだよ、{name}。Molthorが最近お前を褒めちぎってるよ。お前が本物のZandalarの英雄になってきたってさ。\n\nそれに、Maywikiにお前のオーブをもっと磨けってさ！こっちに渡しな、Maywikiが幻視を明るくしてやるよ。", "邪悪なHakkariの霊魂には気をつけなよ。本当に、奴らは不気味だからね。", 0xd4b0851d, nil, nil, 0xb28b36e8, 0x4fb3f53e, ".mm.." },
  [8118] = { "Vision of Voodress", nil, nil, "シャー・モン！Maywikiの冗談だよ！\n\n<Maywikiは笑う。>\n\nで、Zul'Gurubで精霊と元素の力を使って敵と戦ってるんだって？精霊に感謝を！\n\nMaywikiがお前のオーブを明るくしてやるよ。こっちに渡しな、{name}。", "ちょっとこれ見なよ、{name}。Voodressがもっとはっきりしてきただろう? 原始の力が流れるようにさせておきなよ。", 0xd4b0851d, nil, nil, 0x2499e758, 0x45679e87, ".mm.." },
  [8119] = { "Unmarred Vision of Voodress", nil, nil, "<Maywikiはあなたのタリスマンを指さす。>\n\n見てごらん、{name}！生きてるみたいだよ。精霊たちがオーブの周りで踊ってる。\n\nMaywikiに渡しな、最後の調整をしてやるから。", "{name}、あんたはいつかこの宝玉で私と直接話ができるようになるだろう。Hakkarとの戦いが終わったら、Maywikiは家に帰るよ。精霊に呼びかけて、その日が早く来るように頼もう。", 0x47a18639, nil, nil, 0x57fbf2cd, 0x119b7521, ".mm.." },
  [8120] = { "Arathi Basinをかけた戦い!", "鉱山・製材工場・鍛冶屋・厩舎を攻撃し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "聞き及んでいるだろうが、League of ArathorがArathi Basinへ大軍を派遣してきたのだ。食糧と物資を求め、Allianceの馬鹿どもはここの豊富な資源を手に入れて支配するつもりなのだ。奴らに、Arathiはもう二度と人間どもの故郷になどならないということを示さねばならん!\n\nArathi Basinへ行き、鉱山・製材工場・鍛冶屋・厩舎を攻撃せよ。敵の旗を引きずり下ろし、その領域はHordeのものであると宣言するのだ。\n\n行け、{name}。この任務を完了したら私のところへ折り返し報告せよ。", nil, "Defilerの密偵がお前が成功した知らせを届けにきたぞ、{name}。よくやった。\n\n身をもって知ったように、Arathi Basinをかけた戦いに勝利するには、油断することなくAllianceの領地拡大の試みを砕かねばならん。そうして、この地における我らの勝利は確実なものとなるのだ。", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8121] = { "拠点を4つ獲得せよ", "Arathi Basinで同時に4つの拠点を確保し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "{name}、Arathi Basinをめぐる戦いが熾烈さを増すにつれ、お前の戦いに関する知らせがよく耳に入る。我々の間でお前は非常に尊敬を集めていて、今から託す任務を完遂してくれるだろうという確信を与えてくれる。\n\nLeague of Arathorに意志を示す時だ。Arathi Basinにある奴らの所有地はほんのわずかで、すぐにでも無くなってしまうものだということを示さねばならぬ。Arathi Basinの戦略的地点4つすべてを一挙に手にすることで、それを見せつけてやるのだ。\n\n成功をおさめろ、{name}。そしてDefilersからの大いなる尊敬を得るのだ。", nil, "いい働きだぞ、{name}! Arathi盆地におけるその働きは非常に難しく、成功をおさめたことは実に称賛に値する。League of Arathorは盆地でのこの小競り合いで動揺するに違いない。そして痛手から立ち直ろうとするだろうが、ここで戦うという選択を思いとどまってもらいたいものだな。", 0xf638bec7, 0x8f858fe9, 0x33ce1ce8, nil, nil, "...m." },
  [8122] = { "拠点を5つ獲得せよ", "Arathi Basinで同時に5つの拠点を確保し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "理解が難しいことだが、我々は非常に深く対立し合っている。しかし、密偵がLeague of Arathorの決意の弱まりを報告してきた。この突破口を用いて、奴らに容赦ない一撃を与えなければならぬ! Arathi Basinへ戻り、敵の中へ身を投じるのだ。奴らを呪い、殺し、そして戦略的地点を5つすべて支配せよ! 奴らの兵士どもに絶叫をあげさせ、か細く泣き声をあげる口からお前の残虐な行いを語らせ、前線に血を流すのだ。\n\nそうして、Defilersのために大いなる勝利をおさめよ。", nil, nil, 0x8613b728, 0x9749d452, 0x9f6497b3, nil, nil, "...mm" },
  [8123] = { "Arathorの補給線遮断", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、HammerfallのDeathstalker Mortisのところへ持って行って下さい。", "League of ArathorはArathiを奪還するため、費用を惜しまず動いている。彼らとAllianceのあらゆる種族が、今この遠い地へ続々と押し寄せ、Refuge Pointeから支配を広げようとしているのだ。我々は奴らを止めねばならん。そして奴らを止める最善の手は、その物資を奪うことだ。\n\n君の力を貸してくれ、{name}。豊かな鉱山、肥沃な土地、腕の立つ職人で知られるArathi Basinへ入るのだ。奪えるだけの拠点を奪って守り抜き、戦いに勝ち、手に入れた資源を持って私のもとへ戻ってこい。", "何だ、{race}？Marks of Honorは持っているのか？Arathi Basinに戻り、Allianceの害虫どもを殺して、Dark Ladyのためにその資源を奪い取れ！", "<Deathstalker Mortisは微笑む>\n\n我らの敵にまたひとつ決定的な打撃が加えられた、{name}。君の働きのおかげで、Arathi BasinはまもなくDefilersの手に落ちるだろう。", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8141] = { "Zandalarian Shadow Talisman", nil, nil, nil, "そなたの進みは速いな、若き{class}よ。そろそろShera Ali'kh、Zandalariの言葉でDeath's Handを意味する一党に、そなたを迎え入れる時かもしれぬ。幾千年もの間、我らはZandalar Empireのために暗殺者の役を担ってきた。あまりに長く手をこまねき、Hakkariが力をつけるのを許してしまった。再びHakkarと相対することになるが、今度は結束した{race}の戦線の支えがない。Blood Godとその手下どもを打ち倒す助けとならねばならぬのは、そなたとそなたの仲間たちだ!\n\nこの護符を身に着け、旅路の助けとするがよい。", 0xb8ee5e0f, nil, nil, nil, 0x705ba316, ".mmm." },
  [8142] = { "Zandalarian Shadow Talisman", nil, nil, "見事だ、{name}。お前ほどの殺しの才を感じたのは何年ぶりか。Molthorでさえ、お前がZandalarのために成した働きを知っている。タリスマンをさらに強化する時だ。私に渡すがよい。", "護符にかけられる魔法はあとひとつだ、{class}。頃合いが来たら、魔法をかけてやろう。", 0xb8ee5e0f, nil, nil, 0xf8cada86, 0x11a474d7, ".mm.." },
  [8143] = { "Zandalarian Shadow Talisman", nil, nil, "お前がHakkariを数えきれぬほど死に至らしめたのを感じるぞ、{name}。奴らのモジョの悪臭がお前に染みついている。\n\nShadowのタリスマンがその間引きに役立ったのだろう？私に渡せ。その力を高めてやろう。", "暗殺者としての君には近づくべきでないな。敵は身をもって敬意を思い知るに違いない! 敵が「死の手」の閃きを目にした時こそ、君は敵から敬意を得るだろう……時既に遅し、だが……。", 0xb8ee5e0f, nil, nil, 0x4373d0b6, 0xc1164f66, ".mm.." },
  [8144] = { "Zandalarian Shadow Mastery Talisman", nil, nil, "それは成長を渇望している、{name}。タリスマンはお前が成したすべてを吸い込んだ。Zul'Gurubに散乱する何千ものトロールの死体が、その力の糧となったのだ。私に渡すがよい。最後の強化を施そう。", "Shera Ali'khの司祭の元で話すのもこれが最後となろう。君は必要なことをすべて理解した。護符を手に取り、討伐を続けるのだ。決してHakkarをZul'Gurubから出させてはならん。", 0x45b38bfd, nil, nil, 0x9b3819aa, 0xd2a500f4, ".mm.." },
  [8145] = { "Maelstrom's Tendril", nil, nil, nil, "Zandalariansの間では、ハンターの生業は敬われている。我らの最も偉大なハンターたちは、己の覚悟を示すためにMaelstromの縁まで旅をする。\n\n海の中心から、彼らはMaelstrom Tendrilsと呼ばれる海藻の束を引き上げる。その海藻は護符に編み上げられ、命中と力を高める魔法がかけられるのだ。\n\n我は今、そなたにMaelstrom's Tendrilの一筋の編み物を授ける。そなたとZandalarとの絆が深まるにつれ、我はさらなる力をこの護符に編み込もう。", 0x190411ee, nil, nil, nil, 0xcdb3656c, ".mmm." },
  [8146] = { "Maelstrom's Tendril", nil, nil, "ああ、{name}、またお前の匂いを嗅げて嬉しいぞ。\n\n<Falthirはにやりと笑う。>\n\n私のユーモアのセンスは大目に見てくれ。時にひどく下品になるのでな。\n\nお前が敵に大いなる苦悶を与えたのを感じる。Hakkarの軍勢が怒りに満ちてお前の名を叫んでいる。実に素晴らしい。\n\nお前はタリスマンにもう一つの織り目を加える資格を得た。私に渡すがよい。", "奴らには、お前の弾薬の先で贖罪を求めさせてやれ。", 0x190411ee, nil, nil, 0xd7681ef3, 0x034a1cb4, ".mm.." },
  [8147] = { "Maelstrom's Tendril", nil, nil, "ああ、{name}、またお前の匂いを嗅げて嬉しいぞ。\n\n<Falthirはにやりと笑う。>\n\n私のユーモアのセンスは大目に見てくれ。時にひどく下品になるのでな。\n\nお前が敵に大いなる苦悶を与えたのを感じる。Hakkarの軍勢が怒りに満ちてお前の名を叫んでいる。実に素晴らしい。\n\nお前はタリスマンにもう一つの織り目を加える資格を得た。私に渡すがよい。", "武器の先端で奴らに償いを求めろ。", 0x190411ee, nil, nil, 0xd7681ef3, 0x034a1cb4, ".mm.." },
  [8148] = { "Maelstrom's Wrath", nil, nil, "MolthorがKing Rastakhanからの言葉を届けてくれた、{name}。宮廷はお前によるHakkariの軍勢の殲滅にいたく感銘を受けている。お前のタリスマンに最後の織り目を授けるよう命じられた。私に渡すがよい。", "そなたの旅は始まったばかりだ、若き{class}よ。いつの日かMaelstromを訪れ、世界の中心を垣間見ることもあろう。\n\nそなたに力と不屈の心があらんことを!", 0x8035995b, nil, nil, 0x3c574c3d, 0x66380260, ".mm.." },
  [8149] = { "英雄礼賛", "Western PlaguelandsのUther's Tombへ行き、石像にUther's Tributeを使って下さい。その後、Harvest Festivalが終わる前に、Ironforgeの外にいるWagner Hammerstrikeのところへ戻って下さい。", "AzerothのHarvest Festivalの間、我々の代わりに犠牲を捧げた英雄たち……時として、尊い犠牲を払った英雄たちへの感謝を捧げるんだ。Allianceにはたくさんの英雄たちがいる。だが、Uther Lightbringerよりも悲劇的な物語を紡いだ者はいない。Western Plaguelandsの彼の墓へこの供物を捧げて、Utherを讃えるのを手伝ってくれ。彼の石像にこれを捧げて、それから戻ってきてほしい。私がここにいるのはこの祝祭が終わるまでだから、供物をUtherへ捧げるのに手間取らないようにな。", "Uther's Tombへの旅をして、そこにtributeを捧げてきたか？\n\n経験の浅い冒険者には危険な旅になりうる。比較的安全な行き方としては、Hillsbradを流れる川から北へ、Plaguelandsへ向かうのがいいだろう。その川はSorrow Hillに隣接する湖から流れ出ている。丘を西へ登っていくのだ。隣にある墓には近づかないように……そこはScourgeに蝕まれている。", "Utherは、英雄の中の英雄だった。Utherの最も偉大なる弟子であり、彼が我が息子のように可愛がった者……Arthasが全人類を裏切った時、彼が一体どんな苦悩を噛みしめたのか、想像することすらできない。それでも彼は、Arthasを止めるために立ち上がったのだ。それによって、彼は真のパラディンとしていつまでも記憶されることだろう。彼は死ぬまで戦った。守れるかもしれない者たちのことだけを考えながら。どうもありがとう、{name}。Utherの魂やHarvest Festivalの魂を礼賛して、君は今日、偉大なる英雄に敬意を表したのだよ。", 0x9e2b2607, 0x95fd1a45, 0xdb133806, 0x7489d4e8, 0x391a64b5, "....." },
  [8150] = { "英雄礼賛", "AshenvaleのDemon Fall CanyonにあるGrom's Monumentへ行き、石碑の前でGrom's Tributeを使って下さい。Harvest Festivalが終わる前に、Orgrimmarの外にいるJavnir Nashakのところへ戻って下さい。", "AzerothのHarvest Festivalの間、我々の代わりに犠牲を捧げた英雄たち……時として、尊い犠牲を払った英雄たちに感謝を捧げるんだ。Hordeにはたくさんの英雄がいる。だが、力と犠牲とをGrom Hellscream以上に身をもって示した者はいない。AshenvaleのDemon Fall Canyonにある彼の石碑にこの供物を捧げて、Gromを讃えるのを手伝ってほしい。石碑の前に供物を置いたら、戻ってきてくれ。私がここにいるのはこの祝祭が終わるまでだから、Gromに供物を捧げるのに手間取らないようにな。", "Grom's Monumentへの旅をして、彼のtributeをそこに捧げてきたか？\n\nその記念碑のある場所は、今もBurning Legionの穢れに触れられている。冒険の道にまだ不慣れなら、記念碑に近づく時は気を抜かないように。", "Gromのフルネーム、Grommashは「巨人の心」を意味する。Mannorothにただ一人で立ち向かうには、それ以上のものが必要だった。大族長が、オークの呪いはGromに始まりGromに終わったと言ったのが、一番うまい言い方だと思う。Gromの犠牲、そしておそらくは贖罪が、今日のHordeが湧き出る源となったのは、ふさわしいことだ。\n\nありがとう、{name}。お前は今日、偉大な英雄に敬意を捧げ、彼の魂とHarvest Festivalの精神を称えてくれた。", 0x9e2b2607, 0xc50c2b90, 0x3f9e0b27, 0x5b3796af, 0x7d839721, "....." },
  [8151] = { "ハンターの御守り", "AzsharaのOgtincに話しかけて下さい。", "AzsharaのOgtincが、君のような熟練のハンターに呼びかけている。彼は部族を離れてCenarion Circleに力を貸しているfurbolgのハンターだ。彼の教えは、同じ技を持つ者たちの知恵を豊かにし、均衡を保つ方へと導くためのものだ。彼と話すとよいだろう。\n\nOgtincはAzsharaの崖の上、Ruins of Eldarathの北東にいる。", nil, "今の私の務めは狩ることではなく、ハンターを教えることだ。それが運命が私に与えたものなのだ。\n\n私と共にハンターのお守りを作ろう。倒した獲物の戦利品を集めたもので、お前がこれまでの試練と勝利を思い出すためのものだ。最後にはそのお守りは私が預かるが、代わりに別のものを報酬として与えよう。", 0x9c075c99, 0xbd527185, 0xc599dc3a, nil, 0x0a79eb42, "...m." },
  [8153] = { "駿鹿の枝角", "Perfect Courser Antlersを一対、AzsharaのOgtincのところへ持って行って下さい。OgtincはRuins of Eldarathの北東にある崖の上に住んでいる。", "courserは、知られた土地で最も立派なantlersを持つ。そのようなantlersはcourserの身を守るのに使われ、襲う者を突き刺すので、先端が傷むこともしばしばだ。完璧で自然なままのantlersは、この上ない自信を持つ獣の霊の証なのだ。\n\nそのようなantlersを持てば、お前にも同じ自信が授けられよう。\n\nmosshoof courserを狩り、完璧なantlersを見つけて私のもとへ持ってこい。", "antlersは見つかったか？", "この角を手にしているあなたは、鋭い視野と素晴らしい忍耐力とを持ち合わせているに違いありません。お見事です。", 0x34c40124, 0x49ab2b8b, 0x175db876, 0x1ce9f144, 0xc6cc8dfd, "....." },
  [8154] = { "Arathi Basinの資源！", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。", "戦争は兵士で戦うものだ。兵士なら誰でもそう言うだろう。そして兵士はこうも言う。粗末な装備や空きっ腹で挑む戦いは、始まる前から負けているとな！\n\nだからこそArathi Basinが重要なのだ。あの盆地には欠かせない資源を抱える要所がいくつかある。金属、武器、食料、木材――どれもが必要で、どれもがあそこで手に入る。\n\nそれが君に頼みたいことだ、{name}。Arathi Basinへ入り、敵より多くの拠点を押さえて戦いに勝ち、資源の木箱を持って私のもとへ戻ってこい。", "Marks of Honorは持っているか、{name}？League of Arathorはそれがなければまともな戦いもできないのだ……", "Markを手に入れたんだな! よくやった! 資材は補給係に送っておこう。すぐに部隊へ配ってくれるはずだ。\n\nありがとう、{name}。まさに、君が成し遂げたような作戦を成功させることこそが、戦争に真に勝つ方法なんだ。", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8155] = { "Arathi Basinの資源！", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。", "戦争は兵士で戦うものだ。兵士なら誰でもそう言うだろう。そして兵士はこうも言う。粗末な装備や空きっ腹で挑む戦いは、始まる前から負けているとな！\n\nだからこそArathi Basinが重要なのだ。あの盆地には欠かせない資源を抱える要所がいくつかある。金属、武器、食料、木材――どれもが必要で、どれもがあそこで手に入る。\n\nそれが君に頼みたいことだ、{name}。Arathi Basinへ入り、敵より多くの拠点を押さえて戦いに勝ち、資源の木箱を持って私のもとへ戻ってこい。", "Marks of Honorは持っているか、{name}？League of Arathorはそれがなければまともな戦いもできないのだ……", "Markを手に入れたんだな! よくやった! 資材は補給係に送っておこう。すぐに部隊へ配ってくれるはずだ。\n\nありがとう、{name}。まさに、君が成し遂げたような作戦を成功させることこそが、戦争に真に勝つ方法なんだ。", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8156] = { "Arathi Basinの資源！", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。", "戦争は兵士で戦うものだ。兵士なら誰でもそう言うだろう。そして兵士はこうも言う。粗末な装備や空きっ腹で挑む戦いは、始まる前から負けているとな！\n\nだからこそArathi Basinが重要なのだ。あの盆地には欠かせない資源を抱える要所がいくつかある。金属、武器、食料、木材――どれもが必要で、どれもがあそこで手に入る。\n\nそれが君に頼みたいことだ、{name}。Arathi Basinへ入り、敵より多くの拠点を押さえて戦いに勝ち、資源の木箱を持って私のもとへ戻ってこい。", "Marks of Honorは持っているか、{name}？League of Arathorはそれがなければまともな戦いもできないのだ……", "Markを手に入れたんだな! よくやった! 資材は補給係に送っておこう。すぐに部隊へ配ってくれるはずだ。\n\nありがとう、{name}。まさに、君が成し遂げたような作戦を成功させることこそが、戦争に真に勝つ方法なんだ。", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8160] = { "Arathorの補給線遮断", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、HammerfallのDeathstalker Mortisのところへ持って行って下さい。", "League of ArathorはArathiを奪還するため、費用を惜しまず動いている。彼らとAllianceのあらゆる種族が、今この遠い地へ続々と押し寄せ、Refuge Pointeから支配を広げようとしているのだ。我々は奴らを止めねばならん。そして奴らを止める最善の手は、その物資を奪うことだ。\n\n君の力を貸してくれ、{name}。豊かな鉱山、肥沃な土地、腕の立つ職人で知られるArathi Basinへ入るのだ。奪えるだけの拠点を奪って守り抜き、戦いに勝ち、手に入れた資源を持って私のもとへ戻ってこい。", "何だ、{race}？Marks of Honorは持っているのか？Arathi Basinに戻り、Allianceの害虫どもを殺して、Dark Ladyのためにその資源を奪い取れ！", "<Deathstalker Mortisは微笑む>\n\n我らの敵にまたひとつ決定的な打撃が加えられた、{name}。君の働きのおかげで、Arathi BasinはまもなくDefilersの手に落ちるだろう。", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8161] = { "Arathorの補給線遮断", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、HammerfallのDeathstalker Mortisのところへ持って行って下さい。", "League of ArathorはArathiを奪還するため、費用を惜しまず動いている。彼らとAllianceのあらゆる種族が、今この遠い地へ続々と押し寄せ、Refuge Pointeから支配を広げようとしているのだ。我々は奴らを止めねばならん。そして奴らを止める最善の手は、その物資を奪うことだ。\n\n君の力を貸してくれ、{name}。豊かな鉱山、肥沃な土地、腕の立つ職人で知られるArathi Basinへ入るのだ。奪えるだけの拠点を奪って守り抜き、戦いに勝ち、手に入れた資源を持って私のもとへ戻ってこい。", "何だ、{race}？Marks of Honorは持っているのか？Arathi Basinに戻り、Allianceの害虫どもを殺して、Dark Ladyのためにその資源を奪い取れ！", "<Deathstalker Mortisは微笑む>\n\n我らの敵にまたひとつ決定的な打撃が加えられた、{name}。君の働きのおかげで、Arathi BasinはまもなくDefilersの手に落ちるだろう。", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8162] = { "Arathorの補給線遮断", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、HammerfallのDeathstalker Mortisのところへ持って行って下さい。", "League of ArathorはArathiを奪還するため、費用を惜しまず動いている。彼らとAllianceのあらゆる種族が、今この遠い地へ続々と押し寄せ、Refuge Pointeから支配を広げようとしているのだ。我々は奴らを止めねばならん。そして奴らを止める最善の手は、その物資を奪うことだ。\n\n君の力を貸してくれ、{name}。豊かな鉱山、肥沃な土地、腕の立つ職人で知られるArathi Basinへ入るのだ。奪えるだけの拠点を奪って守り抜き、戦いに勝ち、手に入れた資源を持って私のもとへ戻ってこい。", "何だ、{race}？Marks of Honorは持っているのか？Arathi Basinに戻り、Allianceの害虫どもを殺して、Dark Ladyのためにその資源を奪い取れ！", "<Deathstalker Mortisは微笑む>\n\n我らの敵にまたひとつ決定的な打撃が加えられた、{name}。君の働きのおかげで、Arathi BasinはまもなくDefilersの手に落ちるだろう。", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8166] = { "Arathi Basinの戦い！", "鉱山、製材所、鍛冶場、農場を攻撃し、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、Arathi Basinの戦いは資源と領土をめぐる戦いだ。我が軍に必要な原料と物資を供給するには、この地域の要所を押さえて稼働させねばならん。我々のArathi Basinの拠点から最も遠い地点への攻撃を君に命じる。\n\n農場、鉱山、製材所、鍛冶場が敵に押さえられていたら攻め込め。敵の旗を見つけ、旗竿から引きずり下ろしてやれ！\n\nその四か所すべてでそれを成し遂げたら、私のもとへ戻ってこい。", nil, "Arathi Basinでの君の活躍の報告は受けているぞ、{name}。よくやった! 君のような者たちがここでの戦いに加わってくれるなら、いつの日か我々の故郷を取り戻せると信じられる。", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8167] = { "Arathi Basinの戦い！", "鉱山、製材所、鍛冶場、農場を攻撃し、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、Arathi Basinの戦いは資源と領土をめぐる戦いだ。我が軍に必要な原料と物資を供給するには、この地域の要所を押さえて稼働させねばならん。我々のArathi Basinの拠点から最も遠い地点への攻撃を君に命じる。\n\n農場、鉱山、製材所、鍛冶場が敵に押さえられていたら攻め込め。敵の旗を見つけ、旗竿から引きずり下ろしてやれ！\n\nその四か所すべてでそれを成し遂げたら、私のもとへ戻ってこい。", nil, "Arathi Basinでの君の活躍の報告は受けているぞ、{name}。よくやった! 君のような者たちがここでの戦いに加わってくれるなら、いつの日か我々の故郷を取り戻せると信じられる。", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8168] = { "Arathi Basinの戦い！", "鉱山、製材所、鍛冶場、農場を攻撃し、Refuge PointeのField Marshal Oslightのところへ戻って下さい。", "{name}、Arathi Basinの戦いは資源と領土をめぐる戦いだ。我が軍に必要な原料と物資を供給するには、この地域の要所を押さえて稼働させねばならん。我々のArathi Basinの拠点から最も遠い地点への攻撃を君に命じる。\n\n農場、鉱山、製材所、鍛冶場が敵に押さえられていたら攻め込め。敵の旗を見つけ、旗竿から引きずり下ろしてやれ！\n\nその四か所すべてでそれを成し遂げたら、私のもとへ戻ってこい。", nil, "Arathi Basinでの君の活躍の報告は受けているぞ、{name}。よくやった! 君のような者たちがここでの戦いに加わってくれるなら、いつの日か我々の故郷を取り戻せると信じられる。", 0xe8197bb2, 0x24235866, 0xc4127755, nil, 0x82cf24dd, "...m." },
  [8169] = { "Arathi Basinの戦い！", "Arathi Basinの鉱山、製材所、鍛冶場、厩舎を攻撃し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "耳にしているだろうが、League of Arathorが大勢の兵をArathi Basinへ送り込んでいる。食料と物資に飢えたAllianceの愚か者どもは、あそこの豊かな資源を奪い、支配するつもりだ。Arathiが二度と人間の住処にはならないことを、奴らに思い知らせてやらねばならん！\n\nArathi Basinへ行き、鉱山、製材所、鍛冶場、厩舎を攻めろ。敵の旗を引きずり下ろし、それらの土地がHordeのものだと宣言するのだ。\n\n行け、{name}。この任務を終えたら私に報告しろ。", nil, "Defilerの斥候がお前の成功を報告しに来たぞ、{name}。よくやった。\n\nいずれ分かるだろうが、Arathi Basinの戦いに勝つには、常に警戒を怠らず、Allianceの勢力拡大の企てをことごとく叩き潰さねばならん。これを成し遂げれば、ここでの我々の勝利は約束されたも同然だ。", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8170] = { "Arathi Basinの戦い！", "Arathi Basinの鉱山、製材所、鍛冶場、厩舎を攻撃し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "耳にしているだろうが、League of Arathorが大勢の兵をArathi Basinへ送り込んでいる。食料と物資に飢えたAllianceの愚か者どもは、あそこの豊かな資源を奪い、支配するつもりだ。Arathiが二度と人間の住処にはならないことを、奴らに思い知らせてやらねばならん！\n\nArathi Basinへ行き、鉱山、製材所、鍛冶場、厩舎を攻めろ。敵の旗を引きずり下ろし、それらの土地がHordeのものだと宣言するのだ。\n\n行け、{name}。この任務を終えたら私に報告しろ。", nil, "Defilerの斥候がお前の成功を報告しに来たぞ、{name}。よくやった。\n\nいずれ分かるだろうが、Arathi Basinの戦いに勝つには、常に警戒を怠らず、Allianceの勢力拡大の企てをことごとく叩き潰さねばならん。これを成し遂げれば、ここでの我々の勝利は約束されたも同然だ。", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8171] = { "Arathi Basinの戦い！", "Arathi Basinの鉱山、製材所、鍛冶場、厩舎を攻撃し、HammerfallのDeathmaster Dwireのところへ戻って下さい。", "耳にしているだろうが、League of Arathorが大勢の兵をArathi Basinへ送り込んでいる。食料と物資に飢えたAllianceの愚か者どもは、あそこの豊かな資源を奪い、支配するつもりだ。Arathiが二度と人間の住処にはならないことを、奴らに思い知らせてやらねばならん！\n\nArathi Basinへ行き、鉱山、製材所、鍛冶場、厩舎を攻めろ。敵の旗を引きずり下ろし、それらの土地がHordeのものだと宣言するのだ。\n\n行け、{name}。この任務を終えたら私に報告しろ。", nil, "Defilerの斥候がお前の成功を報告しに来たぞ、{name}。よくやった。\n\nいずれ分かるだろうが、Arathi Basinの戦いに勝つには、常に警戒を怠らず、Allianceの勢力拡大の企てをことごとく叩き潰さねばならん。これを成し遂げれば、ここでの我々の勝利は約束されたも同然だ。", 0xe8197bb2, 0x5b64eb5f, 0xf3980fbf, nil, 0x1791a775, "...m." },
  [8181] = { "Yeh'kinyaとの対決", "Yeh'kinyaと話して下さい。", "Mosh'aru Tabletsを調べた結果、悪い知らせがある、{name}。Hakkarの真の姿、すなわち神そのものが、あなたが彼を捕らえたまさにその卵を通じて再び生まれ得るのだ。Yeh'kinyaはそれが彼の悪を封じ込めるためだと言ったが、実際は悪を蘇らせるためなのだ! あのトロールはあなたを欺いたのだ!\n\nYeh'kinyaのところへ行き、卵を渡すよう要求するのだ。Hakkarの復活を止めるのに手遅れでないことを祈ろう!", nil, "ほう、あの年老いたドワーフのIronbootと話をして、失われたMosh'aru Tabletsを見つけ出したというわけか。あのお節介な探鉱者め……\n\n構わん。この世界を救うにはもう遅い。Hakkarは蘇り、今この瞬間も力を増している……古のトロールの王国Zul'Gurubの奥深くでな! 奴は来たのだ! そして血と恐怖をもって支配するのだ!\n\n礼を言うぞ、{name}。そなたの助けがSoulflayerの帰還を早めたのだからな!", 0x2bf7824a, 0x865aa76c, 0x0bb245c9, nil, 0xe5c76923, "...m." },
  [8182] = { "「Rastakhanの手」", "StranglethornのMolthorと話して下さい。", "{name}、我々の最も恐れていたことが起きた。伝説によれば、Soulflayerは悪と恐怖によって古のトロールの世界を支配し、その力は絶対的なものだったという。今彼を止められなければ、彼の新たな支配はAzeroth全土に広がりかねない!\n\nこの闇の流れを食い止める助けとなるかもしれないZandalarianのトロールの一団がいる。彼らはStranglethornの沖、Zul'Kundaの遺跡の西にあるYojamba Isleに野営している。彼らの指導者Molthorと話し、彼がHakkarを倒す方法を知っていることを祈るのだ。", nil, "探鉱者のIronbootに遣わされたのか? 彼の一族は賢明だ。そなたを我のもとへ寄越したのはなおさら賢明だった。我とZandalarianのトロールたちならば、Soulflayerを倒す術を知っているかもしれぬからな。\n\nこの島のトロールたちと話し、その言葉に耳を傾け、備えよ、{name}。そなたの前にある務めは血にまみれているのだ。", 0x4d2a6b24, 0xa46e0578, 0x61260b13, nil, 0x265645c2, "...m." },
  [8183] = { "Heart of Hakkar", "Yojamba IsleのMolthorにHeart of Hakkarを渡して下さい。", "Heart of Hakkarは内部から熱く燃えている。魂刈りの神は倒されたが、その力の核は呪われた臓器の中に残ったままだ。", "{name}、邪悪な魂の悪臭がお前を包んでいる。Soulflayerに呪われたのか？", "おお、Heart of Hakkarか。ではSoulflayerは討たれたのだな! 我らの世界は救われた!\n\n{name}よ、そなたの我らへの貢献はいくら言っても言い足りぬ。そなたはまことにこの世界の英雄だ!", 0x6e55e232, 0xd83101d7, 0x5b4ef4b8, 0xa530809b, 0xaf2be6fe, "....." },
  [8193] = { "達人釣り師", nil, nil, "今日の2pmから4pmまで、誰が一番の釣り名人かを決める大会を開催するよ！Stranglethornの海岸沿いにいるTastyfishの群れで釣ったTastyfishを40匹、誰よりも先に持ってきた一番乗りの人が、Master Anglerの称号を手にするんだ！\n\n40匹を一番乗りで持ってこられなくても、ここにいる私の弟子が、Tastyfishを5匹持ってくるごとにお金で報酬を渡すよ。\n\nそれと、ぐずぐずしないでね。Tastyfishはすぐに傷むから！", "達人釣り師(the Master Angler)と認定されたいのでしたら、急いでここに返して下さいよ! 私はもう何時間も飲まず食わずでここら辺でずーっと立ったままなんですから! その魚を提出して下さいよ!", 0x0e93896b, nil, nil, 0x17676055, 0x25300c55, ".mm.." },
  [8201] = { "首のコレクション", "Channeler's Head 5つを糸につるし、そのCollection of Troll HeadsをYojamba IsleのExzhalに渡して下さい。", "本当だ。Hakkarは今Zul'Gurubに住み、我らの神々の力を浴びている。心を奪われた高位のプリーストたちが、我らの最も神聖な神々の力をSoulflayerへと注ぎ込んでいる。やがて彼はAzerothのいかなる存在をも超える力を得るだろう。彼を止めねばならん!\n\nこの神聖な紐を持って行き、我らの神々の力を注ぎ込んでいる高位のプリーストたちの首をこれに通すのだ。\n\nそれを終えたら、わしのところへ戻ってこい。", "headsは集まったか、{name}？Hakkarがこれ以上力を得るのを止めねばならん！", "首を手に入れたか! そなたは我らの神々の力の略奪を食い止め、Hakkarを弱らせたのだ!\n\nそなたの行いはまことに英雄的だ、{name}。このトロールの奴隷どもの首が、その血が冷えたのちも長く、そなたに慈悲を乞い続けんことを。", 0xd1be3435, 0x0a6cb370, 0xe1f0dd4e, 0x65d91c8c, 0x082ae89b, "....." },
  [8221] = { "希少魚: Keefer's Angelfish", nil, nil, "*Whir* *Click*\n\nFishmaster Bluegillが目録に載せる珍しい魚を探している。Keefer's Angelfishを持ってきてくれれば、この素晴らしい報酬を渡す。\n\n*Zzzap* *Whir*", "ブゥーン  Keefer's Angelfishの認証完了。\n\n報酬が入手可能になりました。\n\nカチカチ　ゴゴゴゴ", 0x07f9e0a5, nil, nil, 0x2cf7fe9f, 0xc5570f3f, ".mm.." },
  [8224] = { "希少魚: Dezian Queenfish", nil, nil, "*Whir* *Click*\n\nFishmaster Bluegillが目録に載せる珍しい魚を探している。Dezian Queenfishを持ってきてくれれば、この素晴らしい報酬を渡す。\n\n*Zzzap* *Whir*", "ウィーン  Dezian Queenfishの認証完了。\n\n報酬が入手可能になりました。\n\nカチカチ　ゴゴゴゴ", 0xddffff03, nil, nil, 0x3373cf5a, 0x955d8be4, ".mm.." },
  [8225] = { "希少魚: Brownell's Blue Striped Racer", nil, nil, "*Whir* *Click*\n\nFishmaster Bluegillが目録に載せる珍しい魚を探している。Brownell's Blue Striped Racerを持ってきてくれれば、この素晴らしい報酬を渡す。\n\n*Zzzap* *Whir*", "ブゥーン  Brownell's Racerの認証完了。\n\n報酬が入手可能になりました。\n\nカチカチ　ゴゴゴゴ", 0x7d23145b, nil, nil, 0x405ed225, 0xaa2d34fb, ".mm.." },
  [8227] = { "Nat's Measuring Tape", "Nat's Measuring TapeをDustwallow MarshのNat Pagleに返して下さい。", "壊れた釣りのルアーや道具の中に、丸められた絹のメジャーがある。そのメジャーには次のように書かれたラベルが付いている:\n\n「Nat Pagle、Dustwallow Marsh」", "やあ、若いの。釣りをしに来たのかい？", "おや、お気に入りの巻尺を見つけてくれたのか! この巻尺が大好きでね! 今まで釣った中で一番大きな魚を何匹か、これで測ったんだ……\n\nだが、この巻尺はZul'Gurubで失くしてしまってね……Zul'Gurubに行ったことがあるのかい? 伝説のGahz'rankaを見たか?\n\nそうか……あいつを釣り上げてみたいかね?", 0xbed193be, 0x6a384727, 0x6d87d88a, 0x666f8943, 0xccac2a23, ".....", nil, nil, nil, 0xd4faa5d5, nil },
  [8230] = { "Collinのテストクエスト", nil, nil, nil, nil, 0xfed429e7, nil, nil, nil, nil, ".mmmm" },
  [8231] = { "波裂き", "AzsharaのOgtincにWavethrasher Scale 6枚を渡して下さい。OgtincはRuins of Eldarath北東の崖の上に住んでいます。", "wavethrasherは、ここAzsharaにしか生息しない水陸両生の獣だ。力強く、しぶとい。\n\nwavethrasherの頑丈で光を映す鱗は、ハンターの強さを映し出す。\n\nAzsharaの海岸沿いでwavethrasherを追跡して狩り、その鱗を持ってきてくれ。", "うまくいったか？", "wavethrashersは容易に倒せる相手ではない。まして水の中ではなおさらだ。\n\nそなたはさらに危険な獲物を狩る用意ができていることを示した。", 0x44de0f03, 0x4d0a92ac, 0x8169d32a, 0x7cadef78, 0x363c01ff, "....." },
  [8232] = { "緑の竜", "AzsharaのOgtincにTooth of Morphazを渡して下さい。OgtincはRuins of Eldarath北東の崖の上に住んでいます。", "さて、お前には危険な狩りに出てもらう。緑の竜Morphazを倒し、その牙を私のところへ持ってくるのだ。MorphazはTemple of Atal'Hakkarの奥深くに棲んでいる。その入口はSwamp of Sorrowsにある。\n\n奴を倒したいなら、一人で行ってはならない。この竜は多くの者の敵だ――奴を倒したいと望む者たちを探すのだ。\n\n竜の牙は、ハンターが仲間と共にあるときに得る力を表している。それを私のところへ持ってくれば、お前は多くを学んだことになるだろう。", "あなたの目に知恵が見えます、{name}。狩りは終わりましたか？", "{name}、あなたは古き習わしを学びましたから、私がかつて{class}であった頃の品物を差し上げましょう。", 0x846c7820, 0x16ae3f61, 0x5f7dfa78, 0xa74a1750, 0x12cd986d, "....." },
  [8233] = { "簡単な依頼", "Ravenholdt ManorのLord Jorach Ravenholdtと話して下さい。", "Lord Jorach Ravenholdtがあなたを呼んでいる。これは秘密の用件で、これ以上は言えない。\n\nRavenholdt ManorはHillsbrad Foothillsにある――Durnhold Keepの北西の山中にある小道を探すといい。", nil, "ようこそ、ようこそ、ようこそ！さあ、{name}、席に着いて、ちょっとした用件について私と話そうではないか。\n\n実はな、{name}、最近大切なものを失くしてしまってね。率直に言えば、何としても取り戻したいのだ。君にも見返りはある、それは心配いらない！ああ、そうとも、とても素晴らしいものがな。\n\nさて、どうかね、{name}……ちょっとした冒険に乗り気かね？", 0x362b8cba, 0xf045dfbf, 0xbb6a9a60, nil, 0x782fc815, "...m." },
  [8234] = { "Sealed Azure Bag", "AzsharaのTimbermaw ShamanからSealed Azure Bagを取り戻して下さい。同じくAzsharaにいるArchmage Xylemのところへ、その袋を持って行って下さい。", "まずは最初のことからだ。私がなくしたのは小さな青い袋で、中身は個人的な事柄だ。\n\n泥棒どもを追う必要はない。奴らはもう死んでいるからな。分かっているのは、その間抜けどもが袋を開けられなかったということだ。それで奴らは、Azsharaのtimbermawのシャーマンに聖遺物として売りつけた。うまいことを考えたものだ。\n\nAzsharaへ行き、そのシャーマンから袋を取り戻してほしい。巧妙に……あるいは力ずくでな。前者の方がうまくいくと私は踏んでいるがね。手に入れたら、Archmage Xylemのところへ持って行ってくれ。", "どこかで会ったか？", "Ravenholdt卿の袋を持ってるのなら何故そう言わないんだ、若いの。", 0x35599650, 0x0ea5890f, 0xfe836e00, 0x879570ca, 0x860f19ff, ".....", nil, nil, nil, nil, 0xf0af4ecb },
  [8235] = { "記号化された断片", "AzsharaのArchmage XylemにEncoded Fragment 10枚を渡して下さい。", "Lord Ravenholdtが我々二人に頼み事をしてきた。彼はこの袋にかけられた魔法を取り除きたいのだ。\n\nあいにく、解呪に関する私の本の何冊かが最近盗まれ、野蛮な者たちに破壊されてしまった。本の残骸は今でも私にとって価値がある。\n\nencoded fragmentsを十分に持ってきてくれれば、私がつなぎ合わせて元に戻せる。一番確実なのはforest oozeを倒すことだ。奴らはほとんど何でも拾い上げる性質があるからな。Azsharaの北東で見つかるだろう。", "私の研究を続けるのに十分なfragmentsは見つかったか？", "状態の良い断片を拾ってきてくれたようだな。君はまったく使い物にならないわけではない、ということか。", 0x61daa4e2, 0xb44304fd, 0xca562999, 0x31bec209, 0x228991d5, "....." },
  [8236] = { "Azure Key", "Lord Jorach RavenholdtにAzure Keyを渡して下さい。", "断片を解読し、魔法を取り除くにはしばらく時間がかかる。それが済んだら、私が自ら袋をLord Ravenholdtに届けよう。\n\nまだ鍵の問題が残っている。Morphazという名の緑の竜が持っていると言われているものだ。その竜はTemple of Atal'Hakkarの奥深くを住処にしている。その入口はSwamp of Sorrowsにある。\n\n仲間を集め、奴の巣へ向かうのだ。Lord Ravenholdtが鍵を持って戻るあなたを待っているだろう。", "Archmage Xylemから袋はもう届いている。keyは見つかったか？", "鍵だ! 永久に失われたと思っていた。さあ、私の蓄えから魔法のかかった衣を取ってくれ。並外れた腕と忠誠を持つローグのために取っておいたものだ。{name}を軽んじてはならぬと、皆に知らしめるべきだな!\n\n<Jorachが袋を開けると、中から金色の輝きが溢れ出す。彼は目を見開き、じっと見つめる……>", 0x6d2a6be1, 0x4cbe4fb9, 0x108758a9, 0xfef60b7a, 0x12b73a85, "....." },
  [8240] = { "Zanzaに小さな宝石を", "Yojamba IsleにあるAltar of Zanzaで、Zul'Gurubで見つけたHakkari Bijou(種類問わず)を破壊して下さい。それを終えたら、近くにいるVinchaxaと話して下さい。", "様々なHakkari Bijousを破壊することは我々にとって非常に重要だ。部族の外の者たちが自らそれを行うことも歓迎するほどにな!\n\nZul'Gurubで見つけたbijousのどれか一つをAltar of Zanzaへ持って行き、破壊するのだ。この一度に限り、我々の部族のHonor Tokenを一つ追加で与えよう。これは通常受け取るものとは別の、特別なものだ。\n\nZanzaの祝福をその目で見届けるがいい!", "Altar of Zanzaでビジューを破壊したか？そうすれば、Zanzaから二重の祝福を受けられるぞ！", "見事だ……Blood Godの手下どもから奪い取るbijouの一つ一つが、ついに奴らを完全に打ち倒すための一歩となる。そなたは高潔な行いによって、Zandalarに、そして自らに誉れをもたらしている。\n\n覚えておけ、{name}。Zul'Gurubで見つけたbijouは、いつでも祭壇で破壊できる。その一つごとに、そなたは認められ、Honor Tokenを得る! まだtokenを一つも持っていないなら、鞄に空きを作っておくのを忘れるな。", 0x7f562633, 0xc0e17e48, 0x1e736b9d, 0x96f43724, 0xa8de4e84, "....." },
  [8249] = { "必要ながらくた箱", nil, nil, "私のローグたちは錠前破りの腕を磨く必要があるし、そのためにはそれなりに難しい錠前がいる。Zanが作ってくれるものは、ひよっこの中でも一番の未熟者にしか使えない代物だ。\n\nこうしよう、Heavy Junkboxesを5個持ってきてくれたら、ローグ界に知られる最高級の投げナイフをいくつかやろう。\n\n箱を開けて中を漁ってもいいが、少なくとも硬貨を少しは残しておいてくれ……訓練中のローグにだってやる気の元は必要だからな。", "このナイフが誰かの心臓に居場所を見つけますように。\n\n文字通りの意味でな。", 0x26effe33, nil, nil, 0x8ade345a, 0x5400bb60, ".mm.." },
  [8250] = { "魔法使いの技", "Sanath Lim-yoを捜し出し、Archmage Xylemと会う道を得て下さい。", "Archmage Xylemが最近あちこちで尋ねて回っている……あなたほどの経験を持つ者をね。\n\n彼を訪ねたいなら、Azsharaで見つけられる。彼の塔は崖の上高くに建てられていて、上へ行く唯一の方法は、彼の傲慢な従者Sanath Lim-yoが唱えるテレポートの呪文だ。\n\nSanathは主人の塔の下に野営している。彼を見つけるには、Azsharaの大通りがRuins of Eldarathの入口で分かれるところまで行くといい。その場所からまっすぐ北へ進めば、崖にたどり着くだろう。", nil, "<Sanathはあなたを嘲笑う。>\n\nArch{class} Xylemがあなたの到着を待っている。", 0x63df1028, 0xe163bc1a, 0xddf08947, nil, 0x6e8ed03a, "...m." },
  [8251] = { "Magic Dust", "Archmage XylemにGlittering Dust 10個を渡して下さい。", "Azsharaのblood elvesは、手に入れた魔法の品を粉々にする方法を編み出した。彼らが作るこのglittering dustは、解呪の呪文で通常得られる素材とは異なるものだ。\n\n弟子をその粉の取引に送ったところ、彼はためらいもなく殺された。その報いは受けてもらわねばならん。\n\n話し合いの時は終わった、{name}。Azsharaの崖沿いでblood elvesを見つけ出し、もっと「説得力のある」方法で彼らのglittering dustを手に入れてくるのだ。", "dustは手に入ったか？", "よくやった、{name}! 一斉に放たれたArcane Missilesがどれほど説得力のあるものだったか、感嘆してやまないよ。", 0x4aaccda3, 0x2fc323bf, 0xe2ab9e6d, 0x8bb6c816, 0x45b28429, "....." },
  [8252] = { "セイレーンの珊瑚", "Enchanted Coral 6つを集め、Archmage Xylemのところへ持ち帰って下さい。", "周りを見てみるがいい。遺跡も浜辺もspitelashで溢れ返っている。最近、あの忌まわしい生き物どもはAzsharaに固有の珍しい素材を見分けるようになった。\n\n具体的に言えば、enchanted coralのことだ――理由は分からんが、奴らはそれに引き寄せられている。今では湾に残っている珊瑚はわずかだが、それは私の研究に欠かせないものだ。spitelashのセイレーンからenchanted coralをいくらか奪い取り、私のところへ持ってきてくれ。", "spitelash sirensは驚くほど腕の立つメイジだ。君ほどではないと願うが？", "これは見事な珊瑚の標本だ、{name}。お前の技は疑いようもなく精密で、命取りだ。\n\nお前の働きが見過ごされたなどと思うな。おそらくお前は、その技の真の試練を受けるにふさわしい……", 0x1c65cc0b, 0x82fc4efd, 0xd1f78fea, 0x7f257375, 0x19112c98, "....." },
  [8253] = { "打倒Morphaz", "MorphazからArcane Shardを回収し、Archmage Xylemのところへ戻って下さい。", "Atal'Hakkarの沈んだ神殿の奥深くに、Morphazという名の緑の竜がいる。\n\n何年も前、奴は大胆な待ち伏せで私を圧倒し、私の弟子を丸呑みにした。弟子を失うことは私にとって珍しいことではないが、その弟子は比類ない大きさと質のarcane shardを持っていたのだ。\n\n強力な仲間を集め、神殿へ潜り込まねばならん。Morphazを倒し、奴の年老いることのない腹からarcane shardを取り戻すのだ。", "私の宿敵を倒したか？", "信じがたい。このshardは長い年月をかけてdrakeの力を吸い取り、成長したのだ。\n\n今やお前に頼むことはもうない。秘術を鍛えるわが力は、このshardとともに完全に戻った。わが最初の創造物はお前のものだ、{name}。あとは選ぶだけだ……", 0xa048a37c, 0x2aa42635, 0x3517d339, 0xaf55bdc0, 0xa8db02cb, "....." },
  [8254] = { "Cenarionの支援", "AzsharaのOgtincを捜し出して下さい。", "困っている者を助けるのが神の道です。どのようにするかは重要ではありません――大切なのは、なぜするかだけです。\n\nCenarion Circleがまさにそのような助けを必要としています。Ogtincと話して、彼らの窮状に力を貸してあげてください。彼はAzsharaのRuins of Eldarathの北東にある崖の上に住んでいます。", nil, "あなたが来て下さって、肩の荷が軽くなりましたよ。やるべきことがたくさんあるのです。", 0x4f3b88f6, 0xc18aa317, 0xcabd114b, nil, 0x4d19dd02, "...m." },
  [8255] = { "無論、ご存じの通り", "Healthy Courser Gland 4つを入手しAzsharaのOgtincに渡して下さい。OgtincはRuins of Eldarath北東の崖の上に住んでいます。", "Azsharaのmosshoof courserは、かつてFelwoodに住んでいた見事な動物です。彼らは生まれつき病気や毒に強く、あの地の汚染にも影響されませんでした。祖先から受け継いだ知恵によって、彼らはただあの病んだ土地を去ることを選んだのです。\n\n心が痛みますが、この力強い獣たちを狩ってきてほしいのです。回復の軟膏の最初の材料として、courser glandsを4つ集めてください――Felwoodを癒すために使う軟膏です。", "戻ったか。うまくいったか？", "神聖な道があなたを我々のもとへ導いてくれたのは良いことです、{name}。あなたの信仰は、この軟膏を作るための務めの妨げにはなりません。\n\nいいですか、courserはCenarion Circleにとって神聖な存在です。どれほど必要であろうと、いかなる理由であれそれらを殺すことは、その魂を弱めてしまうのです。", 0x55179e19, 0x15671a76, 0x184c7352, 0x2d56b41b, 0x17d8db5e, "....." },
  [8256] = { "Ichor of Undeath", "Ichor of Undeathを入手し、AzsharaのOgtincに渡して下さい。OgtincはRuins of Eldarath北東の崖の上に住んでいます。", "この回復の軟膏には、簡単な調合法を使わねばなりません。毒を一、治療薬を二です。治療薬の一つは手に入れました。今度は毒を集めなければなりません。\n\nRuins of Eldarathをさまようhighborneの亡霊のような強力なアンデッドは、時にあまりにも悪に満ちていて、それが病的な緑がかった粘液となって凝固することがあります。生ある者たちには、この物質はichor of undeathとして知られています。\n\nこの邪悪な物質の力は強烈なので、必要なのはichorひとつだけです。", "急いでichorを手に入れねばならん。見つかったか？", "このような嫌な物質を受け取っても嬉しいだなんて言えませんが、これは必要悪ですね。ありがとうございました、{name}。", 0xfcd9e83a, 0x9bed6ac1, 0xa5b0d6ca, 0xe9551c19, 0x8b009b40, "....." },
  [8257] = { "Blood of Morphaz", "Atal'Hakkar神殿でMorphazを殺し、その血をFelwoodのGreta Mosshoofのところへ持ち帰って下さい。沈んだ神殿の入口はSwamp of Sorrowsにあります。", "さて、最後の材料、二つ目の治療薬です。\n\n緑の竜Morphazは、あらゆる毒と病気に対して免疫があることで知られています――この情報をもたらすために多くのドルイドが命を落としました。彼の血が我々の目的に効くことは疑いありません。\n\nあなたが最後の材料を集めている間に、Cenarion Circleの使いが、あなたがすでに集めた材料を運んでくれます。仲間を呼び集め、Atal'Hakkarの沈んだ神殿にある竜の巣を探し出してください。彼の血をFelwoodのGreta Mosshoofのところへ持って行ってください。", "Morphazの血は持っているか？", "あなたはMorphazを討ち、その血を我々のもとへ運んでくれた……この良い知らせが信じられないほどです!\n\n我々はただちに材料を調合し、Felwoodの木々と生き物たちの癒しを始めます。ここで起きたことを元に戻すには一生かかるでしょうが、あなたはそのための手立てを我々に与えてくれました。", 0xd09e0ccc, 0x65b255da, 0x916dae97, 0x3805e63b, 0x15dafe02, "....." },
  [8258] = { "Darkreaverの脅威", "ScholomanceにあるGreat Ossuaryの地下の中心でDivination Scryerを使う。そうすれば、あなたが戦わなければならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出されるので、彼を倒す。\n\nDarkreaver's HeadをOrgrimmar、Valley of WisdomのSagorne Creststriderのところへ持って行って下さい。", "Death Knight DarkreaverはScholomanceのGreat Ossuaryを支配している。奴は霊界を捻じ曲げて意のままにしようとしている。奴を止めねばならん! ここで、あなたが作るのを手伝ってくれたscryerの出番だ。\n\nGreat Ossuaryの地下の中心でdivination scryerを使い、Darkreaverの霊の手下を呼び出すのだ。霊たちを倒せば、あの死の騎士自身が姿を現すだろう。{name}、奴の首を持ってきてくれ! 奴の死によってのみ、霊界に与えられた損害を元に戻せるのだ!", "一刻を争うのです、{name}。Death Knight Darkreaverの脅威を食い止めることはできましたか？", "これは噛みしめるべき勝利だ、{name}! Darkreaverの死によって、霊界を繋ぎ止める脆い枷は取り戻されるはずだ。\n\nそなたは報酬も見返りも念頭になかったときでさえ、求められた以上のことをはるかに成し遂げた。そなたはまことに値打ちあるシャーマンだ、友よ。\n\n霊界を守るために動くこと自体が十分な礼であるべきだとは分かっているが、どうか、このささやかな贈り物を私の感謝とともに受け取ってほしい。", 0xf4f3bcea, 0x03ae7ce9, 0x4c7d637c, 0xc513241d, 0xed58269d, "....." },
  [8259] = { "よりふさわしい報酬", nil, nil, nil, "ああ、{name}……Darkreaverに対するあなたの働きは並外れたものでした。あえて言わせてもらえば、あなたが受け取ったものよりもはるかに良い報酬に値する働きです。どうか、Scholomanceでの功績に対する追加の贈り物として、この兜を受け取ってください。\n\n改めて、ありがとう。", 0x055101fc, nil, nil, nil, 0x45bdd881, ".mmm." },
  [8260] = { "Arathor Basic Care Package", nil, nil, nil, "君は確かに我々に実力を示し始めたね、{name}。報酬として、この支援物資を受け取ってくれ! 中にはArathi Basinの中でだけ使える食料と包帯が入っているよ。\n\nBasinの中で実力を示し続けていけば、これらの品を購入できるようになる。食料は我々との関係がFriendlyになったら、包帯はHonoredになったら買えるようになるよ。", 0x2506a72d, nil, nil, nil, 0x837511ae, ".mmm." },
  [8261] = { "Arathor Standard Care Package", nil, nil, nil, "{name}、確実に力量を示し始めているな。報酬として、この救護パックを受け取ってくれ! 中に、Arathi Basinでのみ使える食べ物と包帯があるはずだ。\n\nArathi Basinで実力を発揮し続ける限り、買って使うことができよう。食べ物は、我々と親しく(Friendly)なれば使うことができる。包帯は称賛(Honored)されるようになった時使えるようになる。", 0xccaf8ee0, nil, nil, nil, 0x837511ae, ".mmm." },
  [8262] = { "Arathor Advanced Care Package", nil, nil, nil, "{name}、確実に力量を示し始めているな。報酬として、この救護パックを受け取ってくれ! 中に、Arathi Basinでのみ使える食べ物と包帯があるはずだ。\n\nArathi Basinで実力を発揮し続ける限り、買って使うことができよう。食べ物は、我々と親しく(Friendly)なれば使うことができる。包帯は称賛(Honored)されるようになった時使えるようになる。", 0x2ff530c9, nil, nil, nil, 0x837511ae, ".mmm." },
  [8263] = { "Defiler's Basic Care Package", nil, nil, nil, "君は確かに我々に実力を示し始めたね、{name}。報酬として、この支援物資を受け取ってくれ! 中にはArathi Basinの中でだけ使える食料と包帯が入っているよ。\n\nBasinの中で実力を示し続けていけば、これらの品を購入できるようになる。食料は我々との関係がFriendlyになったら、包帯はHonoredになったら買えるようになるよ。", 0x7c3e3820, nil, nil, nil, 0x837511ae, ".mmm." },
  [8264] = { "Defiler's Standard Care Package", nil, nil, nil, "君は確かに我々に実力を示し始めたね、{name}。報酬として、この支援物資を受け取ってくれ! 中にはArathi Basinの中でだけ使える食料と包帯が入っているよ。\n\nBasinの中で実力を示し続けていけば、これらの品を購入できるようになる。食料は我々との関係がFriendlyになったら、包帯はHonoredになったら買えるようになるよ。", 0x926dd81b, nil, nil, nil, 0x837511ae, ".mmm." },
  [8265] = { "Defiler's Advanced Care Package", nil, nil, nil, "{name}、確実に力量を示し始めているな。報酬として、この救護パックを受け取ってくれ! 中に、Arathi Basinでのみ使える食べ物と包帯があるはずだ。\n\nArathi Basinで実力を発揮し続ける限り、買って使うことができよう。食べ物は、我々に称賛(Honored)されていれば使うことができる。包帯は尊敬(Revered)されるようになった時使えるようになる。", 0xf5b379ff, nil, nil, nil, 0x803164b2, ".mmm." },
  [8266] = { "犠牲のリボン", nil, nil, "Warsong Gulchで勝利を収めるのが時に難しいことは分かっています。それでも、たとえ勝利に至らなくても、私たちのためのあなたの努力は大切なのです。\n\nWarsong Gulchの試練の1つを達成して勝利できなかったとしても、Ribbons of Sacrificeを受け取れます。それを私のところへ持ってきてください。私たちのために戦ってくれたことに、Sentinelsが報いましょう……たとえ今回は勝てなかったとしても。", "まあ、お前は敗北を前にしても逃げなかった。{name}、お前は踏みとどまった。つまるところ、それこそが真の英雄をつくるものだ。次はきっと勝てるだろう……だがともかく、お前の努力に感謝する。", 0x8ea61f00, nil, nil, 0xe9324b2e, 0xc338822b, ".mm.." },
  [8268] = { "犠牲のリボン", nil, nil, "Warsong Gulchで勝つのが時に難しいことは分かっている。それでも、たとえ勝利に至らなくとも、我々のためのお前の努力は重要だ。\n\nWarsong Gulchの試練の1つを達成して勝てなかったとしても、Ribbons of Sacrificeを受け取れる。それを私のところへ持ってこい。我々のために戦ったことに、Outridersが報いよう……たとえ今回は勝てなかったとしてもな。", "まあ、お前は敗北を前にしても逃げなかった。{name}、お前は踏みとどまった。つまるところ、それこそが真の英雄をつくるものだ。次はきっと勝てるだろう……だがともかく、お前の努力に感謝する。", 0x8ea61f00, nil, nil, 0x61718cce, 0xc338822b, ".mm.." },
  [8270] = { "テスト用コピークエスト", nil, nil, nil, nil, 0xea2a832f, nil, nil, nil, nil, ".mmmm" },
  [8271] = { "Stormpikeの英雄", nil, nil, nil, "Stormpikeの英雄として、この最近略だ……ええと、取り返した宝物からひとつ選んでいいわ。", 0x29b1fe38, nil, nil, nil, 0x32d06266, ".mmm." },
  [8272] = { "Frostwolfの英雄", nil, nil, nil, "{name}、どんな気分だ? 敵を粉砕し、奴らの前線が崩れていくのはどんな感じだ? さぞ気持ちいいことだろうな?\n\n兵士よ、その英雄的功績は讃えられるべきだ。", 0x1e081e68, nil, nil, nil, 0x9dd5ba8c, ".mmm." },
  [8273] = { "Oranの感謝", nil, nil, nil, "これは興味深いわね。この石版を、The HinterlandsのThe Overlook Cliffsにある小さな無人島で見つけたというの、{class}? 実に興味深いわ。<Oranは慎重に石版をしまい、両手をこすり合わせる。>\n\nこの件でのあなたの尽力に感謝するわ。我らがDark Ladyもこの発見をたいそうお喜びになるでしょう。さあ、それに見合った報酬を渡しましょう。", 0x9612f92a, nil, nil, nil, 0xd46b2373, ".mmm." },
  [8274] = { "討伐テストクエスト", "Murlocを5体倒し、testキャラクターのところへ戻る。", "時間はあるかい？ Murlocsを何匹か倒してくれたら、何かピカピカのものをあげるよ！", nil, nil, 0x2cbcf304, 0x00bf1e49, 0xa551eef6, nil, nil, "...mm" },
  [8275] = { "Silithus奪還", "SilithusのCenarion HoldにいるWindcaller Proudhornと話して下さい。", "Allianceの英雄たちよ、傾聴せよ！silithidの脅威はあまりにも長く放置されてきた。まともな抵抗を受けることもなく、奴らはこの間ずっと大規模な拡大の準備を進めてきたのだ。\n\nCenarion Circleの部隊がこの忌まわしき生き物どもに戦いを挑むためSilithusに集結しつつあり、戦える冒険者はみな、ここに我々への参加を求められている！\n\n手遅れになるまで待ってはならない！Azerothの防衛に力を貸してほしい！詳しい指示はCenarion HoldのWindcaller Proudhornから受けてくれ！", nil, "素晴らしい、silithidとの戦いへの呼びかけに応えた新たな志願者ですね。Cenarion Holdへようこそ、{class}。我々の使節の言葉が、あなたほどの力量を持つ英雄たちに届いているのを嬉しく思います。ここでの我々の活動を手伝う機会には事欠きませんし、あなたはすぐに我々の大義にとって貴重な味方であることを証明してくれるでしょう。", 0x1f4019a6, 0xdd40063b, 0x86d6a1fd, nil, 0xe3b065a1, "...m." },
  [8276] = { "Silithusへ取って返す", "SilithusのCenarion HoldにいるWindcaller Proudhornに話しかけて下さい。", "聞いてくれ、Hordeの英雄たちよ! 我々が非常に長いこと挑まずにきてしまった脅威がある。Azeroth中にあるsilithidの巣穴近くの地中からする地響きは、勢力拡大に備えて奴らが大移動をすることを警告している。\n\n手遅れになる前に戦いを仕掛けるべく、Cenarion Circleの戦士たちはSilithusに集まっている! 奴らに我々の地を蹂躙させるな!\n\n戦うことのできる戦闘員は全員、Cenarion HoldのWindcaller Proudhornの指示を仰げ! silithidを征服するのだ!", nil, "素晴らしい。対silithidの招集に応えて新しい戦士がやって来てくれた。Cenarion Holdへようこそ、{class}。我々の使者の言葉が、君のような大物の英雄に届いたと知って嬉しいよ。我々の取り組みを助ける機会が足りなくなることはないし、君が役に立つ協力者だということはすぐに証明されると思うよ。", 0x1f4019a6, 0xdd40063b, 0xbcb39090, nil, 0xe3b065a1, "...m." },
  [8277] = { "致死性の毒", "SilithusのCenarion HoldにいるBeetix Ficklespraggは、Stonelash Scorpid StingerとSand Skitterer Fangをそれぞれ8個集めてくるよう求めています。この仕事を終えたら、彼女のところへ戻って下さい。", "Beetix Ficklespraggがご用を伺うわよ! 従兄弟のNoggleは、Cenarion Holdの錬金術師のために、貴重な薬草を集めて生計を立てているの。少なくとも、前まではね。彼は強い毒に犯されて旅から帰ってきたの。\n\n毒の回りをなんとか遅らせているんだけど、完全に中和するには、彼を刺した何かから採取した毒のサンプルが必要なのよ。\n\nNoggleは北からやって来たわ。だから、stonelash scorpidかsand skittererが刺したに違いないわ。毒針と毒牙をいくつか持ってきてちょうだい。そうしたら、彼に解毒剤を作ってみるわ。", "サンプルはもう集め終わった？今すぐにでもNoggleを失うかもしれないんだ！", "幸運を祈るわ、我が友よ! これでNoggleを救える!", 0xafbb460e, 0x6d92e050, 0xcbe8ea80, 0xf863dda3, 0xf920ed97, "....." },
  [8278] = { "Noggleの最後の希望", "SilithusのCenarion HoldにいるBeetix Ficklespraggは、Stonelash Pincer Stinger・Stonelash Flayer Stinger・Rock Stalker Fangをそれぞれ3つ集めてくるよう求めています。", "畜生! 解毒剤が効かなかったわ。Noggleは遙か南のもっと強い生物に刺されたに違いないわね。\n\n{name}、あそこへ行って、もっとサンプルを集めてくるようお願いするつもりよ。毒はとても強いから、そうたくさん頼まなくていいのが不幸中の幸いね。でも残念なことに、南部一帯には多種多様な有毒生物が徘徊しているから、あなたはたくさんの虫から毒を抽出しなくてはならないの。", "Noggleを救う最後のチャンスだ！急いで！", "やった! これは効きそう、Noggleが意識を取り戻してきたわ。あんたには本当に世話になったわ!", 0x6331e1ef, 0x4a6d3253, 0xe2d69c0b, 0x048affa9, 0xe66a1541, "....." },
  [8279] = { "Twilight Lexicon", "SilithusのHermit OrtellにTwilight Lexiconの章3冊を渡して下さい。", "Twilight's Hammerはその地位を捨てた者に対して優しくはない。今まで奴らは、私のことを獣か何かのように狩ろうとしたんだ! 奴らの敵が私の味方なのは、言うまでもない!\n\nこの粘土板を解読するには、奴らが記述したものを謎めいた文章に変えるのに使う本が必要だ。すなわち、Twilight Lexiconだよ。別々の場所へ3章に分けて保管するくらい重要な物なんだ! 辞書の携帯を許されるほど信頼の篤い士官は、Twilight Keeperとして知られている。Twilight's Hammerの野営地で奴らを探してくれ。", "誰だ？ああ、君か！Lexiconの章はもう全部見つかったか？", "そう! それが例の本の各章だ! それじゃ始めようか、{name}。\n\n三番目の言葉を第二章の言葉に置き換えて……それ以外の言葉を第一章から置き換えて……。ありゃ、逆だったか?", 0x31492787, 0xfa573691, 0x87edb9b3, 0xd824fe46, 0xf034556e, "....." },
  [8280] = { "補給線の確保", "SilithusのCenarion HoldにいるWindcaller Proudhornは、Dredge Striker15匹を殺すよう求めています。", "Cenarion Holdは戦略上最も重要な場所に位置している。ここを確保している限り、silithidに対する勝利は保証されるものと確信している。供給の流入が保たれるならば、砦も保つことができよう。\n\n我々の補給隊にとって、砂漠のワームはsilithidそのものよりも脅威となることが分かった。今朝方、morrowgrainの大きな積荷がdredge strikerの群れによって破壊されたのだ。奴らの数を減らし、我々の供給が脅かされることのないよう守ってほしい。", "dredge strikersは深刻な脅威だ。すぐに対処しなければならん！", "心から君に感謝する。Cenarion Holdを助ける君の働きは、真の勇気を示してくれた。", 0x9beca3f1, 0x3760efd5, 0xfceead9a, 0x939bd353, 0x0f753506, "....." },
  [8281] = { "安全強化", "SilithusのCenarion HoldにいるWindcaller Proudhornは、Dredge Crusherを20匹退治するよう求めています。", "今のところ、君の業績はまさしく他の模範となるべきものだ、{name}。しかし、供給線の安全はまだ完全なものになっていない。dredge strikerがいなくなった間に、奴らより大きい南の同種族が取って代わって、確実に北へやって来るだろう。\n\n奴らを食い止めるにはdredge crusherを大量に殺さねばならないだろうが、供給線の安全を成り行き任せにすることはできん。", "dredge crushersは深刻な脅威だ。直ちに対処しなければならん！", "素晴らしい! silithidとの戦いに備えるにあたって、君が役に立つ協力者であることが証明されたのだ。", 0x57b863d9, 0xd662778f, 0x87d024ec, 0x0478e803, 0x607c7381, "....." },
  [8282] = { "紛失したNoggleの鞄", "Silithusの南にある山からNoggle's Satchelを取り戻し、Cenarion Holdにいる彼に返して下さい。", "ここはどこ? オレの鞄は? ハッ……巨大なscorpidのDeathclaspから逃げてる間に無くしたんだ。慌てて逃げたから、stonelash flayerの巣へ立ち入ってしまったんだよ。\n\nオレが運んでた鞄の中には、たくさんの貴重な試薬が入っていたんだ。あれが無かったら、オレとBeetixはCenarion Holdが必要としてるポーションを作れなくなってしまうよ。オレは起き上がるにはまだ弱りすぎだ。でも、試薬を持ち帰ってきてくれたら、君の役に立つものを作ってあげられるよ。\n\nBronzebeard's campの後ろにある、南部山脈でDeathclaspに出くわしたんだ。", "まだ俺の鞄は見つからないのか？まあ、ツイてたと思うべきだな。少なくとも毒は抜けたんだから。", "やったぞ! 鞄を取り戻してくれたね。それに、貴重な試薬も全部ここに揃ってる! ずっと恩に着るよ。", 0xeeeb4950, 0xea6a7314, 0x5a1c0e0e, 0x8a6d5d7b, 0xc1d43b95, "....." },
  [8283] = { "お尋ね者　砂漠の恐怖Deathclasp", "警備隊長Vish KozusにDeathclasp's Pincerを渡して下さい。", "恐るべきscorpidのDeathclaspは、活動を増すsilithidの存在によって南部山脈一帯へ追いやられたものと思われる。Deathclaspの存在は、南部地方における警備隊や派遣部隊の大いなる脅威である。Deathclaspの殺害に参加した者は、大いに報いられるであろう。報酬に関しては、Cenarion Hold監視塔の最上階にいるCaptain Vish Kozusに尋ねること。", "やり遂げた証拠に、その怪物のpincerが必要だ。pincerがなければ報酬もなしだ。", "素晴らしい! Deathclaspが死んだことで、silithidの巣を回避する戦略上の道として南部山脈一帯を自由に使えるのだ。君の働きは非常に高く評価されている。", 0x1653fede, 0xc66271b7, 0x2223e285, 0xe70b5da7, 0x42eb7ffd, "....." },
  [8284] = { "夕闇の謎", "SilithusのCenarion HoldにいるGeologist Larksbaneは、Twilight Tablet Fragmentを8個集めるよう求めています。", "Twilight's Hammer狂信者のキャンプは、かつてここの北西で栄えていました。今あそこへ行けば、キャンプの名残が点在し飛び散った木のかけら以外には何もない、精霊が行き交う地を見るでしょうね。\n\nそこからいくつか粘土板を回収してきましたが、繋ぎ合わせて役立ちそうな物にするには、もう少し必要です。粘土板の残骸を見つけることができれば、SilithusにいるTwilight's Hammerの存在の謎を解明することができます。", "荒らされた野営地はここから北西にある。fragmentsを全部集めたら戻ってこい。", "まさに期待通りですね。粘土板にあるそれぞれの言葉を解読することはできますが、何らかの論理か意味が抜け落ちているようです。\n\nTwilight's Hammer教団が文章の意味を隠すために暗号を用いているのは明らかです。こういったことに詳しい人物のところへ行かねばなりませんね。", 0x36071092, 0x829f9721, 0xd9ad7936, 0x1f849a86, 0x45153e0e, "....." },
  [8285] = { "脱走兵", "修復した粘土板をSilithusのHermit Ortellのところへ持って行って下さい。", "Twilight's Hammerのメンバー、Ortellという脱走兵の噂があるのです。その噂はこういうものです。彼はSouthwind Villageの南の山に隠れていて、そこで彼は隠遁者として生きていると。この粘土板の解読に、彼の助けが得られると思います。\n\n修復した粘土板を持って行き、Ortellを探し出して下さい。", "お前！どうやって私を見つけた？何者だ？つけられてはいないだろうな？答えろ！", "君は俺が以前所属していた組織と馴染みがあるね。Cenarion Holdの一員なんだろう?\n\n彼らに対抗するための情報を探してる? 近くに来な、俺たち互いに助け合えると思うぜ。", 0xb731c8c4, 0x06d22d8c, 0x8810ae3f, 0xa4e24d3c, 0x12c99ec1, "....." },
  [8286] = { "明日がもたらすもの", "TanarisのCaverns of Timeへ行き、Brood of NozdormuであるAnachronosを見つけて下さい。", "死の抱擁が私の存在をほとんど飲み込もうとしていたとき、彼が現れたのだ。彼は私の傷ついた体に一度だけ息を吹きかけ、それから時の砂が私の傷を清めるのを辛抱強く待った。\n\n「必要ならば、そなたは永遠に留まるのだ」と彼は言った。その言葉によって、私はWatcherとして縛られたのだ。\n\nさあ、砂漠に目を向けよ。第二の戦いが我らに迫っている。Bronzeの眠る場所を探し出さねばならぬ。Caverns of Timeへ赴き、主が戻られたかどうか確かめてくるのだ。先へ進むには、私は確信を得なければならぬ。", "Anachronosは戻ったか？", "あるべき姿になった……偉大なる存在が蘇った。私が見守るのも終わりに近づいたのだな……", 0xcc6f8727, 0xf7f61fb2, 0xd34a0765, 0xbac5c038, 0x1a25433c, "....." },
  [8287] = { "恐ろしい目的", "Decoded Tablet ParchmentをCommander Mar'alithに渡して下さい。", "よし、これが……極めて重要な情報の山だ。本当にな! SilithusにCenarion Circle軍が到着するのを見たぞ。Twilight's Hammerを駆逐する計画じゃないかな? この情報は助けになるだろう。\n\nこの文書を君らの指導者、Commander Mar'alithに持って行ってくれ。Twilight's Hammerはすぐ制圧されるだろうな。そうすれば、私は永遠に奴らの支配から逃れられるんだ!", "私に持ってきたそれは何だ、{name}？", "実に興味深い情報だ、{name}。これはSilithusにいるTwilight's Hammerの存在の謎を解き明かすのに役立ち、間違いなく我々の戦いを助けてくれるだろう。君の働きには気前よく報いねばなるまい、{class}。", 0xab3d7b65, 0x56902685, 0x534bf238, 0x69bfaecc, 0x0f045752, "....." },
  [8288] = { "立ち上がれるのはただひとり", "Head of the Broodlord LashlayerをSilithusのCenarion HoldにいるBaristolth of the Shifting Sandsに渡して下さい。", "無駄にする時間はない! 英雄を見つけねばならぬ! 私が与える任務を果たすには軍勢が必要となるが、Broodの盟友としての重荷と責任を担うために、勇者を志す群衆の中から立ち上がれるのはただ一人だけだ。\n\nBlackrockの主の巣の中に、この上なく残忍な獣がいる。Broodlord LashlayerがHalls of Strifeを守り、Nefarianの奥の聖域への道を塞いでいるのだ。その忌まわしい異形を倒し、奴の首を私のところへ持ち帰るのだ。これを成し遂げれば、そなたは旅の次の段階を始められよう。", "そなたが得ねばならぬのは、Brood of Nozdormuの信頼だ。", "Bronze Flightの信頼を千年間で初めて得る者となってくれるか?", 0x2d7c676a, 0x9626bfb8, 0x2526ea32, 0x7256fa21, 0xc23d3c6a, "....." },
  [8290] = { "侵略者を打ち破れ", "Warsong Gulchに入ってHordeを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、talisman of meritを手に入れなさい。そのtalismanを私のもとへ持ってくれば、{name}、報酬を与えましょう。", nil, nil, 0x877db1ee, 0xfeb46d9a, 0xd5134582, nil, nil, "...mm" },
  [8291] = { "侵略者を打ち破れ！", "Warsong Gulchに入ってHordeを打ち負かし、Silverwing Talisman of Meritを手に入れて、Silverwing GroveのSentinel Farsongのところへ戻って下さい。", "このトンネルの先には、争いと混乱の戦場が広がっています、若き{class}よ。Hordeは我らの聖なる森を荒らし続け、戦争の機械を動かすために常緑の木々を切り倒しているのです。\n\nWarsong Gulchに入り、Silverwing Holdを守りなさい。侵攻してくるHordeの軍勢を押し返すのです！\n\nこれを成し遂げ、talisman of meritを手に入れなさい。そのtalismanを私のもとへ持ってくれば、{name}、報酬を与えましょう。", "Warsong Gulchで戦い、Silverwing Holdを守ってきたか?", "お前はWarsong Gulchでの我々の戦いにおいて、その価値を証明した。これからも大義に力を貸し、さらにMarks of Honorを持ってくるのだ。そうすれば、我々の信頼をさらに得られるだろう。", 0x55520e44, 0xbdddd230, 0xd5134582, 0x71ff749c, 0xf9915c4e, "....." },
  [8294] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Warsong mark of honorを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。", "敵の血こそがmark of honorだ。お前はそのmarkを持っているか?", "<Captain Shatterskullは勝利の雄叫びを上げる>\n\n奴らはあとどれだけ耐えられる? Hordeの手でどれだけのAllianceのクズどもが死ねば、奴らは退くのだ? それは時が教えてくれるだろう、{race}……", 0x636625b4, 0x3df29510, 0x2eb6ef0c, 0xd1cff4b7, 0x160777a5, "....." },
  [8295] = { "Silverwingの簒奪者の鎮圧", "Warsong Gulchに入ってAllianceを打ち負かし、Warsong Gulch Mark of Honorを手に入れて、Mor'shan Base CampのCaptain Shatterskullのところへ持って行って下さい。", "Ashenvaleの森の荒野は、Hordeの力に屈するのだ、{race}。Silverwingが何を言おうと何をしようと、我らの至上の使命を止めることはできん。KalimdorはHordeのものだ。当然我らのものであるものを刈り取るのを、奴らはよくも邪魔しようとするものだ！\n\n奴らが我らの前進を遅らせようとするひ弱な試みを切り崩しながら、胸に誇りをみなぎらせるがいい。Silverwing Sentinelsを倒し、Warsong mark of honorを手に入れろ。その印を持って戻ってくれば、{name}、報酬を与えよう。", nil, nil, 0x636625b4, 0xc94c2293, 0x2eb6ef0c, nil, nil, "...mm" },
  [8297] = { "Arathi Basinの資源！", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、Refuge PointeのSergeant Maclearのところへ持って行って下さい。", "戦争は兵士で戦うものだ。兵士なら誰でもそう言うだろう。そして兵士はこうも言う。粗末な装備や空きっ腹で挑む戦いは、始まる前から負けているとな！\n\nだからこそArathi Basinが重要なのだ。あの盆地には欠かせない資源を抱える要所がいくつかある。金属、武器、食料、木材――どれもが必要で、どれもがあそこで手に入る。\n\nそれが君に頼みたいことだ、{name}。Arathi Basinへ入り、敵より多くの拠点を押さえて戦いに勝ち、資源の木箱を持って私のもとへ戻ってこい。", "Marks of Honorは持っているか、{name}？League of Arathorはそれがなければまともな戦いもできないのだ……", "Markを手に入れたんだな! よくやった! 資材は補給係に送っておこう。すぐに部隊へ配ってくれるはずだ。\n\nありがとう、{name}。まさに、君が成し遂げたような作戦を成功させることこそが、戦争に真に勝つ方法なんだ。", 0xa6f22932, 0x982ec307, 0xfe0a59ea, 0x37247045, 0x2c6df8ea, "....." },
  [8299] = { "Arathorの補給線遮断", "Arathi Basinの戦いに勝ち、Arathi Resource Crateを手に入れて、HammerfallのDeathstalker Mortisのところへ持って行って下さい。", "League of ArathorはArathiを奪還するため、費用を惜しまず動いている。彼らとAllianceのあらゆる種族が、今この遠い地へ続々と押し寄せ、Refuge Pointeから支配を広げようとしているのだ。我々は奴らを止めねばならん。そして奴らを止める最善の手は、その物資を奪うことだ。\n\n君の力を貸してくれ、{name}。豊かな鉱山、肥沃な土地、腕の立つ職人で知られるArathi Basinへ入るのだ。奪えるだけの拠点を奪って守り抜き、戦いに勝ち、手に入れた資源を持って私のもとへ戻ってこい。", "何だ、{race}？Marks of Honorは持っているのか？Arathi Basinに戻り、Allianceの害虫どもを殺して、Dark Ladyのためにその資源を奪い取れ！", "<Deathstalker Mortisは微笑む>\n\n我らの敵にまたひとつ決定的な打撃が加えられた、{name}。君の働きのおかげで、Arathi BasinはまもなくDefilersの手に落ちるだろう。", 0x7b8482f8, 0x81501782, 0xd18465ad, 0xd916acfe, 0x18a5b9a3, "....." },
  [8301] = { "正義の道", "Silithid Carapace Fragmentを200個集め、Baristolthのところへ戻って下さい。", "Brood of Nozdormuは生まれつき劣った種族を信用しない。そなたが英雄となる素質を持っていることは私に証明してみせたが、今度はそれを我が主に証明する時が来たのだ。\n\nHive'Ashi、Hive'Zora、Hive'Regal:どれも活気に満ち、どれも我らの存在を脅かしている。これらの巣でsilithidを倒し、その甲殻の破片を奪ってくるのだ。これ以上持てなくなったら私のところへ戻れ。そなたの決意を強めてやろう。", "定命の種族を信用しないその心には、長い歴史の根がある。だが残念ながら、それは時が来たときにBroodが語るべき物語だ。", "お前はひとりではない、英雄よ。探索を助ける代理人を任命する能力を与えてやろう。一族の戦士となれば、任務や責務を支える者が必要になるだろう。", 0xf26e0d53, 0xff84c0eb, 0xc53eafdd, 0xb2f9b35d, 0x13bca8e3, "....." },
  [8303] = { "古代竜Anachronos", "TanarisのCaverns of TimeにいるAnachronosを探し出して下さい。", "時が来たのだ、{name}。\n\nこれほど多くのことを秘密にしてきたことを詫びねばならぬ。敵はあらゆるところに、我らのすぐ目の前にさえいるのだ。どうか、この書を読んで学んでくれ。私が与える知識を携え、我らの主を探し出すのだ。", nil, "お前はKalimdorの希望だ、{name}よ。", 0x822118f5, 0xcdc07b9b, 0x3578c621, nil, 0x9baa6b7d, "...m." },
  [8304] = { "最愛のNatalia", "SilithusのCenarion HoldにいるCommander Mar'alithは、Bronzebeard's Encampmentの住人に問いかけるよう望んでいます。Bronzebeard's EncampmentはCenarion Holdの南で見つかるでしょう。\n\n求めていた情報が集まったら、Commander Mar'alithのところへ戻って下さい。", "愛するNataliaが行方不明になってしまった。\n\n実は、失踪へと繋がる何週間かの間、彼女はおかしな行動をとっていたのだ。周囲に誰もいない時に彼女が独り言を言っているのを、一度ならず見かけたのだ。彼女はすべて上手くいっているから自分の研究を続けさせてくれと言い張った。\n\n彼女が最後に目撃されたのは、南のBronzebeardのキャンプへ向かう姿だった。\n\n{name}、我が兵士たちはあまりに広く展開しすぎている。Bronzebeardのキャンプへ行って、そこのドワーフたちに尋ねてきてほしい。", "時を無駄にするな、{name}!", "<Commander Mar'alithは考えに深く沈み、うなだれている。>\n\n彼女が生きているにせよ死んでいるにせよ、私は正しいことだけを行わねばならない。彼女を見つけなくては。ああ……私はこの前哨を離れることはできぬ。もう一度、私を助けてはくれないだろうか、{name}。", 0x58c44a73, 0x84359a18, 0x70d8d99d, 0x134e1531, 0x45e4d791, "....." },
  [8305] = { "久しく忘れられた記憶", "SilithusでCrystalline Tearを見つけ、その奥をのぞき込む。", "Silithus南部の砂漠、聖なる障壁の近くに、水晶の涙がただ一つ存在する。この涙は、War of the Shifting Sandsの間に我々を襲った大きな喪失の象徴なのだ。この涙を見つけ、その奥深くを覗き込んで悟りを得るがいい。", nil, "この水晶の周りに大きな悲しみが渦巻いているのを感じる。その力はあまりに強く、悲しみのあまり崩れ落ちて死んでしまいそうに感じる。", 0xcf17fd6d, 0xceca852c, 0xa70f56fe, nil, 0x6eaab3a2, "...m." },
  [8306] = { "狂気の顎へ", "SilithusのCenarion HoldにいるCommander Mar'alithは、愛するNataliaを見つけるよう望んでいます。あなたが集めた情報は、Mistress Natalia Mar'alithが南のHive'Regalにいることを示しています。そこでMistress Natalia Mar'alithを見つけることができるでしょう。\n\n巣穴へ挑む前に、Bronzebeard's campのドワーフのところを訪ねるのを忘れないで下さい。あなたに別の仕事とアドバイスをくれるはずです。\n\n{name}、司令官の言葉を覚えておいて下さい。「成すべき事をせよ……」", "Hive'Regalへ入って、最愛のNataliaがどうなったか調べてくれ。{name}。ひとりでは容易い任務ではなかろう。仲間を何人か連れて行くといい。あの狂気の顎へ飛び込む前に、かのドワーフたちのところへ戻って話すのを忘れずにな。巣に生息するsilithidの対処について、いくつかヒントをくれるだろう。\n\nそれから{name}、もし彼女が彼らの言うように狂っていたのならば……成すべきことをせよ。\n\n<Commander Mar'alithはあなたに背を向けた。>", "Nataliaは?", "<Commander Mar'alithは自分の胸ぐらを掴んだ。>\n\nC'Thunだと? それは一体何なのだ? C'Thunとは何だ? その悪魔はどうやって愛しいNataliaを君の言うような化け物へ変えたというんだ?", 0x92ee9669, 0x7e346e82, 0x892f7d43, 0x898460ac, 0x0a355935, "....." },
  [8307] = { "砂漠のレシピ", "Cenarion Holdの西にあるTwilight's Hammerのキャンプで、Sandworm Meatの調理法に関する情報を見つけて下さい。", "砂漠生活への適応は、控えめに言っても困難なものです。Auberdineの木々や鳥たちを恋しく思うだけでなく、この不毛の環境のせいで食べ物の選択肢もひどく限られているのです。砂漠の薬草について学ぼうとしたのですが、薬草も多くはありません。\n\nこの西にあるTwilight's Hammerの集団が、食用にsandwormを狩っているのを見たことがあります。でもSandwormの肉はとても苦くて、彼らがどうやって口に合うようにしているのか見当もつきません。彼らのキャンプへ行ったら注意して探し、何か学んだら教えて下さい。", nil, "この本にはいくつかの一般的なレシピと少し変わったレシピが載っている。少し参照すれば、Sandworm肉に関するレシピを見つけられる。", 0x7843e85a, 0x74626aa7, 0x3f91f730, nil, 0x0a87d34d, "...m." },
  [8308] = { "Brann Bronzebeard's Lost Letter", "Brann Bronzebeard's LetterをSilithus南部のBronzebeard's Encampmentへ持って行って下さい。", "関係者各位  もしこれを読んでいるのなら、私は死んだか、あるいはもうすぐ死ぬだろう。何とも言えないが、仲間のほとんどはとにかく死んだ。\n\nタイタンに関する情報を見つけた。タイタンと古き神々との間に起きた大戦争。そう、正真正銘の古き神だ。Ahn'Qirajへ通じる古代のトンネルを見つけたのだ。そこを通って行く。\n\nこの手紙を私の古いキャンプへ持って行ってくれ。私の猿が充分な食べ物と飲み物をもらい、抱擁を受けているか確かめて欲しい。\n\nBrann Bronzebeard、Explorer Extreme  追伸　狂った古き神を崇拝するナイトエルフには気をつけろ", "おやまあ。", "なるほど、これで多くのことに説明がつく。もしAhn'Qirajへ入る方法を見つけたら、Brannの奴に目を配っておいてくれ。あいつは猿がいなけりゃ何もできないんじゃないかと心配だ。", 0x56f9f5ee, 0x21723bc0, 0x7ece6adf, 0x9e26ead5, 0x9eac4d41, "....." },
  [8309] = { "象形文字の拓本", "SilithusのBronzebeard's EncampmentにいるRutgar Glyphshaperは、Hive'Ashi・Hive'Zora・Hive'Regalへ行って、それぞれの巣穴でGlyphed CrystalからGlyphed Rubbingsをとってくるよう求めています。\n\n古代象形文字の適切な複製を作るため、Geologist's Transcription Kitを使って下さい。この仕事を完了したら、Rutgar Glyphshaperのところへ戻って下さい。", "巣への最初の突入と、それに続くMistress Mar'alithの錯乱以来、3つの巣から虫がどんどん湧き出してきている！活動が増えたのは、あの奇妙な水晶を覆っている紋様と関係があるのかもしれない。\n\n3つの巣すべてで、水晶の拓本を取らなければならない。その拓本が手に入れば、この狂気の意味がわかるかもしれない。\n\nこの写し取り用の道具一式と仲間を何人か連れて、巣に乗り込んでくれ、{name}。すべての巣から写しを取るまで戻ってくるなよ。", "巣のどこかで頭のおかしいナイトエルフの娘を見かけたら、俺たちの分までケツを蹴っ飛ばしてやってくれ。", "この象形文字はさっぱり理解できん。こんなものは見たことがない! Frankalの研究がこのわけの分からんものを解明するきっかけになってくれればいいんだが。", 0x259096b4, 0xb9b32741, 0x18f11d97, 0x68af550c, 0x5b85f00d, "....." },
  [8310] = { "暗号破り", "SilithusのBronzebeard's EncampmentにいるFrankal Stonebridgeは、Hive'Zora Silithid Brain・Hive'Ashi Silithid Brain・Hive'Regal Silithid Brainを見つけるよう求めています。この任務を完了したら、Frankalのところへ戻って下さい。", "silithidやQirajiの象形文字や言語をもっと容易に解読できるようにしてくれる万能薬を、作り出せると思う! 何が必要かって? よくぞ聞いてくれた! 脳みそが必要なんだよ! もっと具体的に言うと、巣穴に住むsilithidの種類ごとの脳だ。脳を持ってきてくれれば、Rutgarの成果も無駄にはなるまい。", "猿とでも遊んでな、坊主。こっちはそんな暇はないんだ。", "素晴らしすぎる! 小僧、あまり遠くへいって迷子になるなよ。もうひとつふたつ、別の仕事に取りかかってもらわなきゃならない。", 0xd4cb0cb3, 0x3f424a96, 0xd70a8818, 0xbce22f01, 0x08090859, "....." },
  [8311] = { "JesperにHallow's Endのお菓子を!", "Stormwind・Ironforge・Darnassusの宿屋の主人に話しかけて下さい。IronforgeにいるTalvash del Kisselにも同様に話しかけて下さい。彼らが依頼してくる芸をして、代わりにお菓子をもらって下さい。Stormwind OrphanageにいるJesperのところへ、Darnassus Marzipan・Gnomeregan Gumdrop・Stormwind Nougat・Ironforge Mintを持ち帰って下さい。", "お菓子をねだりに行きたいんだけど、病気で行けないんだ。もし僕の代わりに行ってくれたら、もらったキャンディと交換してあげる! {name}はこのキャンディ好きだと思うよ……おかしかったり、怖かったり、いろいろ変わるから!大きな街にいる宿屋の人がそれぞれHallow's Endのキャンディをくれるんだ。話しかけて、頼まれた芸をしてね! それと、IronforgeにいるTalvashって名前の小さなノームがよくキャンディを配ってるよ。キャンディを全部集めたら、僕のところへ持ち帰ってきてね!", "お菓子集めはもう終わった? 私は病気で行けなくて悲しいけれど、あなたが手伝ってくれるおかげで少しだけ気分がよくなるの……", "うわあ、全部集めてくれたんだ! {name}最高!僕の代わりにお菓子をもらいに行ってくれてありがとう。これ、カボチャのお菓子持って行って。すっごく好きだと思うよ、これ!楽しいHallow's Endを、{name}!", 0x52c1029c, 0xf583861b, 0x4f387161, 0xee372d69, 0xc67a4faf, "....." },
  [8312] = { "SpoopsにHallow's Endのお菓子を!", "Orgrimmar・Undercity・Thunder Bluffの宿屋の主人に話しかけて下さい。Sen'jin VillageにいるKali Remikにも同様に話しかけて下さい。彼らが依頼してくる芸をして、代わりにお菓子をもらって下さい。Orgrimmar OrphanageにいるSpoopsのところへ、Thunder Bluff Marzipan・Darkspear Gumdrop・Orgrimmar Nougat・Undercity Mintを持ち帰って下さい。", "お菓子をねだりに行きたいんだけど、病気で行けないんだ。もし僕の代わりに行ってくれたら、もらったキャンディと交換してあげる! {name}はこのキャンディ好きだと思うよ……おかしかったり、怖かったり、いろいろ変わるから!大きな街にいる宿屋の人がそれぞれHallow's Endのキャンディをくれるんだ。話しかけて、頼まれた芸をしてね! それと、Sen'jin VillageにいるKali Remikって名前のトロルがよくキャンディを配ってるよ。キャンディを全部集めたら、僕のところへ持ち帰ってきてね!", "お菓子集めはもう終わった? 私は病気で行けなくて悲しいけれど、あなたが手伝ってくれるおかげで少しだけ気分がよくなるの……", "うわあ、全部集めてくれたんだ! {name}最高!僕の代わりにお菓子をもらいに行ってくれてありがとう。これ、カボチャのお菓子持って行って。すっごく好きだと思うよ、これ!楽しいHallow's Endを、{name}!", 0x356246fa, 0xb4c3c494, 0xc588d4fb, 0xee372d69, 0xc67a4faf, "....." },
  [8313] = { "知識の共有", "Cenarion Holdの宿屋にいるCalandrathにTorn Recipe Pageを渡して下さい。", "sandworm肉調理のレシピは判読可能だが、聞いたことのない薬草と香辛料の記述を含んでいる。Calandrathならば、砂漠に生える植物を理解するだけの知識を充分持っているだろう。", "レシピは覚えたかい? 独り占めはしないでくれよ!", "見てみましょう……。\n\nかなり単純なようですね。一部の薬草には独自の名前があるようですが、理解するのは簡単です。\n\nさあ、お見せしましょう!", 0x7d8138bc, 0xc1449f9f, 0xe87c28b0, 0x91af6a8c, 0xde68a832, "....." },
  [8314] = { "謎の解明", "Bronzebeard's EncampmentのRutgar Glyphshaperは、SilithusのCenarion HoldにいるGeologist LarksbaneのところへGlyphed Crystal Prismを持って行くよう求めています。", "{name}、我々は突破口を見つけたようだ! あんたが回収してきた拓本のおかげで、この水晶の結晶に刻まれた象形文字を再現することができた。これはどうやら、Qirajiとその他の知られざる存在が、様々なメッセージをsilithidに伝える手段らしい。\n\n残念だが、我々が理解できたのはこれで全部だ。この水晶に秘められたメッセージの謎を解く方法を見つける必要があるな。\n\nこの象形文字の施された水晶をCenarion HoldのGeologist Larksbaneのところへ持って行け。彼女なら助けになるはずだ。", "おやまあ! そこに持っているのは何ですか、{name}?", "あのドワーフたちがこの象形文字を解読できなかったのは、解読すべきものが何も無いからですよ。ちゃんと意味が通るように水晶の中の模様と並ぶよう、この結晶の表層を動かさねばなりません。巧妙ですね……。\n\nこの資料を解読せねばなりませんが、最初に暗号の解明をしなくては。この結晶の表面にある物だけが唯一の手がかりです……拓本が正確に転写されているならば、ですが。これはかなり厳しいですね。", 0x315cbd5b, 0xc8213121, 0x24ba33a6, 0x7bcfced9, 0x62edee0d, "....." },
  [8315] = { "召喚", "SilithusのCenarion HoldにいるGeologist Larksbaneは、Qiraji EmissaryからCrystal Unlocking Mechanismを取り戻してほしいと言っています。\n\nGlyphs of CallingをCenarion Holdの南にあるBones of Grakkarondへ持って行き、砂の上に描くよう指示されています。Qiraji Emissaryが現れたらそれを倒し、Crystal Unlocking Mechanismを取り戻して下さい。成功したらGeologist Larksbaneのところへ戻って下さい。\n\nこの任務のために軍勢を集めて下さい、{name}!", "この象形文字は、Qirajiの使者が大きな竜の骨のところで3体のsilithidと会っている様子を描いている。象形文字の上には、何らかの暗号としか思えないものがある。この暗号こそが、使者を召喚する鍵なのかもしれない。\n\nその象形文字の暗号の写しを作ってやろう。お前はそれをBones of Grakkarondの砂の上で使わねばならない。私の考えが正しければ、新しい情報の送信準備ができたと思ってOverlordsがやって来るだろう。奴らを倒し、使者と対峙するのだ。水晶の鍵は奴が握っている……", "機会が訪れたなら、それをつかんで打って出るのだ!", "私は今、20,000年の歴史をこの手に握っているのだ、{name}!", 0x0fadee9b, 0x53eef4e3, 0x39406323, 0x932486cd, 0xcda7abbd, "....." },
  [8316] = { "戦争の兵器", nil, nil, nil, "戦争がやって来ます、{name}。そしてそれと共に、計り知れない恐怖も訪れるのです。あなたは求められうる限りのことをすべて成し遂げました。その報いを受けるべきです。\n\nもし、この……この予言が実現するようなことがあれば……\n\n<Geologist Larksbaneは青ざめる。>\n\n我々すべての未来が終わりを迎えるかもしれません。\n\nこの武具は、この砂漠でのあなたの戦いに計り知れない価値をもたらすでしょう。", 0x9aacc572, nil, nil, nil, 0x7f77ec54, ".mmm." },
  [8317] = { "キッチン手伝い", "Cenarion HoldのCalandrathはSmoked Desert Dumplings 10個を求めています。", "このレシピは確実に便利なものになりますよ。今日用意するSmoked Desert Dumplingsが手に入るよう、取りかかった方がよいでしょうね。少し手を貸してもらえると助かります。お礼はしますよ。", "あのdumplingsの仕上がりはどうだ?", "すごい! あなたは命の恩人です。この肉団子は実に美味しいということが分かりましたよ。本当に、Twilight's Hammerからこんな美味が得られるなんて期待していませんでしたよ。", 0x34700d3b, 0x467ee680, 0x1a909fbf, 0x1999061b, 0x9febcb59, "....." },
  [8318] = { "秘密の連絡", "Cenarion HoldのBor WildmaneにEncrypted Twilight Text10枚を渡して下さい。", "Twilight's Hammer狂信者の一部は、訳の分からないことが書かれたちょっとした書類を持ち歩いている。その書類の束を持ってきてもらいたいのだ、{class}よ。\n\nそのでたらめな物が何を意味するのか私には分からんが、論点はそこじゃない! その書類は個々の集団が密かに連絡する手段なのだ。情報の流れを止めれば止めるだけ、奴らはますます連絡できなくなるということだ!", "textsをいくつか持ってきてくれたか?", "素晴らしい! これは隠しておこう。後で役に立つはずだ。", 0xcc494cd2, 0x5c6002b3, 0xefa328b9, 0x1713c156, 0x59845fa1, "....." },
  [8320] = { "Twilight Geolord", "Twilight Geolordを10人殺し、Cenarion HoldのHuum Wildmaneのところへ戻って下さい。", "Twilight's Hammer……あの狂気の教団は、昼も夜も儀式を行い、Silithusにキャンプを作り、破壊活動に夢中になっている。まだ我々は奴らの計画を知らないが、奴らが脈打つ赤い水晶を砂漠の至るところに設置したのは、何らかの関係があると考えているのだ。\n\nいつか奴らの謎を解かねばならんが、まず始めにその脅威に対処しなければならぬ。西にある奴らのキャンプへ行き、Twilight geolordを探すのだ。奴らはあの悪魔どもの長。我々が攻撃しなければならぬのはそこだ!", "砂漠に入り、Twilightのgeolordどもを見つけ出せ、{name}。奴らを討ち取ったら、私のもとへ戻ってくるのだ。", "いい成果の出た任務だったな、{name}。Twilight geolordの討伐は、あの教団に痛恨の一撃を与えたに違いない。奴らの計画の実行が遅くなることを願おう……", 0x4a8a9dd6, 0xf3c8c0c8, 0x7b7b95be, 0x776cba1a, 0x16794f7f, "....." },
  [8321] = { "Vyral the Vile", "Cenarion HoldのHuum WildmaneにVyral's Signet Ringを渡して下さい。", "我々はTwilight's Hammerのもうひとつの活動拠点を発見した。そこはTwilight's Runと呼ばれる、Silithusの北東の隅に隠された洞窟だ。その教団支部の指導者、Vyral the Vileはその洞窟へ頻繁に出入りしている。君が次に倒さねばならぬのはそいつだ。それを成し遂げたら、奴の印章指輪を持ってきてくれ。\n\n武運を、{name}。Twilight's Runの敵は実に手強いぞ。", "{name}、Vyral the Vileはもう倒したのか? 奴のsignet ringは手に入れたか?", "成し遂げたのだな! Vyralが死んだ! これはSilithusにおけるTwilight Hammerの作戦が決定的に失敗したことに他ならない。まだ動き回っている奴らがいるかもしれないが、今日君が与えた一撃はそう容易く回復できぬだろうよ。", 0xaa8e73ba, 0x5a2d88b7, 0x78859cd1, 0xacfae899, 0x7b7437ca, "....." },
  [8322] = { "Rotten Eggs", "Southshoreの宿屋「Southshore Inn」にある酒樽にRotten Eggsを入れて下さい。", "Southshoreの人間どもはエールが大好きで、だからこそSouthshore Innで出されるエールを大事にしている。Hallow's Endの混乱が奴らに訪れている今、それを利用して奴らの最新の酒を何週間――いや、何か月にもわたって台無しにしてやれるぞ!\n\nこのrotten eggsを持って行き、Southshore Innの中にある主要な醸造樽に入れてこい。お前がそこにいるだけで騒ぎになるだろうから、身を守る覚悟をしておけ!\n\nSouthshoreの連中に当分忘れられない味を味わわせてやったら、ここ祭りの場所にいる俺のところへ戻ってこい!", "その樽はエールで満たされている。", "首尾良く宿の中に侵入して、樽の中に入れてきたのだな。空気にひどい臭いが充満しているのが分かるだろう……", 0x4f60af90, 0x6cdb041f, 0x402db487, 0xa6ca951a, 0xce03c268, "....." },
  [8323] = { "狂信者", "Hermit OrtellはEncrypted Twilight Text 10枚を持ってくるよう求めています。", "Twilight Lexiconが自分のものになった今、ちょっとお願いしたいことがある。\n\n俺が元々いた組織には、月単位で配布する暗号化された秘密の報告書があるんだ。\n\n俺の捜索に進展があったか、あるいは捜索を中止するのなら、指令が「True Believer」で発表されるはずだ。\n\nその情報が俺にとって価値があるのは明らかだけれども、その刊行物に含まれる別の有益な情報を君と共有することができる。Twilight's Hammerのメンバーから見つけた暗号文書を持ってきてくれ。", "encrypted textsは見つかったか? 今月のTrue Believerを読むのが楽しみでならないんだ。", "素晴らしい! できるだけ早くこれを解読しよう。何か面白いことが分かったら、君にこの情報を渡す手段を見つけるよ。", 0x434403a9, 0x9ae5220c, 0x74ecfba2, 0x4afa1bcf, 0xf07c403b, "....." },
  [8331] = { "Aurel Goldleaf", "Cenarion HoldのAurel Goldleafと話して下さい。", "{name}、SilithusにおけるTwilight's Hammerの活動は弱まっていると期待していたが……残念ながら、我々は間違っていた。教団への攻撃を続けるうちに、さらに暗い力、Abyssal Councilが、教団の野営地に点在する秘術のwind stoneを通じてHammerを支配していることが分かった。{name}、あなたの次の行動はAbyssal Councilに対するものとなる。\n\nCenarion Holdの東の区画にいる職人Aurel Goldleafと話してくれ。この次の策略には彼女の技術が必要になる。", nil, "{name}、ご機嫌よう。Abyssal Councilに対抗するとおっしゃったのですか? もしそうなら、これから言うことをしっかり聞いて下さい……", 0x1df6d82e, 0x00d99f06, 0x9ee316b2, nil, 0x5b91bb58, "...m." },
  [8332] = { "深淵の大公", "Large Brilliant Shard1つとAbyssal Crest3つを、Cenarion HoldのAurel Goldleafに渡して下さい。", "wind stoneを使えば、Abyssal Councilの公爵を待ち伏せできるかもしれないと考えています。ただし、そのためにはwind stoneを通じて交信し、自分がTwilight's Hammerの中位の指導者だと評議会に信じ込ませなければなりません。\n\nそのような策略には、教団の階級を示すメダルの複製が必要です。メダルは私が作れますが、large brilliant shardと、Abyssal Templarが身に着けているcrestsが必要です。\n\nこれらを持ってきてくれれば、残りは私がやります。", "shardとcrestsは持っているか、{name}? twilight cultist's medallion of stationを作るのに必要なのだ。", "ああ、実にいい。メダルに取り組んでいたのだが、この最後の材料があれば、ほんの少しで仕上がる……\n\nさあ、できた。これがメダルだ、{name}。\n\nTwilight's Hammerのwind stonesの一つを起動するときは、これを身に着ける必要がある。残りのtwilightの装具と一緒にこれを着ければ、Abyssal Councilはお前を自分たちの信者の下っ端だと見なすだろう。", 0xf889dd83, 0xc49a16ec, 0xbc8d35c2, 0x5f3a2d03, 0xf6a2e4a0, "....." },
  [8341] = { "評議会の支配者", "Large Brilliant Shard5個、Abyssal Signet3個をCenarion HoldのAurel Goldleafに渡して下さい。", "Abyssal Councilの主たちは大きなwind stoneを通じてしか召喚できず、Twilight's Councilの最上位の者たちだけが彼らと話すことを許されています。でも……あなたの変装を強化して、Abyssal Lordsを欺く方法を見つけたんです!\n\nその変装には、教団の最上位の者たちだけが身に着ける支配の指輪が必要です。large brilliant shardsとabyssal signetsを持ってきてくれれば、あなたのために一つ作ってあげます。", "shardsとsignetsは持っているか、{name}? ring of lordshipを作るのに必要なのだ。", "ありがとう。少し待ってくれ、その指輪をすぐに用意する……\n\nさあ、できた。これで準備は整った。\n\ngreater wind stoneを起動するときは、medallion of stationと残りのtwilightの装具と一緒に、必ずこの指輪を身に着けてくれ。そうすれば、Abyssal Councilはお前を自分たちの下僕だと思うだろう。そうすれば、その一体を待ち伏せにおびき寄せられるかもしれん!", 0x1a3e1df3, 0xc80f03d3, 0xaab9abe2, 0x7d648603, 0xac008b57, "....." },
  [8343] = { "Goldleafの発見", "Cenarion HoldのAurel Goldleafと話をして下さい。", "{name}、Aurel Goldleafが、Abyssal Councilを支配する者の一人を召喚して倒す方法を見つけたと考えている! そのような任務は危険だろうが、あなたはCenarion Circleの中で大きな尊敬を得てきた。誰かにできるとしたら、それはあなただと我々は分かっている。\n\n幸運があなたと共にあるように、{name}。準備ができたらAurelと話してくれ。", nil, "Huumの言っていることは本当ですよ。私は確かにAbyssal Councilの王の召喚方法を知っています! 聞いて下さい。ご説明しましょう……", 0x7d06092e, 0x00d99f06, 0x94672e87, nil, 0x9a7b0a81, "...m." },
  [8348] = { "大公の印章", "Abyssal SignetをCenarion HoldのBor Wildmaneに渡して下さい。", "Huumから聞いたよ、Abyssal Dukesを召喚する方法が分かったんだって! そいつは大した手柄だ。\n\n他に何が大した手柄になるか分かるかい? ああいう奴らの一体をこっぴどく叩きのめすことさ。そうすれば奴らの手下どもに強い印象を与えられる、分かるだろ? その証として、奴のsignetを持ち帰ってくれ。", "Abyssal Dukeとの戦いはどうだった? 奴の一撃は重かったか?", "Cenarion Holdへ君がやって来るのを見た瞬間、強靱な{class}だと分かったよ。その調子だ!", 0xa8c6f6c8, 0xf6ee6096, 0x2ae1a524, 0xa61739e1, 0x8abe4588, "....." },
  [8349] = { "Bor Wildmane", "Cenarion HoldのBor Wildmaneと話して下さい。", "メダルを手に入れ、Abyssal Dukeを召喚できるようになったのだから、Bor Wildmaneと話してくれ。彼がAbyssal Councilに対する任務を与えてくれるだろう。\n\n幸運を祈る、{name}。もしまたメダルが必要になったら、私のところへ戻ってきてくれ。", nil, "再びまみえることができてよかった。{class}! それで、作ったメダルを持っているのだな? よろしい。それは次の任務に必要になるだろう……。", 0xc71f0889, 0xed9857d3, 0xaa46e222, nil, 0x03634dd9, "...m." },
  [8351] = { "Borが話したがっています", "Cenarion HoldのBor Wildmaneと話をして下さい。", "これであなたはTwilight Councilを統べる者に変装することができます。Bor Wildmaneはあなたと話をしたがっていると思います。行って彼と会って下さい。そして、大変難しい任務のために備えるのですよ……", nil, "ああ、その通りだ、{name}。この先、非常にきつい任務が待っている……", 0x9e79a2ab, 0xed9857d3, 0x84b44369, nil, 0x19d6e4b2, "...m." },
  [8352] = { "議会の杖", "Cenarion HoldのBor WildmaneにAbyssal Scepterを渡して下さい。", "ちょうどHuumとあんたの話をしてたところなんだ。あんたはもうすぐAbyssal Lordとの戦いに挑む準備ができるって言ってたよ!\n\n言っておくけど、これはとても危険な企てだ。援軍を連れて行った方がいい。友達の1人や2人じゃないよ、一流で、戦いの準備ができた戦闘部隊のことを言ってるんだ。あんたの仲間があんたと同じくらい腕が立つなら、倒せるかもしれない!\n\nもし倒したら――いつものように証拠は見せてもらうけど――本当に素晴らしい報酬をあげるよ。", "それで、どうだった? 持ち場を離れて、あんな奴らと自分で組み合えるなら、俺は何だってするのに!", "や……やりましたね! やりましたね、{name}! さあ! これをお持ち下さい。私が放り出していた一番大きな箱です。この中に、私が見つけた一番良い品をいくつか入れておきました。", 0x9215b008, 0xf0fb4cb2, 0x271213d0, 0xda78e943, 0xece272ca, "....." },
  [8361] = { "深淵との接触", "SilithusのCenarion HoldにいるBor Wildmaneは、Abyssal Templarを打ち破り、その証拠としてAbyssal Crestを持ってくるよう求めています。", "Twilight's Hammerの信者どもが、強力なエレメンタルの貴族を召喚する儀式を行っているのを見た。それが奴らの崇める存在なのか、それともさらに強力な力への仲介者として働いているのかは分からない。一つ確かなのは、奴らがそのエレメンタルたちから命令を受けているということだ。\n\n何とかしてAbyssal Templarと接触し、たっぷり痛めつけてやってほしい! 指揮系統を叩くことほど部隊を混乱させるものはない。ついでに証拠も持ち帰ってくれ。", "仕事は片付けたか?", "ハ! やったな、{name}! Twilight's Hammerはもうすぐ破滅するぞ!", 0xb08857d9, 0x172cfbe4, 0x8438e952, 0x1650733d, 0x5b14bd4d, "....." },
  [8365] = { "おーい海賊帽!", "TanarisのSteamwheedle PortにいるHaughty Modisteは、Southsea Pirate Hat 20個を集めて渡すよう求めています。", "あんたがCartelの寄こした助っ人かい? まあ、あんたでいいだろう。よく聞きな、{class}。知ってのとおり、あたしはAzerothian上流社会のエリートのために流行の衣装を調達している者だ。王や女王、大族長、それに、まあ、Hordeが女王を何と呼んでいるのか知らないが、みんなあたしが流行だと決めたものを着るのさ。しかも法外な金を払ってね。そこが一番いいところだよ。\n\nそれで、こういう段取りだ。Lost Rigger Coveへ行って、どんな手を使ってでもpirate hatsをたくさん手に入れてくるんだ。できそうかい?", "hatsは20個すべて揃っているのか? 信用ならんな、見せてみろ。傷一つない状態でなければ承知しないぞ!", "あらあなた素敵、私が慣れているのより長くかかってたとしてもね。この商品は私が綺麗にして名前を入れたら、もう少し高くなるわね。それと、いつも私は良い仕事には報酬を出したい方だから。つまらないものだけどどうぞ。いくらかはお風呂に使うといいわよ、あなた。", 0x87f5d54e, 0x5cbcdcb7, 0x07521fb1, 0xd83e1745, 0x6c24e923, "....." },
  [8366] = { "Southseaへの脅し", "Steamwheedle PortのSecurity Chief Bilgewhizzleは、Southsea Pirate・Southsea Freebooter・Southsea Dock Worker・Southsea Swashbucklerをそれぞれ10人ずつ殺すよう求めています。", "ああ! 奴らは俺に無理な注文ばかりする!\n\nSteamwheedle Cartelは俺にSouthseaの海賊どもを懲らしめろと言ってきた。問題は、俺は同時に二つの場所にはいられないってことだ。治安を守るためにここにいなきゃならないんでね。\n\n最近、海賊どもはカルテルがいつも払っている保護料を無視するようになった。そこで、あんたを一時的に保安官代理に任命して、あそこへ行って奴らに思い知らせてほしいんだ。\n\n奴らはLost Rigger Coveにいる。ここから南へそう遠くないところだ。ありがとうよ、{name}、恩に着るぜ!", "もう戻ってきたのか? あのSouthseaのごろつきどもに、当分忘れられない教訓を叩き込んでやったのだろうな。", "{name}! あんたは最高だよ!!!\n\nあんたがあのSouthseaのクズどもを片付けてくれたんだ、Cartelも俺への締め付けを緩めるに違いない。さてと、報酬に何をやろうかな? 少しばかりの金と、手間賃にこの中から一つ選んでもらうってのはどうだい?", 0x2069567b, 0xd79ddcd5, 0x5344aa45, 0x6b651691, 0xb71e97a7, ".....", nil, nil, nil, nil, 0x3be240a2 },
  [8367] = { "大いなる名誉のために", "Alterac Valley Marks of Honorを$N1個、Arathi Basin Marks of Honorを$N2個、Warsong Gulch Marks of Honorを$N3個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの大いなる戦いの一つでHordeに仕えることは、大きな名誉の源だ! だが、我らの活動中のすべての戦線でHordeに仕えた数少ない者こそが、真に偉大な戦士なのだ。我らが敵を打ち破るのは、孤立した小競り合いによってではなく、よく連携の取れた戦争を仕掛けることによってだ。\n\n出陣し、Arathi Basin、Alterac Valley、Warsong GulchでAllianceを打ち砕くのだ! 名誉のために! Hordeのために!", "Arathiは今なお偉大なウォリアーたちの血で濡れ、鋼のぶつかり合う音がAlterac中に響いている。前線からの知らせを持ってきたのでないなら、私の時を無駄にするな!", "試練は容易いものではなかったが、お前は勇気によって試練に立ち向かい、持てる力によって成功した。過去の勝利の証を手放せ、{class}。お前の存在価値を記念するものなど何も必要ないはずだ。背筋を伸ばせ、{name}。今日、お前は己が英雄であるという大いなる誇りと共に歩むのだ!", 0x9131d27a, 0x99d65c90, 0xf4c6ab84, 0x18bb2fc6, 0x426129ba, "....." },
  [8368] = { "Warsong Gulchの戦い", "Warsong Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Warsong Gulchからの知らせを持ってきたのか、{name}?", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x815047d1, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8369] = { "Alterac Valleyの侵略者", "Alterac Valley Mark of Honor 3つをバトルグラウンド外のHorde Warbringerに渡して下さい。", "よく聞け、{name}。Alterac Valleyで激化する戦闘について何を聞いていようと、真実はひとつ。Stormpike ExpeditionがFrostwolfの領地を侵略しているということだ。Hordeの土地を戦わずしてAllianceに明け渡した日こそ、斧を手放し恥辱にまみれて残りの人生を生きる日なのだ。前進し、侵略者どもを駆除せよ!", "Frostwolvesの地からどんな知らせを持ってきた? Alterac Valleyの戦いの戦況はどうだ?", "お前はAlteracの土地を守るために、大変な勇気を示してくれた! その行いは上官に伝えておこう。", 0x40e3f888, 0x6cc748f3, 0xe01ce18b, 0x5f4a67f5, 0xc67d587b, "....." },
  [8370] = { "Arathi Basin制圧", "Arathi Basin Mark of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの争いは本物の戦争にまで激化した。今となっては、どちらの側も戦いに入るための偽りの口実を使うことも、それを求めることもない。\n\nArathi Basinの戦いは、単純明快に資源の戦いだ。Allianceが資源を手に入れて我々に向けて使うか、我々が手に入れて戦争を続けるために使うかだ。我々に必要な資源の流れをDefilersが保てるよう手を貸してくれ、{name}！", "Arathiからの知らせを持って戻ってきたのか、{class}?", "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。", 0xc2935afd, 0x58e21046, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8371] = { "協調努力", "Alterac Valley Mark of Honorを$N1個、Arathi Basin Mark of Honorを$N2個、Warsong Gulch Mark of Honorを$N3個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "我々はもう、Hordeと孤立した戦いをしているわけではないのだ、若いの。\n\n一つの戦線での勝利は、Hordeが別の戦いで我々に対して使うはずの資源を奪うことを意味する。同じように、どの戦いで負けても、世界のどこか別の場所で敵に有利を与えかねない。\n\nAllianceには、こうした世界規模の理解を持つ戦士がもっと必要なのだ……真に経験を積んだ古強者がな! {name}、我々の活動中のすべての戦場でHordeと戦ってきたら、私のところへ戻ってこい。", "旅の具合はどうだね、若いの?", "君は期待を裏切らないな、{name}! 君が学んだものは、ささやかな勲章や表彰を超えている。君が学んだものは、経験と、戦場で気性を鍛え上げることによってしか得られないものだ。\n\nよくやった、{class}。君はまことのAllianceの英雄だ!", 0x3f0cde75, 0x65689054, 0xc60bec64, 0x8f1e0c1a, 0xe9fc3fdf, ".....", nil, nil, 0x678d2ae6, 0xbdf4388a, nil },
  [8372] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は単なる自然への愛だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。\n\nWarsong Outridersとの戦いで自分の役目を果たしてくれ、{name}！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやった、{name}! 君はAllianceによく尽くしてくれた。", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8373] = { "松の力", "Stink Bomb Cleanerを使って、Southshoreに投下されたForsaken Stink Bombを取り除いて下さい。事を成し終えたら、SouthshoreにいるSergeant Hartmanのところへ戻って下さい。", "Hallow's Endで一番嫌なのが、SouthshoreでForsakenが使う臭い爆弾だ。世界の解放を祝うのにそんな臭うのを使わにゃならんのだ?\n\nHallow's Endの間、この村にHordeが落としていく嫌な臭い爆弾を、このクリーナーを使って除去するんだ。松の力を使って、変な臭いと戦うのさ。\n\nSouthshoreの掃除に参加してくれたら、君がきっと楽しめるHallow's End treatをいくつかあげようじゃないか。取引成立だな?", "あの忌々しいForsakenども……アンデッドであるだけでも十分に迷惑だというのに、その上で騒ぎ立てて、私の村で面倒を起こし始めるのだからな!", "ああ、もうこの辺りの匂いがましになってきた気がするよ。ほとんどね。\n\n{name}、君のおかげでSouthshoreはもう一度Hallow's Endを乗り切れるかもしれない。お菓子をどうぞ、感謝を込めて! キャンディがなくなったら、IronforgeにKatrina Shimmerstarというノームがいて、もっと売ってくれると思うよ。確か、彼女はHallow's Endの間しかいないはずだけどね。", 0x6e6d4a39, 0x689dd20c, 0x33ac3eda, 0x6af39b38, 0xb45d1953, "....." },
  [8374] = { "Arathi Basinの確保", "Arathi Basin Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "戦争に勝つには、相手を出し抜き、打ち負かすだけでは足りない。勝利はしばしば、単純に敵より多くを生み出せるかどうかで決まるのだ。\n\nArathi Basinには、先にそれを手にした側のものになる、相当な量の資源がある。\n\nAllianceが勝てば、我々の部隊にはより多くの剣や槍が行き渡る。Hordeが勝ったとしても、その剣や槍はやはり作られるだろう。ただ、我々に向けられるだけだ！今こそArathi BasinでAllianceに力を貸す時だ、{name}。", "聞かせてくれ、前線からの知らせはどうなっている?", "よくやった、兵士よ! この調子で行けば、HordeをOrgrimmarまで逃げ帰らせてやれるぞ。", 0x637e1f39, 0x5e7275f8, 0x9452b6af, 0xa2aee952, 0x43526442, "....." },
  [8375] = { "Alterac Valleyを忘れるな！", "Alterac Valley Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "勘違いしないでくれ、{name}。Alterac ValleyはFrostwolf Territoryだと言うHordeの主張は、まったく正しい。\n\nいいか、Stormpike Expeditionは鉱石と遺物を求めて、平和的な訪問者としてこの地に来たのだ。それに対してFrostwolvesは、Allianceがかつて経験したことのない、最も残忍で野蛮な攻撃で応えた。\n\nあの卑怯な不意打ちで命を落とした勇敢なドワーフたちのことを、決して忘れないでいよう。さあ行け、{class}。Alterac Valleyの戦いで自分の役目を果たすのだ。Allianceのために！", "どんな知らせを持ってきた、{name}?", "君は自分の役目を果たしてくれた、{name}。AllianceはHordeの野蛮な行いを見過ごすわけにはいかないのだ!", 0xea2379c4, 0xcc86450b, 0x1106d7d2, 0x816d03be, 0x0945fff6, "....." },
  [8376] = { "戦争の兵器", nil, nil, nil, "戦争がやって来ます、{name}。そしてそれと共に、計り知れない恐怖も訪れるのです。あなたは求められうる限りのことをすべて成し遂げました。その報いを受けるべきです。\n\nもし、この……この予言が実現するようなことがあれば……\n\n<Geologist Larksbaneは青ざめる。>\n\n我々すべての未来が終わりを迎えるかもしれません。\n\nこの武具は、この砂漠でのあなたの戦いに計り知れない価値をもたらすでしょう。", 0x9aacc572, nil, nil, nil, 0x7f77ec54, ".mmm." },
