  [8399] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は単なる自然への愛だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。\n\nWarsong Outridersとの戦いで自分の役目を果たしてくれ、{name}！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやってくれました、{name}。あなたのおかげで、Ashenvaleの自然の守りはもう一日保たれるでしょう。", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0x83c232b5, "....." },
  [8400] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は単なる自然への愛だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。\n\nWarsong Outridersとの戦いで自分の役目を果たしてくれ、{name}！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやった、{name}! 君はAllianceによく尽くしてくれた。", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8401] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は、Silverwingsが掲げる自然保護の思想だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。Warsong Outridersとの戦いで自分の役目を果たしてくれ！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやってくれました、{name}。あなたのおかげで、Ashenvaleの自然の守りはもう一日保たれるでしょう。", 0xbeadcb52, 0x5ca6c72a, 0x82248f89, 0x378bede6, 0x83c232b5, "....." },
  [8402] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は単なる自然への愛だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。\n\nWarsong Outridersとの戦いで自分の役目を果たしてくれ、{name}！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやった、{name}! 君はAllianceによく尽くしてくれた。", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8403] = { "Warsong Gulchをめぐる戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるAlliance Brigadier Generalのところへ持って行って下さい。", "オークが森にもたらしている破壊のせいで、Silverwing SentinelsはWarsong Outridersと戦争状態にある。とはいえ、この森を守る理由は単なる自然への愛だけではない。\n\nこの森は、Ashenvaleを大規模な攻撃から守れるようにしている戦略上の障壁なのだ。これがなければ、AstranaarはBarrensに併合されるまで一日か二日しかもたないだろう。\n\nWarsong Outridersとの戦いで自分の役目を果たしてくれ、{name}！Allianceのために！", "前線からの知らせを持って戻ってきたのか、{name}?", "よくやった、{name}! 君はAllianceによく尽くしてくれた。", 0xbeadcb52, 0x5ca6c72a, 0xd15c0916, 0x378bede6, 0xa2a5cb89, "....." },
  [8409] = { "台無しになった樽", "Tirisfal GladeのWickerman FestivalにいるDarkcaller Yankaのところへ戻って下さい。", "rotten eggsは樽の中にうまく入れられた。Southshore Innのこれからのエールは台無しになること間違いなしだ!\n\nさあ、Tirisfal GladeのWickerman FestivalにいるDarkcaller Yankaのところへ戻り、成功を報告するのだ。", nil, "ああ、成功ね! あなたは真のHallow's Endの精神を、いえ、FORSAKENの精神を示してくれたわ!\n\n<Darkcaller Yankaが笑い、両手をこすり合わせる。>\n\nSouthshoreの連中がまずいエールで祝うか、さもなくば何もなしで済ますしかないと思うと、愉快でたまらないわ! あなたには、このお菓子をあげましょう。きっとうまく使ってくれるはずよ!", 0xcbae20af, 0xce9b33d2, 0xe895ed09, nil, 0xb14ac7c0, "...m." },
  [8410] = { "精霊の支配", "空気・火・土・水の標本を集めてBath'rah the Windwatcherに渡して下さい。", "Bath'rah the Windwatcherが、あなたほどの知恵を持つシャーマンを呼び寄せている。準備ができていることを示すために、それぞれのエレメントの見本を持ってくるよう求めている。\n\nBath'rahを見つけるには、Tarren Millの東にある川へ行くといい。川を北へたどって行けば、Bath'rahが住む遺跡にたどり着くだろう。", "俺に何を持ってきた、{class}?", "素晴らしいね、あんた。それじゃ話そうか。", 0x04bb928b, 0x52c37279, 0x7bb34efb, 0x4e4f40f9, 0x2e232784, "....." },
  [8411] = { "元素の習得", "大地、風、火、水のエレメントをBath'rah the Windwatcherのところへ持って行って下さい。", "よく来たな、兄弟。エレメントを持ってきたら、それから話をしようじゃねえか。", "エレメントはどこにあるんだい、あんた?", "これが俺の欲しかった元素だ。さあ、話そうじゃねえか。", 0xc6de61cd, 0x53ec0188, 0xf3c3ef42, 0xc83605a1, 0xbf2f0684, "....." },
  [8412] = { "魂のトーテム", "Bath'rah the Windwatcherにspirit totemの材料を渡して下さい。", "この地のエレメントの精霊たちは、もうおいらを好いてくれねえんだ。\n\nお前さんは誰よりもトーテムのことを知ってる。おいらを守ってくれる精霊のトーテムが要るんだよ。エレメントはもう揃ってるから、今度はもっと自然の力を持つものが要る。もっと原始的なものがな。\n\nWestern Plaguelandsでは、熊を倒せば爪が、蜘蛛を倒せば目が手に入る。死肉を漁る鳥どもは何でも食うから、どっちかを持ってるかもしれねえ。", "精霊たちは俺たちの企みを知っていて、俺を殺そうとしてるんだ! 部品は手に入れてくれたんだろうな。", "いいぞ、あんた! それじゃ、やってみようか……", 0xb513abac, 0xfad1dd4d, 0xfa023a9f, 0xdcff1581, 0x4f7f69ce, "....." },
  [8413] = { "呪術", "Bath'rah the Windwatcherにvoodoo featherを渡して下さい。", "精霊のトーテムだけじゃ足りねえ。ちゃんと効くようにするには、ブードゥーの魔法が要るんだ。\n\n沈んだ神殿のトロールどもは、ブードゥーの魔力が強く宿った羽を持ってる。そこへ行って、Gasher、Mijan、Zolo、Hukku、Zul'lor、Loroを倒してくれ。そうすりゃ本物の精霊のトーテムを作るのに十分な魔力が手に入る。", "羽根はどこにあるんだい、あんた?", "このトロールもようやく一晩ぐっすり眠れるってもんだ! 精霊のトーテムが俺を見守ってくれる。\n\n長いこといろんなもんを集めてきたんだ。手間をかけさせたお礼に、何か欲しいもんはあるかい?", 0x44084925, 0x7d0d0c69, 0x438ab205, 0x4e430c1d, 0xccb3a8ea, "....." },
  [8414] = { "邪悪の解呪", "Minion's Scourgestone 20個を集め、Western PlaguelandsにいるHigh Priest Thel'danisに渡して下さい。", "ようこそ、{class}。この荒れ果てた地では、あなたのような十字軍の戦士は歓迎すべき存在です。\n\nここの果てしないアンデッドと戦うために、あなたの聖なる力が必要なのです。scourgestonesを大量に集めて、High Priest Thel'danisのところへ持って行ってください。高位のプリーストは、ここからそう遠くないSorrow HillでUther's Tombを守っています。\n\nscourgestonesを見つけられるのはArgent Dawn Commissionを持つ者だけです。まだなら、Officer Pureheartと話してください。", "どんな邪悪なものを持ってきたのだ?", "scourgestoneから邪悪を取り払うのは危険なのだ。遙か彼方からでもアンデッドたちの注意を引きつけるのでな。しかし、{name}。君は「光」の技を得意としているから、心配はしていない……。", 0x33cb58b8, 0xc904dac3, 0x8a383c2e, 0x28a0867e, 0x8d4531d5, "....." },
  [8415] = { "Chillwind Point", "Chillwind PointにいるCommander Ashlam Valorfistに話しかけて下さい。", "{name}、Commander Ashlam Valorfistが君のような高潔さと武勇あるパラディンの召集を発令していたぞ。司令官はWestern Plaguelands南部にあるChillwind Pointにいる。彼を探して、「光」に貢献してくれ!", nil, "いいだろう、{class}! 君の実力を見せてくれ。", 0xe3f1bb3e, 0x68fa4270, 0x9b5889f4, nil, 0xb58b885c, "...m." },
  [8416] = { "Inert Scourgestone", "Inert ScourgestoneをChillwind PointにいるCommander Ashlan Valorfistに渡して下さい。", "石から悪は取り除かれました、{name}。\n\n私はCommander Ashlamの計画を知っています。彼に必要なのは不活性化した石ひとつだけです。それを彼のところへ持って行ってください。Scourgeを正義の炎で包むことができるように。", "Thal'danisはscourgestonesを浄化できたのか?", "あなたは問いもせず、私が頼んだとおりのことをしてくれた、{name}。\n\n信頼は得られたようだ。今なら我々の計画をもっと詳しくあなたに明かせるかもしれない。", 0x23c63ec5, 0xd6823c95, 0x5bd75dd5, 0x2f416567, 0xb3ba619c, "....." },
  [8417] = { "悩める霊", "Blasted Lands入口のFallen Hero of the Hordeと話して下さい。", "Blasted Landsに、かつてhordeの偉大な英雄だった霊がいる。戦士の名誉は肉体とともに滅びはしない。霊と話せば、君のためになるだろう。", "Stoleyの奴、俺の酒を出したか?", "そうか、君は俺の苦痛を和らげに来てくれたんだな。単に俺を倒せたらいいんだがな、そう単純にはいかなくてね……。", 0xe07b8903, 0x95a03fae, 0xb5739780, 0xfdfa4434, 0xa46758be, "....." },
  [8418] = { "Mightstoneの作成", "ブードゥーの羽根をAshlam Valorfistのところへ持って行って下さい。", "さて、不活性化したscourgestonesを組み合わせ、アンデッドの隊列を打ち砕く武器を作らねばなりません。これは簡単な仕事ではありません、{name}。何かの悪をそれ自身に向けさせることのできる珍しい魔法を持っているのは、沈んだ神殿のトロールたちだけなのです。\n\n神殿では、そのトロールたちはGasher、Mijan、Zolo、Hukku、Zul'lor、Loroとして知られています。彼らの堕落した魂に憐れみを感じる必要はありません……彼らも悪と無縁ではないのですから。", "あの忌まわしいトロールどもを討ち取ったか?", "これは見事だ、{name}。驚いたと言いたいところだが、あなたが我々を失望させないことは疑いなく分かっていた。\n\nHoly Mightstonesの一つをあなたに授けられるのは光栄だ。よく使ってくれ。", 0x7dd6edce, 0x78b14100, 0xbeb50915, 0x35661f33, 0xd6031f34, "....." },
  [8419] = { "インプのお願い", "FelwoodのImpsyにFelcloth 一枚を渡して下さい。", "{name}、FelwoodにいるImpsyという名のimpがあなたを呼んでいる。少し奇妙なことに、誠意の証としてfelclothを一枚持ってくるように言っているのだ。ウォーロックとしてあなたがすでに振るっている力を考えれば、Felwoodのsatyrがこのfelclothを持っていることは知っているはずだろう。\n\nImpsyはBloodvenom Fallsのすぐ北にいる。聞くところによると、この時期はとても美しい場所らしい。", "俺のfelclothは持ってきたか?", "なんて素晴らしい{class}なんだ!\n\n<Impsyがfelclothを顔に押し当てる。>\n\nああ、この手触りがたまらないね。肌を焼いて、心に邪悪な考えを織り込んでいくこの感じが……", 0x8f923b54, 0xcaccde4e, 0xba1e506c, 0xe4cd415e, 0x051f42a7, "....." },
  [8420] = { "熱くて痒い", "FelwoodのImpsyにFelcloth 一枚を渡して下さい。", "impがこんなことを言うのは変に聞こえるかもしれないけど、ボクも自分のペットが欲しいんだ。本当に欲しいんだよ。Nibyにはボクがいるのに、ボクには何もないなんて不公平だよ!\n\n実はね、生きたペットじゃなくてもいいんだ。作り始めるための何かが要るんだよ、felclothみたいなね。ここFelwoodのsatyrは時々felclothを持ってるから、見つかるまで十分な数を倒せばいいだけさ。そんなに大変そうじゃないでしょ?", "俺のfelclothは持ってきたか?", "わあ! 優しすぎるよ。ウォーロックにしてはね!\n\n<Impsyがfelclothを顔に押し当てる。>\n\nああ、この手触りがたまらないね。肌を焼いて、心に邪悪な考えを織り込んでいくこの感じが……", 0x7df22def, 0xcaccde4e, 0x787ec5c0, 0xe4cd415e, 0x5abdaa3e, "....." },
  [8421] = { "間違った道具", "Rotting Wood 10本とBloodvenom Essence 4つをFelwoodのImpsyに渡して下さい。", "felclothが手に入ったから、これで本格的に*ボクの*ペットを作り始められるよ。\n\nでも、目が要るんだ。irontreeの連中からrotting woodを引き剥がしてきてくれないかな。それで素敵な目を彫るからさ。奴らは北のIrontree Woodsにいるよ。\n\nそれに、あの新品の悪魔の匂いをつけるためにbloodvenom essenceも要るんだ。tainted oozesがそのessenceを持ってて、奴らはNibyとボクのすぐ近くのこのあたりをうろついてるよ。", "品物は持ってきたか?", "こいつはすごく使えそうだな。", 0x40b3fba2, 0x1049c074, 0x8f984754, 0x62d2d1c5, 0xd0eb0948, "....." },
  [8422] = { "羽のトロール", "sunken templeのトロールから合計6枚のVoodoo Featherを手に入れ、Impsyに渡して下さい。", "ボクのペットはもうすぐ完成だよ。あとは中に詰めるものが要るだけなんだ。\n\n沈んだ神殿のトロールが持ってるvoodoo feathersじゃなきゃだめなんだ。奴らはGasher、Mijan、Zolo、Hukku、Zul'lor、Loroって名前だよ。奴らを倒して。全員倒してね。\n\nこれは簡単な仕事じゃないよ、{name}。だから、Nibyの持ち物を何かあげて、苦労に見合うようにするよ――どうせ彼には要らないだろうしね。", "feathersは持ってきたかい? この人形には詰め物が要るんだ!", "素晴らしい、これで僕のペットは完成だ!\n\n<Impsyが素早く人形に詰め物をして、悪魔じみた抱擁をする。>\n\nおや、このvoodoo feathersには妙な副作用があるんだね……", 0xe11bf3ac, 0xfa3d0c11, 0x7f9ba851, 0x80d2b7f3, 0x46c09dc3, "....." },
  [8423] = { "ウォリアー同士", "Blasted LandsのHelboar 7頭を殺し、Fallen Hero of the Hordeのところへ戻って下さい。", "<英雄はあなたをじろじろと眺める。>\n\nお前は間違いなく{class}だな。名誉ある任務を頼みたいが、まずはお前の力を試さねばならん。\n\nRexxarは、helboarを一撃の素早い斬撃で仕留めることで自分の刃の鋭さを測ったと言われている。今度は、奴らを倒させることでお前の力を測らせてもらおう。", "helboarの燃える棘は、恐ろしい傷跡を残す。痛みも醜い傷も恐れるな、ウォリアーよ。我を縛るこの牢獄に比べれば、そのようなものは何ほどでもない。", "{class}、頼み事をこなしてくれたかどうかの証拠は要らないんだ。表情に刻み込まれた決意が見えるのでね。", 0xde7fa3a8, 0x39b7a605, 0x8f24b94b, 0x5be003e0, 0x2aacbdb4, "....." },
  [8424] = { "Shadowswornとの闘い", "Blasted LandsのShadowswornを大勢殺し、Fallen Hero of the Hordeのところへ戻って下さい。", "Blasted Landsにshadowswornが居座り続けていることは、私に大きな苦痛をもたらしている。奴らの闇の儀式と呪文は、生きていた頃に感じたどんなものとも違う苦しみを引き起こすのだ。\n\nお前を通じて、私自身の苦痛の知らせを届けることができる。行って、私の怒りを届けてくるのだ。", "shadowswornどもはたやすくは倒せぬであろう? だがそなたはウォリアーだ。勝利を収めるか、挑んで果てるかのいずれかだ。", "すでに君は苦痛を抑えて名誉を授けてくれた。ありがとう、{class}。", 0x7e21c995, 0xe2db1389, 0x7336323a, 0xdecd09a7, 0x41506fda, "....." },
  [8425] = { "Voodoo Feathers", "Sunken TempleのトロールからVoodoo Featherを手に入れ、Fallen Hero of the Hordeに渡して下さい。", "お前の名誉は私にいくばくかの安らぎをもたらした。その見返りに何かを差し出すのが筋というものだ。\n\n私の武器と鎧は生前見事なものだったが、今の私には何の役にも立たない。お前が持っている方がふさわしいだろう。\n\n沈んだ神殿へ行き、トロールの守護者Gasher、Mijan、Zolo、Hukku、Zul'lor、Loroを倒すのだ。奴らは魔法の羽を持っている。それがあれば、お前に報酬を与えられる間だけ、私の肉体を再びかたちづくることができる。", "もう戻ってきたのか? 我にとって時はもはや同じものではない。そなたにとっては、まことに長い旅であったのかもしれぬな……", "ようやく、鉄の冷たい感触をまた感じることができたよ。ほんの少しの間だけれど。", 0xbb860a9b, 0x4f5e1843, 0x400f79cc, 0x05e22a31, 0x1afd1e5f, "....." },
  [8426] = { "Warsong Gulchの戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Silverwing Sentinelsを相手取るWarsong Gulchの戦いは、極めて重要だ。自分たちのものでもない森を守るという名目のもと、AllianceはHordeから最大の木材供給地の一つを奪おうとしている。\n\nそのようなことをさせるな、{name}! Hordeにふさわしい形で仕えた証を持って、私のもとへ戻ってこい!", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x957077e1, 0x134a3898, 0x134a3898, 0xf832f61b, "....." },
  [8427] = { "Warsong Gulchの戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Warsong Gulchからの知らせを持ってきたのか、{name}?", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x957077e1, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8428] = { "Warsong Gulchの戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Silverwing Sentinelsを相手取るWarsong Gulchの戦いは、極めて重要だ。自分たちのものでもない森を守るという名目のもと、AllianceはHordeから最大の木材供給地の一つを奪おうとしている。\n\nそのようなことをさせるな、{name}! Hordeにふさわしい形で仕えた証を持って、私のもとへ戻ってこい!", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x957077e1, 0x134a3898, 0x134a3898, 0xf832f61b, "....." },
  [8429] = { "Warsong Gulchの戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Silverwing Sentinelsを相手取るWarsong Gulchの戦いは、極めて重要だ。自分たちのものでもない森を守るという名目のもと、AllianceはHordeから最大の木材供給地の一つを奪おうとしている。\n\nそのようなことをさせるな、{name}! Hordeにふさわしい形で仕えた証を持って、私のもとへ戻ってこい!", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x957077e1, 0x134a3898, 0x134a3898, 0xf832f61b, "....." },
  [8430] = { "Warsong Gulchの戦い", "Warsong Gulch Marks of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Warsong GulchでのSilverwing Sentinelsとの戦いは極めて重要だ。自分たちのものでもない森を守るという口実で、AllianceはHordeから最大級の木材の供給源の一つを奪おうとしている。\n\nそんなことをさせるな、{name}！Hordeに相応しく尽くした証を持って戻ってこい！", "Warsong Gulchからの知らせを持ってきたのか、{name}?", "素晴らしい! Warsong Gulchでの我々の作戦を守り、その価値を示してくれた! 君の名誉の噂が我らの地の隅々にまで広まらんことを。", 0x6925d544, 0x957077e1, 0x134a3898, 0x5bb7b09a, 0xf832f61b, "....." },
  [8436] = { "Arathi Basin制圧", "Arathi Basin Mark of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの争いは本物の戦争にまで激化した。今となっては、どちらの側も戦いに入るための偽りの口実を使うことも、それを求めることもない。\n\nArathi Basinの戦いは、単純明快に資源の戦いだ。Allianceが資源を手に入れて我々に向けて使うか、我々が手に入れて戦争を続けるために使うかだ。我々に必要な資源の流れをDefilersが保てるよう手を貸してくれ、{name}！", "Arathiからの知らせを持って戻ってきたのか、{class}?", "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。", 0xc2935afd, 0x58e21046, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8437] = { "Arathi Basin制圧", "Arathi Basin Mark of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの争いは本物の戦争にまで激化した。今となっては、どちらの側も戦いに入るための偽りの口実を使うことも、それを求めることもない。\n\nArathi Basinの戦いは、単純明快に資源の戦いだ。Allianceが資源を手に入れて我々に向けて使うか、我々が手に入れて戦争を続けるために使うかだ。我々に必要な資源の流れをDefilersが保てるよう手を貸してくれ、{name}！", "Arathiからの知らせを持って戻ってきたのか、{class}?", "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。", 0xc2935afd, 0x58e21046, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8438] = { "Arathi Basin制圧", "Arathi Basin Mark of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの争いは本物の戦争にまで激化した。今となっては、どちらの側も戦いに入るための偽りの口実を使うことも、それを求めることもない。\n\nArathi Basinの戦いは、単純明快に資源の戦いだ。Allianceが資源を手に入れて我々に向けて使うか、我々が手に入れて戦争を続けるために使うかだ。我々に必要な資源の流れをDefilersが保てるよう手を貸してくれ、{name}！", "Arathiからの知らせを持って戻ってきたのか、{class}?", "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。", 0xc2935afd, 0x58e21046, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8439] = { "Arathi Basin制圧", "Arathi Basin Mark of Honorを$N1個、戦場の外にいるHorde Warbringerのところへ持って行って下さい。", "Allianceとの争いは本物の戦争にまで激化した。今となっては、どちらの側も戦いに入るための偽りの口実を使うことも、それを求めることもない。\n\nArathi Basinの戦いは、単純明快に資源の戦いだ。Allianceが資源を手に入れて我々に向けて使うか、我々が手に入れて戦争を続けるために使うかだ。我々に必要な資源の流れをDefilersが保てるよう手を貸してくれ、{name}！", "Arathiからの知らせを持って戻ってきたのか、{class}?", "Arathiの資源を確保するのは重要な任務だ! よくやった、{name}。", 0xc2935afd, 0x58e21046, 0x67a7e231, 0x294fb6ca, 0xb1dc9ed2, "....." },
  [8446] = { "悪夢に覆われて", "Nightmare Engulfed Objectに秘められた意味を解き明かせる者を探す。\n\n強大な力を持つドルイドなら助けてくれるかもしれない。", "この品からは堕落がにじみ出ている。\n\nこの品と、Dreamから現れつつあるドラゴンたちの間には、何らかのつながりがあるのかもしれない。この品が意味するものを解き明かせる者を探さなければならない。MoongladeかCenarion Holdのドルイドたちなら、さらに力になってくれるかもしれない。", "何だ、{race}?", "穢れをそこから取り除かねばならぬ。最近、詳しく調べるのに失敗した「夢」を解明できるかもしれない。渡してくれ。", 0x246a0099, 0x0ddca4a0, 0x26d51f90, 0x98b629a5, 0x648c4b7e, "....." },
  [8447] = { "目覚める伝説", "Moonglade の Keeper Remulos が Nightmare Engulfed Object を浄化するのを待つ。", "Lake Elune'ara の水はこの物体を飲み込んでいる悪夢を消滅させるはず。{name} 、浄化を行うゆえしばし待て。", nil, "彼の指輪を取れ、{name} 。その指輪は Malfurion のために役目を果たした。今度はそなたのために役目を果たすであろう。", 0x40aca492, 0x878b703d, 0x84513d69, nil, 0x9a9b424a, "...m." },
  [8460] = { "Timbermawの仲間たち", "Grazleは、Deadwood Warriors 6匹、Deadwood Pathfinders 6匹、および Deadwood Gardeners 6匹を殺すことで、あなたが仲間であることを証明して欲しいと思っている。使命を終えたら、Felwoodの南、Emerald Sanctuaryの近くの彼のもとに戻りなさい。", "Timbermawはデーモンによる汚染を免れている唯一のfurbolg族だ。しかし今、他の多くの種族がfurbolgが敵か味方か確かめもせずに、オレたちを盲目的に殺していく。そう、だからTimbermaw furbolgはごく少数の者しか信頼していない。\n\nお前は、オレたちの信頼を得たいと思うか？Felwoodの汚染された Deadwood族を追い散らせ。そうすれば、我々はお前を仲間と考えてもよい。ここから西へ行けば、最初の Deadwood族 -- Warriors、Pathfinders、および Gardeners -- に出会うはずだ。", "その調子で続けろ、{name}。我らの信頼を得たいなら、自らの力を証明してみせねばならん。", "オレたちは過去の出来事に多くの影響を受けている。お前の行為、Timbermawを保護する支援に感謝する。お前との友情を育てる証しとして、このささやかな報酬を受けとってくれ。", 0x69fcebb2, 0x62b5ba95, 0xa2401007, 0x4cc9b0e3, 0xaa7a3b99, "....." },
  [8461] = { "北のDeadwood族", "Deadwood Den Watcher・Deadwood Avenger・Deadwood Shamanをそれぞれ6頭ずつ殺して下さい。Felwood北部のTimbermaw Hold入り口付近にいるNafienのところへ戻って下さい。", "すぐ南西にDeadwood furbolgの野営地があります。そこには腐敗が広がっており、問題となる前に手を打ちたいと思っているのです。\n\nDeadwood族は邪悪ですが、それは悪魔のもたらした力(fel)の影響で精神を蝕まれたせいです。彼らは生来敵対的だったのではありません、けれど救うことはできないのです。同胞と戦わなくてはならないとは、なんと悲しいことでしょう。\n\nお願いします、{name}。やらねばならないことを、あなたにお願いしたいのです。ただ、詳しいことは聞かせないで下さい。そんなことを考えるのは、苦しくてたまらないのです。", "Timbermawの信頼を得られれば、きっとあなたのためにできることがあると確信しています。Timbermawは味方を忘れません。特にこのような暗い時代にはなおさらです。", "分かります、あなたが勝利を勝ち取ったことが。勝利……やらねばならなかったことを考えれば、なんと空しい言葉でしょうね。とにかく、あなたが信ずるに値することは証明されたのです。\n\nTimbermawが敵意なしにあなたを迎え入れるには、まだ時間がかかるでしょう。それでも、同胞があなたに対して抱いている疑念を少しずつ晴らしていけると思いますよ。私たちを裏切らず、刃を向けることのない限り、わかり合える時がくるでしょう。", 0xb6acb3ae, 0xb30acb50, 0x71d91a00, 0x8424c8e2, 0xbd4d6d31, "....." },
  [8462] = { "Nafienと話す", "Felwoodの幹線道路を北へ進み、Nafienという名のfurbolgと話して下さい。彼はTimbermaw Holdの入口の外で見張りをしている。", "あなたなら、我々Timbermawが直面しているもっと大きな脅威にも対処できるかもしれません。ここでも十分に力があることを示してくれましたから……\n\nこの道をずっと北へ行ったTimbermaw Holdの入口の外で、私の同族がもう一人見張りに立っています。彼の名はNafienです。獰猛で不気味な獣に見えるかもしれませんが、恐れることはありません。彼は我々の住処を脅かす邪悪な勢力に立ち向かう助けを求めているだけなのです。", nil, "ああ……我らの部族ではない者たちが、Timbermaw furbolgsと手を結ぼうとしているという噂は風の便りに聞いておる。そなたを歓迎しよう。だが警告しておかねばならぬ。我が部族はよそ者を快く思わぬのだ。\n\n今は苦難の時。我らが信じられるのは、我らと共にこの地の堕落と戦う道を選び……それにふさわしく我らに己を証明した者だけなのだ。そうしておらぬ者がHoldに足を踏み入れれば、あからさまな敵意に迎えられるであろう。", 0x1e7cf150, 0xfd94d1c5, 0x16e63df0, nil, 0x08837f6c, "...m." },
  [8464] = { "Winterfall族の動向", "WinterspringのTimbermaw Hold入り口のすぐ外にいるSalfaは、Winterfall Shaman・Winterfall Den Watcher・Winterfall Ursaをそれぞれ8頭倒してほしいようです。", "Timbermaw族はひとりで過ごしがちなのです、{name}。信頼する者には安全に通ることを許しますが、他のfurbolg部族は出来る限り遠ざけています。\n\nWinterfall族は最近ますます私たちに敵対するようになりました。激しい怒りにかられているようなのです。彼ら自身にも理解できないすべての物に対する恐怖と憎悪に、完全に飲み込まれているのです。\n\n脅威を少なくするためにも、彼らの仲間を減らすようお願いしなくてはなりません。ここから遙か東のWinterfall Villageにいる彼らを捜し出して下さい。", "Timbermawのためにしてくれたことに心から感謝しています、{name}。あなたが努力を続ければ、きっと我が部族の信頼と敬意を得られるでしょう。", "悲しいですけれど、あなたのしてくれたことに感謝しています。感謝の印にこれを受け取って下さい。\n\nこれからも引き続き手伝ってくれるようお願いしたいです、{name}。物を頼める協力者はごくわずか。脅威に対処しようにも、あなたの助け無しでは手に負えないのです。", 0xfa0ccfbc, 0x15a35934, 0x10d61732, 0x369719ad, 0x3375f923, "....." },
  [8465] = { "Salfaと話す", "Timbermaw Holdを通り抜けてWinterspringへ出る。Timbermaw Holdの入口の外で見張りをしているSalfaと話して下さい。", "堕落の脅威は、南のDeadwoodのfurbolgsからだけでなく、東、つまりWinterspringのWinterfallのfurbolgsからも迫っています。さらに我々に力を貸してくれるなら、Holdの反対側、Winterspring側の入口のそばにいるSalfaと話してください。左の道を進めばたどり着けます。\n\n気をつけてください――中にいる私の同族があなたを敵対的、あるいは憎むべき者と見なせば、襲いかかってきます。争いを避け、できるだけ速く通り抜けてください。Timbermawを殺せば――たとえ身を守るためであっても――あなたはさらに疎まれるだけです。", nil, "ようこそ、{class}。我はここWinterspringにおけるTimbermawの代弁者として、また部族の守り手として、ここで見張りに立っておる。\n\nこの凍てつく地にいる我らの同胞Winterfallは、Felwoodのfurbolgと同じ堕落の力に屈してしまった。そなたがTimbermaw furbolgsに助力を申し出に来たのなら、我らはその申し出を受け入れる用意がある。", 0x0bcafcf5, 0xd998c3b3, 0x0eda6305, nil, 0x61b7f62d, "...m." },
  [8470] = { "Deadwood Ritual Totem", "Deadwood Ritual Totem を Timbermaw Hold へ持っていき、furbolgがその使い道を見つけられるかどうか調べる。Timbermaw 族からの評判が Neutral もしくはそれ以上でないと、話をすることはできない。", "Deadwood furbolgの儀式用トーテムの一つを見つけた。トーテムそのものはこれといった特徴のない作りだが、はっきりと感じ取れるほどの絶望がにじみ出ている。Deadwood furbolgが苦しめられている堕落を最もよく表す品があるとすれば、間違いなくこれだろう。\n\nTimbermaw Holdの中にいるfurbolgの誰かなら、この品の使い道を知っているかもしれない……ただし、彼らが話をしてくれるほどの信頼を得ていればの話だ。", "うむ、{class}よ、何を手伝えばよい? そなたは平穏のうちに我らの間を歩んでいるが、確かに何かがおかしい。何かを感じる……何か、心をざわつかせるものを……", "このトーテムは……Deadwoodのものだと分かるが、腐敗の悪臭がひどく染みついている。我らの同胞を我らに背かせた穢れが何であれ、それは間違いなくこの品に宿っている。\n\nこれを我らのもとへ持ってきたのは賢明だった、{name}。研究と儀式によって、同胞の心を汚しているものの正体を突き止められるかもしれない。ありがとう、友よ――見つけてくれた礼に、この捧げ物を受け取ってほしい。", 0x835827c1, 0x38da6b11, 0x05bee739, 0x400a0c34, 0x499bdd47, "....." },
  [8471] = { "Winterfall Ritual Totem", "Winterfall Ritual Totemを持ってTimbermaw Hold内へ行き、そこにいるfurbolgの一頭がトーテムの使用法を見つけられるかどうか調べて下さい。Neutralかそれ以上の評判でなければ、Timbermaw族は話をしてくれません。", "Winterfall furbolgの儀式のトーテムを一つ見つけた。トーテムそのものはこれといった特徴のない作りだが、ほとんど手に取れるほどの恐怖と絶望の気配を発しているようだ。もし多くのWinterfall furbolgsが本当にこれを持っているのなら、彼らの今の状態を説明するのに大いに役立つことは間違いない。\n\nTimbermaw Holdの中にいるfurbolgsの誰かが、このような品の使い道を知っているかもしれない……ただし、彼らが話をしてくれるほどの信頼をあなたが得ていればの話だが。", "{class}よ、そなたは穏やかな様子で我らに近づいてくるが、重く深刻な用件でここに来ていると感じる……furbolgにとっても{race}にとっても同じく。何を伝えに来たのだ?", "これは……Winterfall Ritual Totemの形をしていますが、私には到底理解の及ばぬ力によって歪められています。Winterfallを我々に敵対させた穢れが何であれ、この品には確かにそれが宿っています。\n\n神聖な知恵が、これとあなたの両方を我々のもとへ導いてくれました、{name}。我々はこの品を丹念に調べます。いつの日か、Winterfallが我々に牙を剥くことはなくなるかもしれません。\n\nありがとう、友よ。あなたの慈愛と引き換えに、どうかこの品々を受け取ってください。", 0x1a9e7597, 0x8901cc35, 0x095bc630, 0x5a6ecea3, 0x92c5d348, "....." },
  [8481] = { "諸悪の根源", "Demon Summoning TorchをWinterfallのfurbolgの村にあるHigh Chief Winterfallの洞窟の入り口に設置してください。悪魔を倒し、Timbermaw HoldのGorn One EyeのためにEssence of Xandiviousを回収してください。", "{name}、Winterfall族の諸悪の根源……彼らを支配している腐敗の悪魔を呼び出す方法を、あなたのおかげで考え出せました。\n\nこの松明を持ってHigh Chief Winterfallの住む洞窟へ行き、そこに松明をしっかりと立てて下さい。そうすれば、悪魔は否応なく姿を現し、様子を調べに来るでしょう。あなた方が悪魔を打ち倒す時は今です!　死んだ悪魔の魂だけが、Winterfall族の長い長い立ち直りと……Timbermaw Holdの救済の始まりとなるのです。", "我らのもとへ戻ってきたのだな、{name}……ということは、あの悪魔は討ち取られたのか?", "あなたは……私たちを救ったのです!　悪魔Xandiviousの打倒によって、Timbermaw Holdの末永い安全が確保されたのです。あなたは私たちの真の英雄です。\n\n私たちの祝福とこれをどうぞ受け取って下さい。furbolgたちが立ち直るのはゆっくりでしょうし、争いもまだ続いていくでしょうけれども、Winterfall族が今まで持っていなかった何かをあなたは与えたのです。\n\n彼らには、生きていける可能性があります。", 0x8964f90a, 0x092c5e3b, 0x6b67dd59, 0x21afd731, 0x1d5043c1, "....." },
  [8484] = { "平和の橋渡し", "Timbermaw Offering of PeaceをIronforgeのKing Magni Bronzebeardへ渡して下さい。", "あなたの偉業は単なる英雄のお話を遙かに凌ぐものです、{name}。あなたが一族の代表ならば、あなたの一族は私たちが和平を結ぶことのできる人々です。\n\nお願いします、鋼鉄の山に住むドワーフの王にこの贈り物を渡して下さい。あなた方がIronforgeと呼ぶ都市だと思います。以前、彼はAllianceを代表して接触しようとしてきました。平和を橋渡しするAllianceの取り組みの要は、あなたをおいて他にありません。", "{class}よ、我が領域へようこそ。Ironforgeは、そなたのような英雄にとって常に故郷であるべき場所だ。それで、私にどのような用があるのかね?", "まったく、思いがけない展開になったことだな。あの生き物と恒久平和を結べるなら、Kalimdorの問題……ナイトエルフが自身で支えきれぬ問題に関して確実な強みとなろう。このことはAllianceの他の指導者たちにもすぐ伝え、また外交官を派遣することにしよう!\n\n{name}、そなたについては……自ら行動し、双方の外交関係において勇気を示してくれた。全Allianceに代わり、礼を言うぞ。", 0xb6a1d87d, 0x28866f41, 0x02f05eb6, 0x31c122ab, 0x10cecc6d, "....." },
  [8485] = { "平和の橋渡し", "Timbermaw Offering of PeaceをOrgrimmarのThrallへ渡して下さい。", "あなたの偉業は単なる英雄のお話を遙かに凌ぐものです、{name}。あなたが一族の代表ならば、あなたの一族は私たちが和平を結ぶことのできる人々です。\n\nお願いします、Durotarの地に住むオークのwarchiefにこの贈り物を渡して下さい。あなた方がOrgrimmarと呼ぶ都市だと思います。以前、彼はHordeを代表して接触しようとしてきました。平和を橋渡しするHordeの取り組みの要は、あなたをおいて他にありません。", "大族長からの挨拶をそなたに授けよう、{class}。この困難な時代にあって、そなたの行いはHordeをより強くしている。さて、私にどのような用がある?", "まったく、思いがけない展開になったことだな。あの生き物と恒久平和を結べるなら、外的脅威からKalimdorを守る確実な強みとなろう。このことはHordeの他の指導者たちにもすぐ伝え、また外交官を派遣することにしよう!\n\n{name}、そなたについては……自ら行動し、双方の外交関係において勇気を示してくれた。Horde全てに代わり、礼を言うぞ。", 0xb6a1d87d, 0xb9e33dfa, 0x1dddc44b, 0x562b8e26, 0x748fecea, "....." },
  [8492] = { "AllianceはCopper Barsを必要としている！", "Copper Barを20本、IronforgeのMilitary WardにいるSergeant Stonebrowのところへ持って行く。", "やあ、{class}、戦いに貢献できるくらい丈夫そうじゃないか！ Ahn'Qiraj Warに必要な物資を揃えるのに、ここじゃどんな助けでも欲しいんだ。今日はお前さんにとって幸運な日だぞ。\n\ncopper barsを20本ひと束で集めてるんだ。立派な目的のためさ、どうだい？ Allianceを助けてやれそうかい？", "あのcopper barを20本、もう集めてきたか、兵士?", "やってくれたな、若いの! このcopper barsを山に積んで、すぐに軍需物資作りに役立ててやろう。お前さんのような者たちの働きがあるからこそ、わしはAllianceに仕えることを誇りに思えるんだ。よくやった、兵士よ!\n\nそれから、もしまたcopper barsを見つけたら、必ずわしのところへ届けてくれよ。", 0x757406f0, 0xf4add46a, 0x51825aa9, 0xdcd7c22d, 0x4a7e2fe9, ".....", nil, nil, nil, nil, 0x90199bdf },
  [8494] = { "AllianceはIron Barsを必要としている！", "Iron Barを20本、IronforgeのMilitary WardにいるCorporal Carnesのところへ持って行く。", "おやまあ、Fancypantsさんじゃないの、会えてうれしいよ。外で「冒険」してる間に耳に入らなかったかもしれないけど、AllianceはAhn'Qirajでの戦争に向けて準備を進めていて、iron barsが必要なんだ……それも山ほどね。20個ずつ束にして持ってきておくれ。頼りにしていいよね、{class}？", "あのiron barを20本持っているなら、どこに隠しているのかなど知りたくもないな!", "おやおや、{name}じゃないか。しかもやり遂げたときた。これからはお前から目が離せなくなりそうだ。言うのは癪だが、働きには感謝する。Allianceは忘れないし、俺も忘れない。さあ、とっとと出かけて、他に集める必要があるものを何でもいいから汗水たらして集めてこい。", 0x9fa1d26b, 0xce905b6f, 0xe062b09f, 0x77c47230, 0x4adb19d0, ".....", nil, nil, 0x4c0ca3d6, nil, nil },
  [8499] = { "AllianceはThorium Barsを必要としている！", "Thorium Barを20本、IronforgeのMilitary WardにいるDame Twinbraidのところへ持って行く。", "Allianceが必要としているものについて尋ねてくださるとは、ご親切にありがとうございます。進行中のさまざまな収集活動に加えて、私たちは大量のthorium barsを必要としていて、それが私の担当している仕事なのです。thoriumは戦争のためのさまざまなものの製作に使われますが、何より、完成し次第Silithusへ空輸される蒸気戦車の大隊の建造に使われるのです。この取り組みに力を貸していただけますか、{class}？", "おお、兄弟からの荷物だって？素晴らしい！今日は本当に運に恵まれているよ！", "つまりGnoarnは俺の偵察能力を信用してないってことか? なんでだろうな……", 0xbc047bca, 0x3b0fb51a, 0xde56c2df, 0x89b01d8f, 0x8c8ff225, "....." },
  [8503] = { "AllianceはStranglekelpを必要としている！", "Stranglekelpを20個、IronforgeのMilitary WardにいるPrivate Draxlegaugeのところへ持って行く。", "ねえ、{class}、stranglekelpのすばらしい使い道のこと、もう全部話したっけ？ 話した？ まあいいや……とにかくたくさん必要なんだ。たくさんって言ったら、本当にたくさんだよ！ 手伝ってもらえないかな？ それで作れるいろんな素敵なものを諦めることになるのは分かってるけど、立派な目的のためなんだ！", "そんなことはない! ここに積まれた山からstranglekelpをくすねたりなど、私は決してしない。まあ、実用的な万能薬も同然なのだから、誘惑に駆られる者もいるだろうがね。*ごほん* ところで、先ほど話したstranglekelpを持っていたりはしないかね?", "やった! これでまた20個片付いたよ。君って最高! しおれる前に全部しまっておかなきゃね。stranglekelpはこんなにあるのに、時間がちっともないよ!\n\n改めてありがとう、{class}!", 0x63f519e9, 0x7edb95d9, 0x986b25d7, 0x72242e7d, 0xc0116e1a, "....." },
  [8505] = { "AllianceはPurple Lotusを必要としている！", "Purple Lotusを20個、IronforgeのMilitary WardにいるMaster Nightsongのところへ持って行く。", "{class}、purple lotusは数多くの用途を持つ花です。私はその利用法の権威として、集められた薬草を保存し、戦争のためにAllianceが計画している用途をまかなえるだけのpurple lotusを確実に手に入れられるよう、Allianceの要請でここにいるのです。\n\n世界へ出かけて、この花をいくらか持ち帰ってきていただきたいのです。お願いできますか？", "お願いしたpurple lotusの薬草は持ってきましたか?", "あなたの貢献に深く感謝します、{class}。silithidと、それを駆り立てている何らかの力の容赦ない進撃を退けられるのは、すべての者の力を合わせてこそです。Hordeでさえ、独自にpurple lotusを集めています。もっと見つけたら、どうかここへ戻ってきてください。", 0x96884544, 0x079dc878, 0xc21d38b7, 0x46a461af, 0x5dc529c8, "....." },
  [8509] = { "AllianceはArthas' Tearsを必要としている！", "Arthas' Tearsを20個、IronforgeのMilitary WardにいるSergeant Major Germaineのところへ持って行く。", "簡潔に要点だけ言おう、{class}。AllianceはAhn'Qirajの戦争のために、大量のArthas' Tearsを集める必要がある。何に使うのかは聞くな。私は命令に従っているだけだ。だが、できるだけ多くその薬草を集めて、ここへ持ってきてもらいたい。やってくれるか？", "何だって? はっきり言ってくれ、{class}! 頼んでおいたArthas' Tearsの積荷は手に入れたのか?", "よくやった、{class}。正直言って嬉しい驚きだよ。手伝うと言って来ておきながら、二度と戻ってこなかった者がどれだけいたか、君には信じられないだろうね。とりあえずそれを木箱に入れて、君の名前で数を記録させてくれ。そしたら、あの植物がまだ必要かどうか、また話そう。", 0x6d6dd93b, 0xf1a02c62, 0x60fc0f60, 0x3c0166a7, 0xf3dfc769, "....." },
  [8511] = { "AllianceはLight Leatherを必要としている！", "Light Leatherを10枚、IronforgeのMilitary WardにいるBonnie Stoneflayerのところへ持って行く。", "我々Stoneflayer家は、皮はぎ職人として長い歴史を持っているんだ、{class}。だからAllianceは、Ahn'Qirajの戦争のためのlight leatherの収集を手伝ってくれと、うちの一族に頼んできたのさ。俺はここで、何に使うにせよ、皮がちゃんとなめされるよう見届けている。だが、お前さんの助けが必要なんだ。\n\n俺はここでその仕事をしてなきゃならないから、お前さんに出かけて皮を集めて、ここへ持ってきてほしい。どうだい、若いの、やってみるか？", "{class}、それが約束してくれたlight leatherであることを、心から願っているよ。", "言わせてもらえば、Allianceはこの革をとても喜ぶだろうね、{class}。1枚たりとも無駄にはしないよ。ありがとう。数え終わったら、もっと必要かどうか確かめにまた声をかけてくれ。", 0x166b0989, 0x2f8c4ca1, 0x9167564a, 0xbc6f644c, 0x2612f9b9, ".....", nil, nil, 0x7b43942b, nil, nil },
  [8513] = { "AllianceはMedium Leatherを必要としている！", "Medium Leatherを10枚、IronforgeのMilitary WardにいるPrivate Porterのところへ持って行く。", "はい、戦争のために集められるmedium leatherをすべて集めて記録する役目を任されております。どこからでも構いませんので、medium leatherを集める手立てがおありでしたら、ここへお持ちください。お時間を割いていただけるなら、手を貸していただけると本当にありがたいです。", "はい、お客様、あなたのことは覚えていますよ。そこに持っているのは、medium leatherですか?", "わあ! ついさっき手伝いを申し出てくれたばかりな気がするのに。寄付を本当にありがとう。全部まとめて数えておくよ。まったく、君は人の一日を明るくする方法を心得てるね。", 0xfb782e71, 0x489fbec8, 0x5b621688, 0xd58c253b, 0x12b794b1, ".....", nil, nil, 0x6ff18d34, 0x965b27ea, nil },
  [8515] = { "AllianceはThick Leatherを必要としている！", "Thick Leatherを10枚、IronforgeのMilitary WardにいるMarta Finespindleのところへ持って行く。", "うわあ、これはすごいことになるぞ！ {class}、Ahn'Qirajの戦争の準備は真っ最中で、僕は届くthick leatherを全部管理する係を任されたんだ。それでいろんなものを山ほど作るんだけど、まずはそれを山ほど集めなきゃならない。文字通りの意味でね！ そこで君の出番さ。\n\nそれで、外に出て、thick leatherをたっぷり束にして持ってきてくれないかな？ ねえ、ねえ、やってくれる？！", "その荷袋に入っているのは、thick leatherですか、{class}? そうなのですか? 早く渡してほしくてたまりません! みんなきっと私たちのことをとても喜んでくれますよね?", "ああ、君ならできると思ってたよ、{class}、分かってたんだ! できるだけ早くこれをしかるべき人の手に渡すね。さて、どれどれ。うーん、集計はなかなか順調みたいだ。数え終わったら、もっと必要かどうか、ちょっとしてからまた確かめに来てくれ。もし必要なら、集めに行ってほしいのは君なんだから!", 0x460fae65, 0x6b20ea1a, 0x9a42642a, 0x83fccb86, 0xc7cd8ddd, "....." },
  [8517] = { "AllianceはLinen Bandagesを必要としている！", "Linen Bandageを20個、IronforgeのMilitary WardにいるSentinel Silverskyのところへ持って行く。", "Ahn'Qirajの戦争は長く、血なまぐさいものになるでしょう。争いに真っ向から飛び込む前に、必要な物資を揃えるため、あなたやあなたのような方々の助けを募るのは、Allianceにとってとても賢明なことです。\n\n私は戦争のためのlinen bandagesの収集を取りまとめるよう頼まれていて、必要なだけ集めるのをあなたが手伝ってくださることを願っています。軽いことではありませんが、少なくともlinen bandagesは作るのが一番簡単です。力を貸していただけますか、{class}？", "私が必要としている20個のlinen bandageは持っていますか、{class}?", "今日ここでのあなたの貢献は、多くの兵士たちの助けとなるでしょう、{class}。あなたの尽力をAllianceに知らせるよう、私自身が取り計らいます。この包帯をきちんとしまい、数を更新するまで少しお待ちください。その後、さらに必要かどうか私に確かめに来てください。\n\nEluneの光があなたを照らしますように、{race}!", 0x39ccd76b, 0xb3fed698, 0x33421156, 0xd06208b4, 0x57d65781, "....." },
  [8519] = { "終わらない盤上の駒", "過去から学ぶことのできるすべてを学び、TanarisのCaverns of TimeにいるAnachronosと話して下さい。", "落ち着きを取り戻して目をじっと凝らすと、その水晶の中で何かが動いているのに気が付いた。よく調べてみると、あなたは過去……遠い昔に忘れられた記憶を見ていることが分かった。", nil, "Staghelmの裏切りののち、我はScepter of the Shifting Sandsの砕けた欠片を集め、ここへ戻った。この世界に害をなすためにその杖を使おうとする者たちから、それを守り抜くつもりであった。かくしてDragonflightsの責務が生まれたのだ。\n\n4体の強大なAspectsに分け与えられた杖は、あえて混沌を求める者たちにとって、元に戻すことはほぼ不可能なはずであった……我はそう思っていた。なんと愚かであったことか。今なお我はあの呪われた一族に狙われている。", 0x64ad1c82, 0xff784ae6, 0xea365e7c, nil, 0x61c05b10, "...m." },
  [8520] = { "AllianceはSilk Bandagesを必要としている！", "Silk Bandageを20個、IronforgeのMilitary WardにいるNurse Stonefieldのところへ持って行く。", "Ahn'Qiraj Warが迫る中、兵士たちが必要なものをすべて手にできるよう、我々はできる限りのことをしなければならない。まさにそれを、ここでやっているんだ。私の担当としては、十分な量のsilk bandagesを集める役目を任されている。\n\n手伝ってもらえるか、{class}？", "こんにちは、{class}。あの20個のsilk bandageはもう手に入りましたか?", "{class}、やってくれたね! 君のおかげで、silk bandagesの目標達成にまた一歩近づいたよ。これをしまっておくから、よかったらその後でまた話そう。", 0x15d829cb, 0x956b5123, 0xc152ec92, 0xfc304e96, 0xdb5433ca, "....." },
  [8522] = { "AllianceはRunecloth Bandagesを必要としている！", "Runecloth Bandageを20個、IronforgeのMilitary WardにいるKeeper Moonshadeのところへ持って行く。", "戦争の是非を論じたければ論じるがいい、{class}。だが戦争はすでに動き出している。周りの家族や友人を見て、彼らが巻き込まれた時、この大火を生き延びるためのあらゆる利点を持てるよう、自分に何ができるのか自問してみることだ。\n\nそのために、私はここで、出どころを問わずrunecloth bandagesを集めている。寄付してくれるか？", "日々は次々と過ぎ去り、それでも我々は歩み続ける。{class}、あのrunecloth bandageは持ってきてくれたか？", "この任務をやり遂げたあなたの忍耐は称賛に値します、{class}。この包帯をしまったら、runecloth bandagesをさらに集めていただけるかどうか、改めてお話ししたいと思います。", 0xf93887af, 0xeebbdf4d, 0x62a11c22, 0xde0bf237, 0x5557e41f, "....." },
  [8524] = { "AllianceはRainbow Fin Albacoreを必要としている！", "Rainbow Fin Albacoreを20匹、IronforgeのMilitary WardにいるSlicky Gastronomeのところへ持って行く。", "やあ、友よ！ もし私が「兵士だって他のみんなと同じように食べる物が必要だと思わないかい？」と言ったら、もちろん君は「うん」と答えるだろう。私も110%同感さ！ 意見が一致して嬉しいよ。君にしてほしいのは、出かけていって、生のrainbow fin albacoreをどっさり釣り上げて、それを全部料理して、ここへ持ってきてくれることだけだ。うーん、もう味がしてきたよ。", "前に話していたrainbow fin albacoreを全部持って戻ってきたんだろう、賭けてもいいぜ。そうだろう、{class}？", "Allianceに2つ、俺に1つ、Allianceに2つ、俺に1つ。やあ、魚屋さん、見事な仕事だ。君はこのクラブの立派な誇りになりそうだな。だが見たところ、そのalbacoreはもう少し必要みたいだ。ひとっ走り行って、もうちょっと集めてきてくれないか。もう腹が鳴ってるのが聞こえるよ。", 0x5b42adcf, 0xdd52119c, 0x09512125, 0xb86def6c, 0xda8db929, "....." },
  [8526] = { "AllianceはRoast Raptorを必要としている！", "Roast Raptorを20個、IronforgeのMilitary WardにいるSarah Sadwhistleのところへ持って行ってください。", "あ、調子はどう、{class}？ もしかして、Ahn'Qirajで始まる戦争のために食料を集めることに興味があるのかな？ なぜか父さんは、僕がここで手伝いを志願したらいい勉強になると思ったらしいんだ。大間違いだよ。僕は肉を食べるのさえ好きじゃないのに。\n\nとにかく、その気があるなら、roast raptorをたくさん持ってきてくれてもいいよ。どうやら兵士たちはみんなそれを欲しがるらしいからさ。", "それで、roast raptorはもう全部揃ったのか？", "へえ、そりゃいいね。この焼けた獣の肉をこんなに持ってきてくれてありがとう、{class}。あっちの山に載せておくよ。誰かが何とかしてくれるだろう。暇があるなら、もっと持ってきてくれてもいいんじゃないかな?", 0x098b1abf, 0xaba3be3e, 0xe72e6f63, 0x4407bf0f, 0x69244cc0, "....." },
  [8528] = { "AllianceはSpotted Yellowtailを必要としている！", "Spotted Yellowtailを20個、IronforgeのMilitary WardにいるHuntress Swiftriverのところへ持って行ってください。", "調理した魚を集めるのは英雄的には見えないかもしれませんが、準備の価値を侮ってはいけませんよ、若き{class}。兵士も他の誰とも同じように食べなければなりませんし、Ahn'Qirajで戦争が始まった時に彼らが必要なものを手にできるよう、私たちはここで自分の役割を果たしているのです。\n\nそういうわけで、私はspotted yellowtailを蓄えています。日持ちがよく、さまざまな料理に使える万能な栄養源です。それに、他の海水魚のような臭みもありません。この取り組みに力を貸していただけますか？", "これほど早く戻ってきたのですから、話し合ったspotted yellowtailを持ってきてくれたものと信じていますよ。", "この贈り物をありがとう、{class}。しかもこんなに早く。これで兵士たちが食べるものに困ることはないでしょう。この魚をきちんとしまうので、その後、よろしければ二度目の漁獲についてお話ししましょう。", 0x7294f481, 0x3cf7b746, 0x271c6dcb, 0x7b69ba9d, 0x0e1fc6c8, "....." },
  [8530] = { "AllianceはSinged Corestonesを必要としている！", "singed corestoneを50個、Dun Moroghの飛行場にいるCommander Stronghammerのところへ持って行ってください。", "{class}、助けてほしいんだ。Molten Coreには、ある石が――正確に言えば焦げたCorestonesが――あって、Ahn'Qirajの戦争のためにそれを集める必要がある。我々の鍛冶屋や技術者がうまく使えるそうだから、そこでお前の出番ってわけだ。Molten Coreに入って、そのcorestonesをできるだけ多く集めてきてほしい。もちろん、一番親しい仲間を39人連れていきたいところだろうな。", nil, nil, 0x04d33b63, 0x27c04186, 0xe9b6aca8, nil, nil, "...mm" },
  [8532] = { "HordeはCopper Barsを必要としている！", "Copper Barを20個、OrgrimmarのValley of SpiritsにいるMiner Cromwellのところへ持って行ってください。", "ここを手伝うと決めてくれて本当に嬉しいよ。誰もがそうしてくれるわけじゃないからね。だから、私が何を必要としているのか、ちゃんと分かってもらわないと。copper barsだよ、銅鉱石じゃなくてね。私たちには精錬を全部自分たちでやる時間も人手もないから、君がそれを引き受けてくれるなら、その働きはきちんと記録しておくよ。やってもらえるかな、{class}？", "そこに持っているのが20本のcopper barだといいんだがな、{class}。", "この地金で十分だ。磨かないでくれて助かったよ。戦争のために作る物資の材料としてどうせ潰されるんだから、きれいにしても意味がない。俺が積み上げておくし、ちゃんと役立つようにしておくよ。もう20本持ってくる気があるなら、また声をかけてくれ。", 0xbbeab2c7, 0xf9c51e39, 0x0474773f, 0x04e66454, 0x8e6c1aad, "....." },
  [8542] = { "HordeはTin Barsを必要としている！", "Tin Barを20個、OrgrimmarのValley of SpiritsにいるGrunt Maugのところへ持って行ってください。", "Lok'tar、{race}。俺たちがAhn'Qirajで虫けらどもと戦争をすることは、もう知ってるだろう。だがその前に、大族長は「準備」とかいうものをすると決めたんだ。俺は武器を研いだり鎧を叩いて形にしたりしてるほうがいいんだが、ここでtin barsの収集を任されたのは誇りに思ってる。だが、お前の助けなしにはそれができないんだ。\n\nだから、出かけてtin barsを作って、ここへ持ってきてほしい。俺が数えきれないくらい必要になりそうだ。", "そこにtin barは何本あるんだ、{class}？戦が終わったら、数え方を教えてくれる奴が必要になりそうだな。", "まあ、tin barsの数はちょうど合ってるみたいだな。俺をだまそうとするなよ、{class}! 数えると頭蓋骨が痛くなるんだ。さあ、俺はこの地金を山に積みに行く。お前は出かけて同じものをもっと持って帰ってこい。", 0xfe2e6fc8, 0x2780cd8a, 0x7acae7ff, 0x2f7584b3, 0xfa129c8f, "....." },
  [8545] = { "HordeはMithril Barsを必要としている！", "Mithril Barを20個、OrgrimmarのValley of SpiritsにいるSenior Sergeant T'kelahのところへ持って行ってください。", "{class}、戦争がやって来る。俺たちにできるのは、それに備えることだけだ。そこでお前と俺が助け合えるってわけよ、マン。ほら、俺たちが必要ないろんなものを作るのに要るmithril barsを全部集める係を、俺が任されたんだ。そんで、まだまだ足りねえんだよ！\n\nだから、お前が出かけて俺たちのためにミスリルを掘って、それを延べ棒に精錬してくれたらと思ってる。やってくれそうか？", "Ahn'Qirajの戦への備えに要るmithril barが全部揃ってりゃ、そりゃあいいんだがねぇ。だから戻ってきたんだろう、あんた？おれのbarは持ってきたかい？", "こいつはお前と俺にとっていい始まりだな、{class}。これでまた20本のmithril barsを山に積んで、リストに印をつけられるってわけだ。全部、軍需物資作りにしっかり役立てられるぜ。\n\n忘れずにまた俺のところへ確かめに来てくれよ。どうやら、そのmithril barsがもっと必要になりそうだからな。", 0x2123ee67, 0x718709db, 0x11eb5190, 0x4a6bef2f, 0x1becef77, "....." },
  [8549] = { "HordeはPeacebloomを必要としている！", "Peacebloomを20個、OrgrimmarのValley of SpiritsにいるHerbalist Proudfeatherのところへ持って行ってください。", "どの世代も、自らを決定づける試練に直面せねばならぬと言われている。Ahn'Qiraj Warこそ、我らの真価が試される坩堝となるのではないかと私は案じている。だから我らは備え、そうすることで、自分たちが何でできているのかを知るのだ。\n\n私は、戦争のための薬にできるよう、できる限り多くのpeacebloomを集めてHordeを助けると申し出た。君が私に力を貸すためにここへ来てくれたのならいいのだが。もしそうなら、その薬草をたっぷり持ち帰ってきてほしい。手伝ってくれるか、{class}？", "もうpeacebloomを持って戻ってきたのですか、{class}？", "こうして私たちの努力によって、戦いへとまた一歩近づくのです。このpeacebloomを懸命に集めてくれてありがとう、{class}。必ず役立てると約束しますし、あなたの貢献は心に留めておきますよ、{name}。その気があれば、どうかまたこの花を持って私のもとへ戻ってきてください。それまで、Earth Motherがあなたを導きますように。", 0x1be189a4, 0x2dfe9b56, 0x2b32de4d, 0xd2b20a86, 0x45e9daf7, "....." },
  [8551] = { "船長の宝箱", "Smotts' ChestをBooty BayのHecklebury Smottsのところへ持って行って下さい。", "かつて私はここからKalimdorのRatchetまで船を走らせていた。立派な評判を持つ、成功した船長だったのだ。\n\nそれが……\n\nあの呪われたsea giantsに破滅させられた！ 奴らは私の船を叩き壊し、乗組員を殺し、私を救命ボートに乗せてBooty Bayへ流したのだ。しかもgiantsの一体、Gorlashが私のCaptain's Chestを盗んでいった。嗅ぎタバコ入れにしたいんだとさ。ふざけおって！\n\nGorlashはここの東の海岸をうろついているそうだ。奴を見つけて私の箱を取り戻してくれ！ そうすれば、船長の感謝を得られるぞ。", "おう、{name}! Gorlashは見つかったか? あのchestは俺のお気に入りでな、隠し仕切りがあって、そこに俺の一番のお宝をしまってたんだ!", "見つけてくれたか! なんて幸せな日だ! ありがとう、{name}。宝箱が戻って、胸の炎も少しは収まったよ。\n\nだが、俺の復讐はまだ終わっちゃいない……", 0xba51aa97, 0x91038538, 0x167e029a, 0x06215b45, 0x6b909651, "....." },
  [8552] = { "名入りの飾り帯", "Monogrammed Sashを持ち主に返して下さい。", "この上等な飾り帯の裾には、「HS」という文字が刺繍されている。", "こんにちは。私に何か用ですか?", "俺の飾り帯を取り戻してくれたのか? ってことは……sea giantのMok'rashを倒したんだな! やったぞ!\n\nあの卑劣な悪党が死んでせいせいした。Mok'rashは、俺の船を叩き壊して乗組員を殺した3体のsea giantの1体だったんだ。\n\nそれも3度もだ。\n\nお前は価値ある{class}だ、{name}。", 0xf25f7e16, 0xaf626a54, 0xd7b275b4, 0x48a14437, 0xd35d9f2e, "....." },
  [8553] = { "船長のカトラス", "Sproggerと話して下さい。", "最初の船をあのgiantsに奪われた後、私はもう一隻買った。Smotts' Revengeと名付け、物資と乗組員を満載して悪党どもを探しに出た。奴らを見つけはしたが……負けてしまった。奴らはSmotts' Revengeを叩き壊し、二度目の乗組員を殺し、私をまた救命ボートに乗せたのだ。\n\n今度は別のgiant、Negolashが私のカトラスを盗んでいった。\n\nNegolashと対決して、私のカトラスを持ってきてくれ！\n\nSproggerと話すといい。彼はSmotts' Revengeの料理人で、この前の襲撃を生き延びた。giantを見つける手助けをしてくれるだろう。", nil, "やあやあ、{name}。Negolashを追うんだって、船長から聞いたぜ?", 0xb8962084, 0x114316b6, 0xb86aff68, nil, 0x2c14bb44, "...m." },
  [8554] = { "Negolashとの対決", "Barbecued Buzzard Wingsを$N1個とJunglevine Wineを$N2本、Captain Smotts' Lifeboatへ持って行って下さい。\n\nNegolashを倒し、Smotts' CutlassをStranglethornのCaptain Smottsのところへ持って行って下さい。", "Negolashは腹を空かせたgiantだ。\n\ngiantsが俺たちの船を壊したとき、Negolashはまっすぐ俺の厨房に向かった。奴は他のgiantsと違って、乗組員を食おうとはしなかった。Negolashが欲しがったのはワイン……それに俺のBarbecued Buzzard Wingsさ。あれは俺の得意料理で、レシピを手に入れるためにわざわざBadlandsまで行ったんだぜ！\n\ngiantをおびき寄せたいなら、ワインとbuzzard wingsを山ほど手に入れてくれ。それを、ここから南東の海岸沿いにある俺たちの古い救命ボートに置くんだ。Negolashがあの食い物の匂いを嗅ぎつけたら、きっとやって来るさ！", "俺のcutlassは手に入れたか、{name}?", "Negolashから俺のカトラスを取り返してくれたのか! この幸運が信じられないよ、{name}! あんたに会ってから運が上向いたんだ、間違いない!\n\nありがとう! もしまた新しい船を手に入れて、あんたが海を渡りたくなったら、名誉ある客人として迎えるよ。", 0x73a04fad, 0xeb22c78b, 0xcd78a826, 0x224ded7e, 0x423de715, "....." },
  [8555] = { "竜族の使命", nil, nil, nil, "Eranikus、Vaelastrasz、そしてAzuregos……定命の者よ、そなたもこれらのドラゴンのことは知っておろう。ならば、彼らがこの世界の見張り手としてこれほど大きな役割を果たしてきたのも偶然ではない。\n\n不幸にも(そしてその一端は我自身の未熟さにある)、Old Godsの手先によるものか、彼らを友と呼ぶはずの者たちの裏切りによるものか、守護者はみな悲劇に倒れた。その深さゆえに、我はそなたらの種族への不信を募らせてきたのだ。\n\n彼らを探し出せ……そして{race}よ、最悪の事態に備えるのだ。", 0x167d2c28, nil, nil, nil, 0x52b243f2, ".mmm." },
  [8556] = { "Signet of Unyielding Strength", "Qiraji Magisterial Ring・Lambent Idol 2つ・Bronze Scarab 5つ・Ivory Scarab 5つをSilithusのWindcaller Yessendraに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから称賛(Honored)の評判を獲得していなければなりません。", "Qirajiの副官たちが着けている指輪は、恐るべき能力を与えていると言われています。穢れた宝石で装飾されている指輪も、理論上、清らかな材料と交換することで穢れのないものとして作り直せるのです。\n\nQirajiの像を飾る宝石なら、優れた品質ですからうまくできるでしょう。\n\n指輪と像を持ってきて下されば、強力な指輪を作って差し上げますよ。{class}。", "指輪と材料は持ってきてくれたか、{name}？", "指輪の宝石を取り替えて差し上げましょう。完成品の方がはるかに……心地よいのが分かるでしょう。", 0x9615d9db, 0xb9e48325, 0x1bf57e0d, 0x43a13b9a, 0x31e56a0d, "....." },
  [8557] = { "Drape of Unyielding Strength", "Qiraji Martial Drape・Onyx Idol 2つ・Silver Scarab 5つ・Bone Scarab 5つをSilithusのKeyl Swiftclawに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから尊敬(Revered)の評判を獲得していなければなりません。", "Ahn'Qirajへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nQirajiのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。", "そのマントのための材料は持ってきたか、{name}？", "ああ、いいね……このマントは汚れひとつ無い。\n\nマントを持って行け、{name}。このマントがQirajiの穢れた魔法から君を守ってくれますように。", 0xda8e92d0, 0xa862c01a, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
  [8558] = { "Sickle of Unyielding Strength", "Qiraji Spiked Hilt・Alabaster Idol 2つ・Crystal Scarab 5つ・Stone Scarab 5つをSilithusのWarden Haroに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x75668cc8, 0xaa269a4a, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8565] = { "Arathiでの過去の勝利", nil, nil, nil, "ああ、そうだとも! Arathi Basinでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8566] = { "Arathiでの過去の勝利", nil, nil, nil, "ああ、そうだとも! Arathi Basinでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0x1b6fa606, nil, nil, nil, 0x84b7e476, ".mmm." },
  [8567] = { "Warsong Gulchでの過去の勝利", nil, nil, nil, "ああ、そうだとも! Warsong Gulchでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8568] = { "Warsong Gulchでの過去の勝利", nil, nil, nil, "ああ、そうだとも! Warsong Gulchでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0x2097f0b6, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8569] = { "Warsong Gulchでの過去の奮闘", nil, nil, nil, "ああ、そうだとも! Warsong Gulchでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8570] = { "Warsong Gulchでの過去の奮闘", nil, nil, nil, "ああ、そうだとも! Warsong Gulchでの君のこれまでの功績を、もちろん忘れたりはしないよ。", 0xddd58d46, nil, nil, nil, 0xbc373b8c, ".mmm." },
  [8575] = { "Azuregos's Magical Ledger", "Azuregos's Magical LedgerをTanarisのNarain Soothfancyに届けて下さい。", "台帳に書かれている言葉がひとつも理解できなかった。何の言語で書かれたものなのかすら分からなかった!", "おおおっ！魔法で脈打つやつだ！わたしに？", "<Narainが熱心に手紙を調べる。>\n\n見事だ、{race}! これは何だ? 私はDraconicなどこれっぽっちも読めないのでね。", 0xc2c92d43, 0x80d85f61, 0x99f204c4, 0xb9b60c82, 0x4aa3f14f, "....." },
  [8576] = { "帳簿の翻訳", nil, nil, nil, "まずは大事なことからだ、{name}! Azuregosがこの台帳に何を書いたのか解き明かさないと。\n\nあいつが君にarcanite buoyを作れと言って、これがその設計図だって? あいつがこれをDraconicで書くとは妙だな。あの老いぼれは、私がこんなちんぷんかんぷんを読めないことを知ってるんだ。\n\nこれを上手くやるには、私の遠見のゴーグルと、500ポンドのニワトリと、「Draconic for Dummies」の第II巻が要る。必ずしもこの順番じゃないけどね。", 0xe592afa5, nil, nil, nil, 0x51c828ad, ".mmm." },
  [8577] = { "かつての大親友、Stewvul", "Narain Soothfancyは、彼のかつての大親友Stewvulを見つけ、Stewvulが盗んだscrying gogglesを取り戻すよう求めています。", "何かを翻訳するとなると、私の占いのゴーグルが必要だ。あいにく、それはかなり前に、元・永遠の大親友Stewvulに盗まれてしまった。彼は私の心を5か所も傷つけ、それから私をここに置き去りにして朽ちるに任せたのだ。\n\n頼りになる水晶玉の力を借りて、彼の居場所を絞り込んだ。SilverpineのGreymane Wallか、もしくは今まさにBurning Legionに蹂躙されているOutlandの異界らしき場所のどちらかだ。彼を突き止めて、私のゴーグルを取り戻してきてくれ、{name}!", nil, "あいつが私を発見したなどと信じられん。Outlandへ行方をくらました時、確実にまいたと思ったんだがな。あそこへは戻らないぞ、{race}! 嫌なこった、どうあってもな! あいつのアルバイト親友でいるのも、常勤奴隷でいるのもこりごりだ。", 0xe9495a98, 0x1c91e108, 0x12f4ce40, nil, 0xc02bd526, "...m." },
  [8578] = { "占いゴーグル? 任せろ!", "Narain's Scrying Gogglesを見つけ、TanarisのNarain Soothfancyに返して下さい。", "<木箱から安堵のため息が漏れるのが聞こえる。>\n\nあいつのscrying gogglesが欲しいだけ? よし! それなら問題ないさ……ちょっと待ってくれ……あれ! どこに……ちくしょう!\n\nさて、悪い知らせと、もっと悪い知らせがある。悪い知らせは、ゴーグルをなくしちまったってことだ。もっと悪い知らせは、先月Molten Coreの中を嗅ぎ回ってたときになくしたってことさ。そう、Molten Coreだ……これで取引は終わりってことだな! じゃあな!", "Molten Coreだって？おれのゴーグルがまだ無事だといいんだがな！", "見事だ! さて、あの500ポンドの鶏と『Draconic For Dummies???』のVolume IIはどこへやったかな? ああ、それと、君の骨折りに少しばかりの物があるぞ!", 0xdc9ee9be, 0xdbf9e65b, 0x0ce9a2cd, 0xe9496a67, 0x5f3e7f98, "....." },
  [8579] = { "定命の戦士", nil, nil, "Ahn'Qirajのさらに奥深くに、囚われた同胞の気配を感じる。だが、竜の軍勢をもってしても彼らを救い出すには足りぬのだ、{race}。\n\n彼らを閉じ込めたのと同じ呪文が、我らがC'Thunにこれ以上近づけば、我らをその支配下に固く縛りつけるだろう。\n\nOld Godは我らの到来を予見していた。もはや望みはない。お前のようなただの定命の者に、いったい何ができるというのだ？", "そなたは普通の定命種ではないと分かっていたぞ、{name}よ。そなたらが古き神に勝つ見込みは限りなくわずかなものであったが、現時点では我らより大きかった。つまり、C'Thun は竜が間近に迫っていることは予期していたが、そなたらのような者への備えは無かったのだ。\n\n千年前に定命種と竜族とが手を組み、Anachronos と Staghelm が Qiraji を倒したのと同じように、我らも契約を成そう。Bronze Dragonflight の信頼を得よ、さすればそなたは我らの信頼を得る。そうして、そなたを真の戦士へと仕立て上げるのだ。", 0x8fe7b7d8, nil, nil, 0xd1ac67e9, 0x14403ef9, ".mm.." },
  [8580] = { "HordeはFirebloomを必要としている！", "Firebloomを20個、OrgrimmarのValley of SpiritsにいるBatrider Pele'keikiのところへ持って行ってください。", "おい、{class}。そう、お前だよ、マン！ HordeはこのAhn'Qirajの戦争のために、firebloomが山ほど要ると思ってるんだ。もしかしたら、ドカンといく素敵なもんに入れるのかもな？ もしかしたら、Allianceに蒸気戦車の燃料としてくれてやるのかもな？ 誰にも分からねえ！ Pele'keikiにも分からねえ！\n\nでもPele'keikiにはこれだけは分かる……お前がPele'keikiを手伝って、firebloomをたくさん持ってきてくれるってな。そうだろ、マン？", "Pele'keikiを怒らせたくないだろう。firebloomをたくさん、すぐに持ってきて、Pele'keikiを喜ばせるんだ。", "{class}! Pele'keiki、今はうれしい。Pele'keiki、firebloom全部、新鮮なまま箱に入れる。Pele'keiki、firebloom全部、戦争のためのいいものになるよう見張る。もっと手に入ったら、すぐPele'keikiに会いに来い。Pele'keiki、たぶんもっと要る。", 0x21f53256, 0x19b40e2b, 0x8d8f856d, 0x23203e8e, 0xa887a505, "....." },
  [8582] = { "HordeはPurple Lotusを必要としている！", "Purple Lotusを20個、OrgrimmarのValley of SpiritsにいるApothecary Jezelのところへ持って行ってください。", "purple lotusはな、{class}、実に多くの薬、秘薬、オイルの材料になるんだ。その中にはAhn'Qirajで我々の役に立つものもある。戦争のために、そうした薬を膨大な数作らなければならない。それに、lotusのさらなる使い道を見つける実験もするつもりだ。だがそのすべてをやるには、その花が大量に必要になる。\n\nそこでお前の出番だ。野に出て、purple lotusesをできるだけ多く集めてきてくれ。我々のためにやってくれるか？", "もう、私が頼んだpurple lotusを持って戻ってきたのですか、{class}？ここで私が試みていることすべてが無に帰さぬよう、できる限り速やかに事を運んでもらうことが肝要なのです。", "称賛に値する働きです、{class}。この標本を適切な用途に合わせて計量し、あなたの貢献を記録しておきます。purple lotusは、私が使う準備が整うまで適切に保管しなければなりません。あなたのほうは、まだ手が空いているなら、purple lotusはまだ必要になると思います。少ししたらまた確認しに来てください。", 0xa54234fd, 0x6fdc470f, 0xfd7d840c, 0xe33898f0, 0xfc3faaef, "....." },
  [8584] = { "仕事のことは絶対に聞くな", "TanarisのNarain Soothfancyは、GadgetzanのDirge Quickcleaveと話すよう求めています。", "私について一つ知っておくべきことがあるとすれば、これだ。私の仕事については決して尋ねるな! 私は君には到底理解できないものを扱っているのだ。たとえば、サイコトロニック・マズルドルフが何か知っているかね? もちろん知らないだろう! だからこそ、計画は私に任せ、取ってくるのは君に任せるというわけだ。\n\nさっきも言ったように、これをうまくやるには500ポンドのニワトリが必要になる。\n\nGadgetzanへ向かい、Dirge Quickcleaveと話してくれ。彼が適当な標本探しの手始めを手伝ってくれるだろう。", nil, "<Dirgeが頭を掻く。>\n\n500ポンドの鶏だと? そんなものはいない! 少なくとも、もういない。そういう鶏のことは知っていた……The Black Chicken of Death……\n\n<Dirgeの声が次第に消えていく。>\n\nだがまあ、あの鶏を見て生きて語り伝えた者はいない。お互いのためになる考えがあるんだ、坊主。", 0x0228ea0f, 0xa8c77109, 0xf36f8ea5, nil, 0xec6c3378, "...m." },
  [8585] = { "恐怖の島!", "TanarisのDirge Quickcleaveのために、Lakmaeran's CarcassとChimaerok Tenderloin 20個を取り戻して下さい。", "言い伝えによれば、FeralasのIsle of Dreadにいるchimaerokは、この世で最も汁気たっぷりで柔らかい食い物なんだとさ! で、そのchimaerokには親父がいてな、ちゃんと下ごしらえすれば、500ポンドのニワトリに見えるかもしれないし、見えないかもしれない。\n\nIsle of Dreadへ行ってLord Lakmaeranを倒し、奴の新鮮な死骸を持ってきてくれ。それであのノームは満足するだろう。俺を満足させるには、chimaerok tenderloinを手に入れてもらわなきゃならないがな。\n\nこれをやってくれたら、500ポンドのニワトリとちょっとしたおまけをやるよ。", "んんんん……Chimaerok……", "そのtenderloinsの霜降りを見ろ! 素晴らしい!\n\nさて、あの鶏のことだが……ふむ、そうだな。レシピを考え出すのに少し時間が要る。", 0x24bc1b42, 0x029dfd4c, 0x9b361af5, 0x89c31d53, 0xe0b0cb41, "....." },
  [8586] = { "Dirge's Kickin' Chimaerok Chops", "GadgetzanのDirge Quickcleaveは、Goblin Rocket FuelとDeeprock Saltをそれぞれ20個ずつ持ってくるよう求めています。", "俺のレシピは完成だ! お前さんに頼みたいのは、rocket fuelとdeeprock saltだ。スパイスは俺が用意するし、お前さんが持ってきてくれた肉で残りは足りる。\n\n頼んだものを持ってきてくれたら、Narainのところへ持って帰るニワトリの準備ができるぜ。", "急いでくれ、若いの。この肉を悪くさせたくはないからな。", "準備できたぞ! オレの最高の作品をあんたにあげるよ。Dirge's Kickin' Chimaerok Chopsだ!", 0x230ca266, 0xf28b79bb, 0x14982c96, 0x11989c2a, 0xf28ea97d, "....." },
  [8587] = { "Narainのもとへ", "TanarisのNarain Soothfancyへ500 Pound Chickenを届けて下さい。", "俺は約束を守るゴブリンだぜ、坊主。ほら、お前の500 pound chickenだ。\n\nノームが500ポンドのニワトリなんかで何をしたいのか、俺にはさっぱり分からねえ……\n\n<Dirgeは何か聞き取れないことをぶつぶつ言っている。>\n\nたぶん、その中で寝るんだろうよ……汚ねえノームどもめ……", "この美味そうな匂いは何だ？", "<Narainが両の拳を巨大な鶏に突っ込み、Dirgeの美味な珍味を顔いっぱいに頬張る。>\n\nうーん……信じられない! 今まで食べた中で最高の鶏だ!", 0xf0396dc8, 0x54a88bfc, 0xe556e25f, 0x7baa47b2, 0xa7fb1855, "....." },
  [8588] = { "HordeはHeavy Leatherを必要としている！", "Heavy Leatherを10枚、OrgrimmarのValley of SpiritsにいるSkinner Jamaniのところへ持って行ってください。", "戦争の準備をしてるんだから、まずは必要な品を全部揃えるのが一番だと思わないか、マン？ 俺たちが作ってる戦争物資の基本の一つが、heavy leatherだ。補強から鎧、それに昔ながらのただの防水布まで、ほとんど何にでも使うんだ。\n\nだがまずは、それをもっと手に入れなきゃならない。それがお前の仕事だ、{class}。ナイフを研いで、ひと束持ってきてくれ。話はそれからだ。", "無駄口を叩きに来ただけなら、遊んでいる暇はないんだ、{class}。なめさなければならないheavy leatherの束が山ほどある。少なくとも10束持ってから戻ってこい。", "ほう、私が必要としていたheavy leatherを本当に持ってきたのか。君の刃は実に鋭いな、{class}。これはいい革だ! こうして幸先の良い付き合いが始まったのだから、君の貢献はきちんと役立てるようにしよう。もしheavy leatherをもっと見つけたら、私のところへ持ってきてくれ。", 0x45f51bdb, 0x6655a94d, 0x423eaf25, 0x5e85eb55, 0xaedff7ae, "....." },
  [8590] = { "HordeはThick Leatherを必要としている！", "Thick Leatherを10枚、OrgrimmarのValley of SpiritsにいるSergeant Umalaのところへ持って行ってください。", "このことで話しに来てくれて嬉しいぞ、{class}。来たるAhn'Qiraj Warに向けたHordeの準備は、どうやら真っ最中のようだ。だが、お前と俺もまだ自分の役目を果たさなきゃならん。\n\n俺は、あらゆる戦争物資に使うthick leatherの皮をたくさん集めるよう頼まれている。お前には外に出て、それを集めて手伝ってほしい。手伝うと決めてくれたなら、名誉とHordeの感謝がお前のものになるぞ。やってくれるか？", "{class}、話し合った10枚のthick leatherを持って、もうこんなに早く戻ってきたのか？", "よくやった、{class}。このthick leatherの革は、きっと飛行船の補強や、あらゆる種類の防具や武器を作るのに使われるだろう。俺からも、Hordeからも感謝する。旅の途中でthick leatherをもっと見つけたらまた来てくれ。幸運を祈る。", 0xcf355a33, 0x41739670, 0x5c6d1af2, 0x67f46584, 0x6a629205, "....." },
  [8597] = { "Draconic for Dummies", "South Seasの島に埋もれたNarain Soothfancyの本を見つけて下さい。", "あの本がいつか役に立つと分かっていたんだ! ありがたいことに、私には安全な場所にしまっておく機転と先見の明があった。\n\n心配はいらない、誰にも見つけられっこない場所にあるからね! 最初にそこへ行くのにジャイロコプターが必要だったくらいさ。あいにく、帰る途中で浜辺に墜落させてしまったがね。その事故のおかげで、私はこの超ノーム的な超能力を手に入れたんだ!\n\nLand's End Beachのどこかにある私の墜落したジャイロコプターを探して、そこから南へ泳いでいくんだ! その場所は見ればすぐ分かるよ!", nil, "本は無くなっていた! 盛り土の上には手紙がある。", 0x05fce9d1, 0xe3e8e710, 0x8ad40ded, nil, 0x3f0d740a, "...m." },
  [8598] = { "ミのしろキン", "TanarisのNarain SoothfancyにRansom Letterを渡して下さい。", "<このメモの文字は、様々な書体の文字を羊皮紙の表面に貼り付けて作られている。>\n\nお前の大事な本は預かったぞ、ノーム。また見たければ、我々の言うとおりにしろ。\n\n<3ページにわたって、詳細な指示が書き連ねてある。>\n\n金を持って一人で来い!", "なあ、どうかしたのかい？", "<Narainの顔が真っ赤に輝く。>\n\n私の……本を誘拐するだと!? 超能力を持つノームにちょっかいを出すとはどういうことか、思い知らせてやる!", 0x84b8255d, 0xa2bf5f5d, 0xe466f082, 0x35954ada, 0x3e8a19c8, "....." },
  [8599] = { "Narainにラブソングを", "TanarisのNarain SoothfancyにMeridith's Love Letterを渡して下さい。", "訪ねてくる人なんてめったにいないのよ。実を言うと、最後に誰かが訪ねてきたのは、墜落した空飛ぶ機械の残骸から、あの愛しくて優しいノームを助け出したときだったわ。\n\n<Meridithは思い出に浸り、虚空を見つめている。>\n\n彼を知ってる? Narainよ。Narain Soothfancy。ああ、誰かが私の代わりに彼へ伝言を届けてくれたら、本当にうれしいわ。私の気持ちを伝えなきゃ! これは恋だって分かってるの! 絶対にそうなのよ!\n\nNarainに伝言を届けてもらえないかしら? ずっと恩に着るわ!", "魚臭いぞ！", "何だって!?\n\n<Narainがそわそわし始める。>\n\nいや、その……私にどうしろというのだ??? 彼女は魚なんだぞ! 魚だと言っているんだ! そして私はノームだ。うまくいくはずがない。", 0xb6a7fa19, 0xc21305f4, 0x7fd3c2fb, 0xbd590330, 0xd896a44a, "....." },
  [8600] = { "HordeはRugged Leatherを必要としている！", "Rugged Leatherを10枚、OrgrimmarのValley of SpiritsにいるDoctor Serratusのところへ持って行ってください。", "刃の鋭さより、ナイフが手のひらにどう収まるかのほうが大事だと私は思う。どんなになまくらな刃でも、きちんと力を込めれば切れるようになるものだ。そう思わないか、{class}？ だがお前も私も、常に最高に鋭い刃を保っているから、そんな問題とは無縁だろう？\n\nまあ、それはいい。お前に任務がある。Hordeに仕え、Ahn'Qirajの戦争のために自分の役目を果たすべく、rugged leatherの皮をいくらか持ってきてほしい。やってくれるな？", "私のためにrugged leatherを10枚剥ぎ取るのに、まさかこれほど時間がかかるはずがないだろう！皮はぎナイフを研いだ方がいいんじゃないか？それとも、私の思い違いで、もう鞄の中に入っているのか？", "よろしい、端のほうが少々ぼろぼろの革もあるようだが、まずまずの仕事をしたようだな。まあいい、任務は完了し、お前は報酬を得た。rugged leatherの束をまた見つけたら、必ず大至急私のところへ持ってくるように。", 0x21019bf3, 0xfa590648, 0x7470b114, 0xde61e0ab, 0x480d2c55, "....." },
  [8604] = { "HordeはWool Bandagesを必要としている！", "Wool Bandageを20個、OrgrimmarのValley of SpiritsにいるHealer Longrunnerのところへ持って行ってください。", "ようこそ、{class}。Ahn'Qirajでの戦争に備えて、私はここでwool bandagesを集めるHordeの取り組みを取りまとめています。残念ながら、戦場では、兵士たちは治癒師がいてくれることを当てにして命をつなぐわけにはいかないのです。信じてください、身をもって知っています。だからこそ、兵士たちのためにこうした救急箱を用意しているのです。\n\n時間があれば、wool bandagesがたくさん必要です。ここへ持ってきてくだされば、きちんと報酬が渡るよう取り計らいましょう。", "ああ、{class}、もうこんなに早くwool bandageを持って戻ってきたのですか？", "感謝するぞ、{class}。Hordeも感謝している。戦争にさらに貢献したいなら、wool bandagesをもっと見つけたらここの俺のところへ持ってこい。それまで、祖先がお前を見守らんことを!", 0xf92611a1, 0x03811185, 0x53103f9d, 0x30381a39, 0xfede6e5f, "....." },
  [8606] = { "囮作戦!", "TanarisのNarain Soothfancyは、Winterspringへ行き、誘拐犯が文書で指示した受け渡し地点へBag of Goldを置いてくるよう求めています。", "分かったぞ! こうしよう。私が袋に石を詰めるから、君がそれを置いてくるんだ。私が届けろと書いてあったのは分かっているし、実際そうするつもりさ――まあ、ある意味ではね。\n\n<Narainはあなたを上から下までじろじろと見る。>\n\nうん、君なら十分だ。このターバンとローブと石の袋を持って、Winterspringの受け渡し場所へ行くんだ。\n\nこの特製キットに必要なものは全部入れておいた。奴らが品物を受け取りに現れたら、始末してやれ! Narainにちょっかいを出すとどうなるか思い知らせてやるんだ!", nil, "我々は誘拐犯を甘く見ていたかもしれんな。", 0xc96e5672, 0xf7f7670e, 0x2c03a57f, nil, 0xdfeb8d35, "...m." },
  [8607] = { "HordeはMageweave Bandagesを必要としている！", "Mageweave Bandageを20個、OrgrimmarのValley of SpiritsにいるLady Callowのところへ持って行ってください。", "私に話しかけているということは、私が任された収集を手伝ってくれるということだな？ よろしい！ どんな手段でも――本当にどんな手段でもだ――mageweave bandagesをたっぷり集めてきてほしい。新品ならなおいいが、絶対に必要というわけではない。ここへ持ってきてくれ、{class}。そうすれば、きちんと報酬が渡るよう私自ら取り計らおう。", "しくじって私の面目を潰すなよ、{class}！話し合ったmageweave bandageを持って、できる限り早くここへ戻ってこい。", "意外だが、まあ許容範囲だ。お前の「能力」とやらを見くびっていたのかもしれんな、{class}。かもしれん、だが。お前はごく簡単な任務を果たしただけだが、それに見合わぬほどの報酬を受け取ることになる。だが調子に乗るなよ。本当に自分を証明したいなら、出かけてmageweave bandagesの束をもう一つ持ってくることだ。", 0x85d7d1ef, 0xfc829187, 0xcc7de5e3, 0xfc2fe283, 0x45db5f1e, "....." },
  [8609] = { "HordeはRunecloth Bandagesを必要としている！", "Runecloth Bandageを20個、OrgrimmarのValley of SpiritsにいるStoneguard Clayhoofのところへ持って行ってください。", "HordeとAllianceがAhn'Qirajでの戦争へ向けて突き進んでいるのは、避けられないことのようだ。驚いたことに、それは互いの戦争ではなく、silithidと、奴らを操っている何らかの勢力との戦争なのだ。これも驚いたことに、どちらの側も、戦争を勝ち抜くのに必要な資源を集めるため、自分の役目を果たしている。\n\n私は兵士たちに配るrunecloth bandagesを集めているが、助けがなければうまくいかないだろう。できればお前の助けが欲しい。手を貸してもらえるか、{class}？", "戦は間もなく来るでしょう、{class}。我々の収集の務めを助けるために時間と労を割いてくださり、感謝します。以前話したrunecloth bandageを手に入れたから戻ってきたのですか？", "お前はHordeの誇りだ、{class}。尽力に感謝する。本当にありがたいぞ! この新しい包帯をしまって、目標までどれくらい進んだか、もう一度数えなければならん。よければ、runecloth bandagesをもっと集めて、ここの俺のところへ持ってきてくれ。", 0x3e4ef45d, 0xa2dfa378, 0xecf0977e, 0x5bed4ced, 0xc35c53f8, "....." },
  [8611] = { "HordeはLean Wolf Steaksを必要としている！", "Lean Wolf Steakを20個、OrgrimmarのValley of SpiritsにいるBloodguard Rawtarのところへ持って行ってください。", "いい日焼けをするためにここに突っ立ってるわけじゃないんだ、{class}。やるべき戦争の準備があるんだよ。Ahn'Qirajであの虫けらどもを叩き潰すつもりなら、備えておかなきゃならない。それには食料も含まれるんだ！\n\n俺はここで、来たる戦争のためにlean wolf steaksを集めて塩漬けにする役目を任されてる。だが俺はここに残ってこれを全部片付けなきゃならないから、お前に出かけて狼を何匹か仕留めて、その肉をlean wolf steaksに料理して、ここへ持ってきてほしいんだ。全部分かったか？", "もうそのlean wolf steakを持って戻ってきたのか、{class}？焼きすぎだろうが生だろうが構わん、とにかく美味けりゃいい、早く持ってこい！", "よし、この肉の山は良さそうだ。塩漬けにしてからしまっておくよ。その時が来たときに食べられるくらい新鮮なままだといいんだけどね。\n\n貢献ありがとう、{class}。もう一山持ってきてもらえるかな?", 0x3f7a77c1, 0x9085e187, 0x42e32ed7, 0x55f13fe2, 0x07b46faf, "....." },
  [8613] = { "HordeはSpotted Yellowtailを必要としている！", "Spotted Yellowtailを20個、OrgrimmarのValley of SpiritsにいるFisherman Lin'doのところへ持って行ってください。", "釣りにはいい日だな、そう思わねえか、マン？ ちょうどいい、どうやら魚がたくさん要りそうだからな。Hordeの連中が、spotted yellowtailを山ほど集める係を俺に任せたんだ。Ahn'Qirajで準備してる戦争に必要だって言うのさ。俺はできるだけのことはするって言ったんだ。だから助けが要るんだよ。手伝ってくれるか、{class}？", "もうspotted yellowtailを持って戻ってきたのかい、{class}？ちゃんと美味そうに焼くのを覚えてたかい？暑い砂漠の日差しの下にいる兵士たちに生の魚を出すわけにはいかないからねぇ。", "おお、これはいい品だ。無駄にならんよう、しっかり包んでおくぞ。こうして助けてくれて、感謝するよ。これだけのspotted yellowtailを獲ってくるとは、あんたは一流の釣り人だと思うね。それに、もしもっと釣って料理することがあったら、ここの俺に持ってきな。あんたのおかげだと、みんなに知らせてやるからよ!", 0xb7ab612a, 0x6fb7910e, 0x4f8ae337, 0x8a809e6f, 0x35f42517, "....." },
  [8615] = { "HordeはBaked Salmonを必要としている！", "Baked Salmonを20個、OrgrimmarのValley of SpiritsにいるChief Sharpclawのところへ持って行ってください。", "Ahn'Qirajの戦争準備は途方もない大事業だ、{class}。ここで集められているすべての物資は、武器のための金属であれ、食べるための食料であれ、どれも同じくらい重要なのだ。何日も食べていなければ、肝心な時に斧を持ち上げる力も出ないのだからな。\n\nだから、我々は集められるだけの食料を集めている。私が集めているのはbaked salmonだ。栄養があり、日持ちもするという理由で選ばれた料理だ。この仕事を手伝ってくれるか、{class}？", "sprite dartersは怒らせると危険な生き物だ。相手にするときは気をつけろ、{class}。それに、この辺りにいるナイトエルフにはもっと気をつけろ。あの厄介な馬鹿どもも森に潜んでいることが多いからな。\n\nwingsが十分に集まったら知らせてくれ。たっぷり報酬をはずんでやる!", "素晴らしいです、{class}! これで十分です。Korrinのためのマントを作るのに足りるだけありますし、もっと作れるかもしれません! ありがとう。\n\n道中はあまり危険ではありませんでしたか? Feralasの地は容赦のないことで知られていますが、あなたは見事にやり遂げたようですね。\n\n改めてありがとう、{class}。", 0x742e218a, 0xf3655658, 0x89dae190, 0xeb9d3196, 0x75713903, "....." },
  [8617] = { "HordeはSinged Corestonesを必要としている！", "singed corestoneを50個、DurotarにいるGeneral Zogのところへ持って行ってください。", "Ahn'Qirajの戦争に貢献する時が来たぞ、{class}。のんびりと時を過ごしていた平穏な日々は終わった。今こそ私とHordeに仕える時だ。言っておくが、私は大族長ほど寛大ではないぞ。\n\n戦力を集めろ。ギルドがあるならギルドをだ。そしてMolten Coreに攻め込め。中に入れば、そこの住人どもが焦げたcorestonesを持っているのが分かるだろう。それを大量に持ち帰ってこい。", nil, nil, 0xaf5e26b5, 0x34ebf112, 0xeb5dca4a, nil, nil, "...mm" },
  [8619] = { "Morndeep the Elder", nil, nil, nil, "この地の人々が古き種族にまだ敬いの心を持っていると分かって良かった。歓迎するぞ、{name}よ。記念の品をそなたに授けよう……。", 0x2a5020ee, nil, nil, nil, 0xdc5611ad, ".mmm." },
  [8620] = { "唯一の指示", "Draconic for Dummiesの無くなった8つの章を取り戻し、Magical Book Bindingで綴じて、Draconic for Dummies: Volume IIの完全本をTanarisのNarain Soothfancyに返して下さい。", "分かっていたはずだった。私の宿敵、Doctor Weavilがまたいつもの手を使ったんだ! しかも、Winterspringで君がしくじったせいで、Doctor Weavilは私の本を破壊してしまった! これでどうやって世界を救うつもりだい、英雄殿?\n\n届いたメモによれば、現存する唯一の「Draconic for Dummies: Volume II」は8つに引き裂かれて、風に撒き散らされたそうだ! もし何とかしてその失われた章を見つけられたら、この魔法の綴じ具を使って元どおりに綴じ合わせ、私のところへ戻ってきてくれ。", "おれだってあんたと同じようにズボンを履く——1度に片足ずつな。違うのは、ズボンを履き終えたらarcanite buoyを作るってことだ。arcanite buoyだぜ、ベイビー！", "素晴らしい! そんな面倒をやり遂げるとは信じられない! 君は何かの機械なのか? 私だったら、おそらく世界が崩れ落ちるに任せていただろうね。\n\n君にターバンを取って敬意を表するよ。それに、善行が報われずに終わっていいはずがない。", 0xed078484, 0xc2e70399, 0x965d5a35, 0x7b6b4d71, 0x8d7b1131, "....." },
  [8635] = { "Splitrock the Elder", nil, nil, nil, "過ぎ去った昔の戦いは、伝説が育つ種なのだ。そなたの時代は英雄の時代だ、若者よ。そなたの伝説が根付き、大きく育ちますように。\n\n歓迎するぞ、{name}よ。記念の品をそなたに授けよう……。", 0xca99c5d4, nil, nil, nil, 0x570dc313, ".mmm." },
  [8636] = { "Rumblerock the Elder", nil, nil, nil, "命は死んで土に還る宿命にあるが、魂は永遠に生き続ける。歓迎するぞ、{name}よ。記念の品をそなたに授けよう……。", 0x8ee1d31b, nil, nil, nil, 0x62d528f4, ".mmm." },
