  [8686] = { "High Mountain the Elder", nil, nil, nil, "若き{class}よ、そなたの魂は命で輝いている。そなたが示してくれた敬いの心は受け取った。お返しに記念の品を授けよう……。", 0x2825953c, nil, nil, nil, 0x441923fb, ".mmm." },
  [8688] = { "Windrun the Elder", nil, nil, nil, "天は、その数えきれぬ星々の中に、地上の謎への答えを秘めている、{name}。ならば、賢き者、そして幸運な者は、天を仰いで真理を見出せるのではないか？", 0x204f5248, nil, nil, nil, 0x3da1f0cc, ".mmm." },
  [8689] = { "Shroud of Infinite Wisdom", "Qiraji Martial Drape・Jasper Idol 2つ・Gold Scarab 5つ・Clay Scarab 5つをSilithusのKeyl Swiftclawに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから尊敬(Revered)の評判を獲得していなければなりません。", "Ahn'Qirajへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nQirajiのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。", "そのマントのための材料は持ってきたか、{name}？", "ああ、いいね……このマントは汚れひとつ無い。\n\nマントを持って行け、{name}。このマントがQirajiの穢れた魔法から君を守ってくれますように。", 0x7213a736, 0x5493a2f1, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
  [8690] = { "Cloak of the Gathering Storm", "Qiraji Regal Drape・Obsidian Idol 2つ・Clay Scarab 5つ・Gold Scarab 5つをSilithusのKeyl Swiftclawに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから尊敬(Revered)の評判を獲得していなければなりません。", "Ahn'Qirajへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nQirajiのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。", "そのマントのための材料は持ってきたか、{name}？", "ああ、いいね……このマントは汚れひとつ無い。\n\nマントを持って行け、{name}。このマントがQirajiの穢れた魔法から君を守ってくれますように。", 0xa9ab60dc, 0x25f6371e, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
  [8691] = { "Drape of Vaulted Secrets", "Qiraji Martial Drape・Alabaster Idol 2つ・Stone Scarab 5つ・Crystal Scarab 5つをSilithusのKeyl Swiftclawに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから尊敬(Revered)の評判を獲得していなければなりません。", "Ahn'Qirajへの攻撃を支援してくれていると聞いて嬉しいよ、{name}。私なら、我々の敵との戦いの役に立つ防御用の品を作れるよ、{class}。\n\nQirajiのマントが必要だな。もちろん、君用のサイズに作り直すつもりさ。像とスカラベも要る。そっちは留め具を作るのに使うんだよ。\n\n期待は裏切らないと誓うよ。", "そのマントのための材料は持ってきたか、{name}？", "ああ、いいね……このマントは汚れひとつ無い。\n\nマントを持って行け、{name}。このマントがQirajiの穢れた魔法から君を守ってくれますように。", 0xc2fd8562, 0x4f289f43, 0x841bdde5, 0xde8b9b39, 0x67472b1a, "....." },
