  [8707] = { "Blade of Vaulted Secrets", "Qiraji Ornate Hilt 1つ・Obsidian Idol 2つ・Silver Scarab 5つ・Bone Scarab 5つをSilithusのWarden Haroに渡して下さい。このクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x7a7f863c, 0xb6fa7160, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
