  [8709] = { "Dagger of Veiled Shadows", "Qiraji Spiked Hilt・Vermillion Idol 2つ・Gold Scarab 5つ・Clay Scarab 5つをSilithusのWarden Haroに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x6c216880, 0x883e843d, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8710] = { "Kris of Unspoken Names", "Qiraji Ornate Hilt・Onyx Idol 2つ・Gold Scarab 5つ・Clay Scarab 5つをSilithusのWarden Haroに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x2c4c7958, 0x250427ad, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8711] = { "Blade of Eternal Justice", "Qiraji Spiked Hilt・Amber Idol 2つ・Bronze Scarab 5つ・Ivory Scarab 5つをSilithusのWarden Haroに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x4bcb3a8a, 0xa5680b54, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8712] = { "Scythe of the Unseen Path", "Qiraji Spiked Hilt・Azure Idol 2つ・Silver Scarab 5つ・Bone Scarab 5つをSilithusのWarden Haroに渡して下さい。\n\nこのクエストを達成するには、Cenarion Circleから賛美(Exalted)の評判を獲得していなければなりません。", "Qirajiとその下僕たちは極めて貴重な最高の素材で作られた品を振るっている。巨大な古の生物の骨や、大地の奥深くから掘り出された宝石や、純粋で強い金属といったような。\n\nまさにQirajiの秘宝の姿は、あれをばらばらに砕いて溶かして自分の作品を作り上げたいという衝動を湧き上がらせるよ。{name}、Cenarion Circleへの忠誠を示してくれれば、Qirajiの最高の素材を使って強力な武器を作ってあげるよ。", "私が必要とする部品は持ってきてくれたか、{name}？", "よくやったな{class}。これは最高傑作の柄だ……均整も完璧にとれている。\n\n{name}、君の武器を持っていけ。大きな信頼をもってこれを振るい、敵を打ち倒せ!", 0x74182cc0, 0xe8c23020, 0xbec045e9, 0x31fe20fc, 0xebafe37f, "....." },
  [8713] = { "Starsong the Elder", nil, nil, nil, "天は、その数えきれぬ星々の中に、地上の謎への答えを秘めている、{name}。ならば、賢き者、そして幸運な者は、天を仰いで真理を見出せるのではないか？", 0x406f03a9, nil, nil, nil, 0x3da1f0cc, ".mmm." },
