  [8917] = { "真面目な提案", "Silithus Venom Sample15個と20GoldをShadowcraft Bracersとセットにして、OrgrimmarのMokvarに渡して下さい。", "やあ{class}! 君の様子を見ていれば、世界中で見聞きし多くの事を成し遂げてきたのが分かる。けれど、こんな鎧は見たことがないに違いない。\n\n私の願いを聞いてくれたら、ありふれた小手とこれを取り替えてあげよう。\n\nSilithusに住む蜘蛛やサソリから抽出した毒のサンプルが大量に必要なんだ。いくらかの金貨と一緒に持ってきてくれたら、交換してあげるよ。", "私が必要としている品は手に入れたか、{name}？", "ああ、そうだ。Muxはこれに大いに喜ぶだろう。\n\nあのbracersは、もっと大きな防具一式の一部だった。さらに手を貸してくれる気があるなら、残りを手放すことも考えてもいい。", 0x5744ae45, 0xb2f01d1e, 0xea675b9d, 0x200db369, 0xa658e962, "....." },
  [8918] = { "真面目な提案", "Silithus Venom Sample15個と20GoldをBindings of the Elementsとセットにして、OrgrimmarのMokvarに渡して下さい。", "やあ{class}! 君の様子を見ていれば、世界中で見聞きし多くの事を成し遂げてきたのが分かる。けれど、こんな鎧は見たことがないに違いない。\n\n私の願いを聞いてくれたら、ありふれた小手とこれを取り替えてあげよう。\n\nSilithusに住む蜘蛛やサソリから抽出した毒のサンプルが大量に必要なんだ。いくらかの金貨と一緒に持ってきてくれたら、交換してあげるよ。", "私が必要としている品は手に入れたか、{name}？", "ああ、そうだ。あの老いぼれゴブリンは、この血をさぞ喜ぶことだろう。\n\nあの腕甲は、もっと大きな鎧一式の一部だったのだ。さらに手を貸してくれる気があるなら、残りを手放すことも考えてやってもいい。", 0x5744ae45, 0x42654b5d, 0xea675b9d, 0x200db369, 0x727ead4e, "....." },
  [8919] = { "真面目な提案", "Silithus Venom Sample15個と20GoldをDreadmist Bracersとセットにして、OrgrimmarのMokvarに渡して下さい。", "やあ{class}! 君の様子を見ていれば、世界中で見聞きし多くの事を成し遂げてきたのが分かる。けれど、こんな鎧は見たことがないに違いない。\n\n私の願いを聞いてくれたら、ありふれた小手とこれを取り替えてあげよう。\n\nSilithusに住む蜘蛛やサソリから抽出した毒のサンプルが大量に必要なんだ。いくらかの金貨と一緒に持ってきてくれたら、交換してあげるよ。", "私が必要としている品は手に入れたか、{name}？", "ああ、そうだ。Muxはこれに大いに喜ぶだろう。\n\nあのbracersは、もっと大きな防具一式の一部だった。さらに手を貸してくれる気があるなら、残りを手放すことも考えてもいい。", 0x5744ae45, 0x7f9ef117, 0xea675b9d, 0x200db369, 0xa658e962, "....." },
  [8920] = { "真面目な提案", "Silithus Venom Sample15個と20GoldをBracers of Valorとセットにして、OrgrimmarのMokvarに渡して下さい。", "やあ{class}! 君の様子を見ていれば、世界中で見聞きし多くの事を成し遂げてきたのが分かる。けれど、こんな鎧は見たことがないに違いない。\n\n私の願いを聞いてくれたら、ありふれた小手とこれを取り替えてあげよう。\n\nSilithusに住む蜘蛛やサソリから抽出した毒のサンプルが大量に必要なんだ。いくらかの金貨と一緒に持ってきてくれたら、交換してあげるよ。", "私が必要としている品は手に入れたか、{name}？", "ああ、そうだ。Muxはこれに大いに喜ぶだろう。\n\nあのbracersは、もっと大きな防具一式の一部だった。さらに手を貸してくれる気があるなら、残りを手放すことも考えてもいい。", 0x5744ae45, 0x9ca9a24b, 0xea675b9d, 0x200db369, 0xa658e962, "....." },
  [8921] = { "Ectoplasmic Distiller", "Delicate Arcanite Converter 1つ・Greater Eternal Essence 4つ・Stonescale Oil 10個・Volcanic Ash 25個・金貨40枚を、GadgetzanのMux Manascramblerに渡して下さい。", "ああ、私の最新のプロジェクトが必要なんだね……異次元幽霊暴露装置だ! あいにく、資金も人手も尽きてしまってね。\n\n手伝ってくれるって? 素晴らしい! 最初の仕事は、死そのものの構造を採取する装置を作ることだ! エクトプラズム蒸留器を作るのは簡単な仕事じゃないよ、{name}。\n\narcanite converterと、greater eternal essencesをいくつか、それにstonescale oilを持ってきてほしい。フィルターを作るために、Burning Steppesの溶岩溜まりからvolcanic ashもいくらか必要だ。", "材料が少々値の張るものだということは分かっている……だが、その一つ残らずが必要になると約束しよう！", "これこそまさに私が必要としていた材料だ。しかも実に良い頃合いだ、{name}!\n\nほんのわずかな間で、君のdistillerを使える状態にしてみせる! その間に、私の計画を手伝ってくれた報酬としてこれを受け取ってくれ。", 0xca7ea5e2, 0x7afb86a2, 0x2aa4ed53, 0x08e024f2, 0x90856cbc, "....." },
  [8922] = { "超常的装置", "GadgetzanのMux ManascramblerにSealed Blood Containerを渡して下さい。", "Anthion Harmonと話す方法を見つけなければ……もっと正確に言えば、彼の幽霊とね!\n\n超自然的なものに妙な興味を持っている技術者を知っているの。彼は死者と話せる機械を作れると言っているわ!\n\nあなたが集めてくれた血は彼のためのものだったの。Gadgetzanへ行って、彼の仕事への支払いとしてそれを届けてちょうだい!", "私に何か持ってきたのか？", "素晴らしい! ちょうど残り少なくなっていたところだ!\n\nDelianaに遣わされたと言ったか?", 0x412537f1, 0xedba7f2d, 0x51fbab6c, 0x25136523, 0x1185e9c7, "....." },
  [8923] = { "超常的装置", "GadgetzanのMux ManascramblerにSealed Venom Containerを渡して下さい。", "あんなことがあった後も残ってくれたなんて、あなたはよほど勇敢なのね。それとも、私があげた鎧で興味を引かれたのかしら。まだ私を助けてくれる気があるなら、あれと同じものがまだあるわ。\n\nあなたが集めてくれた毒の見本は、私の知り合いのMux Manascramblerのためのものよ。超自然的なものに興味を持っている技術者なの。彼の最新のプロジェクトは、死者と交信できる装置なのよ! 私の最後の望みは、Anthionと連絡を取って、私の状況についてもっと知ることなの。", "私に話があるのか？", "素晴らしい! ちょうど残り少なくなっていたところだ!\n\nMokvarに遣わされたと言ったか?", 0x412537f1, 0x0179231f, 0x60995f12, 0x7f7a3875, 0x50480f76, "....." },
  [8924] = { "エクトプラズム狩り", "実体を持たないアンデッドの近くでEctoplasmic Distillerを使い、SilithusでScorched Ectoplasmを、WinterspringでFrozen Ectoplasmを、Eastern PlaguelandsでStable Ectoplasmをそれぞれ12個集めて下さい。集めたエクトプラズムとEctoplasmic Distillerを持って、GadgetzanのMux Manascramblerのところへ戻って下さい。", "我ながら見事な技術の作品だ! 残念だが、我々が必要とする実体のないアンデッドを見つけるには、少しあちこち旅をしてもらう必要がある。\n\nいいかい、気候が違えば、死者の霊的な構造の濃さも違ってくるんだ。Silithusの苦しめられたナイトエルフ、Winterspringのhighborneの霊、それにEastern Plaguelandsの幽霊とbansheesから、我々に必要な様々な種類のエクトプラズムが手に入るはずだ。採取する前に、必ず近くに蒸留器を置いておくんだよ!", "ectoplasmはもう集めたか、{race}？", "よし、これなら申し分ない!\n\nこれらの物質に含まれる異界の力を引き出すことで、まだこの世を完全に去ってはいない魂たちに手を伸ばせるようになるのだ!", 0x0fc2cb8b, 0xed53890c, 0xca00eb5e, 0xa00f7f05, 0xf391f891, "....." },
  [8925] = { "携帯動力源", "Burning SteppesでMagma Lord Bokkを見つけ、そのMagma Coreを手に入れてGadgetzanのMux Manascramblerに渡して下さい。", "次に、エクトプラズムを活性化させておくための、安定していて持ち運びのできるエネルギー源を見つけなければならない。Magma Lord Bokkという強力なエレメンタルの噂を聞いたことがある。その心臓は強力なmagma coreで、尽きることのない熱の源なんだ!\n\n奴はBlackrock Mountainの南、Burning Steppesにいるそうだ。magma coreを私のところへ持ってきてくれれば、異次元幽霊暴露装置を動かすのに十分な力が手に入るぞ!", "Magma Lordは見つかったか、{name}？", "よくやった! 別次元幽霊暴露機の電源を入れるのに充分なエネルギーが供給できるに違いない!", 0x96babea4, 0xae4979d0, 0x192fdaac, 0x49af06a5, 0x44cb2363, "....." },
  [8926] = { "順当な報酬", "IronforgeのDelianaにWildheart BeltとWildheart Glovesを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0xaf7ff1c4, 0xce2da401, 0x6608fbe7, 0x86434e09, "....." },
  [8927] = { "順当な報酬", "OrgrimmarのMokvarにWildheart BeltとWildheart Glovesを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0x2338cd92, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8928] = { "小狡い商人", "Winterspring南部のDarkwhisper Gorge入り口にある洞窟内のインプを探し、Fel Elemental Rodを購入してGadgetzanのMux Manascramblerのところへ戻って下さい。", "coreがあれば装置を動かすのに十分な力が得られる。あとは、溶けずにそのエネルギーを導けるロッドを作るだけだ。\n\nWinterspringで、あらゆる珍しい品を売っているimpに会ったことがある。そいつは申し分のないelemental rodを持っていた。あのとき買っておかなかったことを、今になって悔やんでいるよ。\n\nそいつはDarkwhisper Gorgeの入口にある洞窟の中に住んでいる。こっそり忍び込んで、そいつを探してみてくれ。\n\n40ゴールドしか払わないようにするんだぞ。私にはその値段を言ったんだから!", "Darkwhisper Gorgeのimpを見つけられたか？", "やったな! このロッドなら完璧に作動するだろう。それじゃ全部まとめてみよう……", 0xeae65424, 0x07ca052e, 0xbd11b68d, 0xb8bde3dd, 0x602973b0, "....." },
  [8929] = { "Anthionを探して", "Stratholmeの入口でExtra-Dimensional Ghost Revealerを使い、Anthion Harmonの幽霊と話して下さい。", "さて、我々に残された手は、あのゴブリンの発明品を試してみることだけね。噂では、AnthionはStratholmeの門に入ろうとしたところを、アンデッドの軍勢に薙ぎ倒されたそうよ。\n\nそこで装置を使って、Anthionが知っていたことを突き止めてちょうだい。", nil, "Delianaが私に連絡を取るよう言ったのか？ できる限り力になろう。だがその前に、ひとつ大きな頼みを聞いてもらわねばならない。", 0xfd59b646, 0x1041fc47, 0x9d147007, nil, 0xa296c55d, "...m." },
  [8930] = { "Anthionを探して", "Stratholme入口でExtra-Dimensional Ghost Revealerを使い、Anthion Harmonの幽霊と話して下さい。", "よろしい、{name}。あとはあのゴブリンの発明品を試してみるだけだ。噂によれば、AnthionはStratholmeの門に入ろうとしたところを、そこのアンデッドの軍勢に殺されたという。\n\nそこでその装置を使ってみて、本当に死者と話せるかどうか確かめてくれ!", nil, "Mokvarが接触するよう差し向けたのかい? 君を手伝うよう最善は尽くすつもりだけど、始めにぜひ頼みたいことがあるんだ。", 0xfd59b646, 0x1041fc47, 0x0b58c1d6, nil, 0x5dd4c414, "...m." },
  [8931] = { "順当な報酬", "IronforgeのDelianaにBeaststalker's BeltとBeaststalker's Glovesを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0x67e7b8c8, 0x6a914bc9, 0x6608fbe7, 0x86434e09, "....." },
  [8932] = { "順当な報酬", "IronforgeのDelianaにMagister's BeltとMagister's Glovesを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0x6d622b41, 0x6a914bc9, 0x6608fbe7, 0x86434e09, "....." },
  [8933] = { "順当な報酬", "IronforgeのDelianaにLightforge BeltとLightforge Gauntletsを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0x7329ffd8, 0x35c57e0b, 0x6608fbe7, 0x86434e09, "....." },
