  [8936] = { "順当な報酬", "IronforgeのDelianaにDreadmist BeltとDreadmist Wrapsを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0x9687a99f, 0xce2da401, 0x6608fbe7, 0x86434e09, "....." },
  [8937] = { "順当な報酬", "IronforgeのDelianaにBelt of ValorとGauntlets of Valorを渡して下さい。", "あなたは約束を守って、Muxの作った装置を持ってきてくれた。難を逃れようと考えてあなたを雇うのなら、それに見合う報酬を渡すのが順当だと信じているわ。性能を上げたいベルトとグローブを持ってきてちょうだい。お返しに渡す物は、より優れた物になっていると約束するわ。", "取引をする用意はできているか？", "あなたはきちんと責任を果たしてくれたわ。私も約束を守ることにしましょう。\n\nあなたの仕事が終わるまでは、一番いい部分は私が持っているということを覚えておいてね。", 0x467758ec, 0xb902f02b, 0x35c57e0b, 0x6608fbe7, 0x86434e09, "....." },
  [8938] = { "順当な報酬", "OrgrimmarのMokvarにBeaststalker's BeltとBeaststalker's Glovesを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0xf910b600, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8939] = { "順当な報酬", "OrgrimmarのMokvarにMagister's BeltとMagister's Glovesを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0xeb6d7e34, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8940] = { "順当な報酬", "OrgrimmarのMokvarにDevout BeltとDevout Glovesを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0x663cecb3, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8941] = { "順当な報酬", "OrgrimmarのMokvarにShadowcraft BeltとShadowcraft Glovesを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0xce54935e, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8942] = { "順当な報酬", "OrgrimmarのMokvarにCord of the ElementsとGauntlets of the Elementsを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0xefd34ff4, 0x8e2fd8f3, 0x022eedef, 0x61802695, "....." },
  [8943] = { "順当な報酬", "OrgrimmarのMokvarにDreadmist BeltとDreadmist Wrapsを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0x36005819, 0xd0d70463, 0x022eedef, 0x61802695, "....." },
  [8944] = { "順当な報酬", "OrgrimmarのMokvarにBelt of ValorとGauntlets of Valorを渡して下さい。", "{name}、君は実に頼りがいのある人物だということを証明してくれた。苦境にあっても君なら手伝ってくれると信じているが、実績に応じて報酬を渡すのは賢明だと思う。\n\n今のところ、ベルトとグローブを交換するつもりだ。我々が苦境を乗り越えて最後までやり遂げたなら、残りの部分も使えるようにしてあげよう。", "交換をする用意はできているか？", "我々の契約は依然有効なままだ。覚えておくといい、これは君を待ち受ける些細なものに過ぎない。この呪われた運命から解放してくれ。そうすれば、真に強大な力を秘めた品々を君に渡そう。", 0x467758ec, 0xd299b66d, 0x8e2fd8f3, 0x022eedef, 0x61802695, "....." },
  [8945] = { "死せる男の願い", "Stratholmeへ行き、Baron RivendareからYsida Harmonを救って下さい。", "お前が求める情報は与えてやろう、{name}。だが、もっと差し迫った問題がある。\n\n愛する妻が、Rivendareのアンデッドのクズどもに捕らえられてしまったのだ。\n\n彼女がArgent Dawnの愚かな聖戦に加わることには強く反対したが、今となってはそんなことはどうでもいい。私がやろうとしたことを、お前が成し遂げてくれ。男爵の手からYsidaを救い出すのだ!", "教えてくれ、Ysidaは生きているのか？", "助けてくれてありがとう……命が危ういと思っていた。どうか、ささやかな感謝のしるしとしてこれを受け取ってくれ。\n\nAnthionが……いや……そんなはずは……", 0x6a2a5250, 0x1d4c6d9f, 0x6ab2edc3, 0x80f73718, 0x410f8d83, "....." },
  [8946] = { "生きている証拠", "Eastern PlaguelandsのAnthion HarmonにYsida's Locketを渡して下さい。", "私の愛する人が、私を救おうとして命を落としたなんて、何と残酷な運命でしょう。それでも、あなたは彼と話す力を持っていると言うのですね。\n\n私が無事である証として、このロケットを彼に届けてください。彼がこの世にとどまっていてはいけません。私の心はそれに耐えられないでしょう。\n\nさようなら、{name}。このご恩はいつまでも忘れません。", "Ysida……彼女は生きているのか？", "そのlocket……彼女を見つけてくれたのだな! ようやく安らかに眠れる。\n\n今からあなたのどんな問いにも答えよう、{name}。だが急いでくれ、この世に残された私の時間は長くない。", 0x64e5d7a9, 0x5380237f, 0xa5e26c5b, 0x7ff73a33, 0xfb9f7ead, "....." },
  [8947] = { "Anthionの奇妙な依頼", "Dark Iron Bar 3本・Enchanted Leather 20枚・Mooncloth 3枚・Cured Rugged Hide 4枚をEastern PlaguelandsのAnthion Harmonに渡して下さい。", "我々はValthalakのメダルの重要性に気づいていなかったので、他の戦利品と一緒に分けてしまったのだ。最初の欠片はTheldrenという名のドワーフが持って行った。私は奴からそれを取り戻そうとしたが、半殺しの目に遭わされた。欠片は力ずくで奪うしかないだろう。\n\n最後に聞いた話では、奴はDark Ironのドワーフの剣闘士になったそうだ。だが、奴をお前と戦わせるのは少々骨が折れるだろう。\n\n次の材料を集めてきてくれ。必要になるはずだ。", "頼んでおいた材料は手に入れたか、{name}？", "いいね。これをもっと目的に合った物へ変換しよう。", 0x09d2eb99, 0xdc29bb29, 0x0913d249, 0xa7af49ab, 0x6dc999eb, "....." },
  [8948] = { "Anthionの旧友", "未完成のBanner of Provocationを、Dire Maulの図書館にいるFalrin Treeshaperのところへ持って行って下さい。", "Theldrenは自ら進んで公正な戦いに加わるような男ではない。この旗を、奴の一族の色を示すように仕立てておいた。\n\nさらに魔術を施せば、この旗は奴が抗えないやり方で奴を挑発するだろう。\n\n私の古い知り合いのFalrinが、必要な手順を正確に知っている。彼には人を……苛立たせる独特のやり方があるのだ。彼はDire Maulの図書館にいる。", "はっきり言え、よそ者。俺が忙しいのが分からんのか？", "Anthionに遣わされたと言うのか? 奴は死んだものと思っていた。まあ、もっと奇妙な話も聞いてきた人生ではあるがな。\n\nよろしい。このbannerで私に何をしてほしいというのだ?", 0x8217cd50, 0xac19640e, 0x5b124075, 0x66d4d20d, 0x20d14ddc, "....." },
  [8949] = { "Falrinの復讐", "Dire MaulかBlackrock Spire内のOgresからOgre Warbead 25個を集め、Dire MaulのAthenaeumにいるFalrin Treeshaperに渡して下さい。", "確かに、お前が求めているその魔法のことはよく知っているとも、{class}。だが、たとえ古い友人に寄こされたのだとしても、私はただで頼みを聞いてやるような者ではない。\n\n私が粗暴なogreの隣人どもに抱いているのは、憎しみと軽蔑だけだ。それも奴らだけではない。King Gordokに従う者どもを憎むのと同じくらい、Omokkに従う者どもも憎んでいる。\n\n奴らを殺してきてほしい。たくさん殺してこい! 仕事の証として、奴らが首に下げているビーズを持ってくるのだ。これをやれば、お前の頼みについて話をしよう。", "頼んだ用件は済ませてくれたか、{name}？", "ふむ……妙なことに、あの野蛮どもの手にかかった兄弟の死について、少しも気が晴れない。\n\nまあ、お前は約束を果たした。何をしてやれるか見てみよう。", 0x925ac131, 0x6a75e717, 0x7dc93557, 0xd5749e9d, 0x62d8edfd, "....." },
  [8950] = { "煽動者の魔法", "Dire Maulの中にいるFalrin Treeshaperのところへ次の品を持って行ってください：Jeering Spectre's Essenceを1個、Dark Runeを4個、Large Brilliant Shardを8個。", "求めている魔法を旗にかけるのはたやすいことです、{name}。あいにく、この種のまじないを頼む人はめったにいないので、必要な材料が手元にありません。\n\nこの広間に取り憑いているEldrethの幽霊の一体のエッセンス、Scholomanceのdark runesを一握り、それにlarge brilliant shardsがいくつか必要です。これらの試薬を持ってきてくれれば、あなたのためにこの仕事をしてあげましょう。", "私の求める材料は集めたか、{name}？", "よし、とてもよく使えそうだ。魔法をかけ終わった後は、犠牲者はどうあがいても君の挑戦を受けざるを得ないだろう。", 0xb49d9e73, 0xd3d5a2ea, 0xb39814a4, 0x82ea88c6, 0x931e3725, "....." },
  [8951] = { "Anthionの遺言", "IronforgeのDelianaにWildheart Boots・Wildheart Kilt・Wildheart Spauldersを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x18d5514c, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8952] = { "Anthionの遺言", "IronforgeのDelianaにBeaststalker's Boots・Beaststalker's Pants・Beaststalker's Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x27ac01f3, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8953] = { "Anthionの遺言", "IronforgeのDelianaにMagister's Boots・Magister's Leggings・Magister's Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x7709557d, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
