  [8955] = { "Anthionの遺言", "IronforgeのDelianaにDevout Sandals・Devout Skirt・Devout Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x78a18b35, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8956] = { "Anthionの遺言", "IronforgeのDelianaにShadowcraft Boots・Shadowcraft Pants・Shadowcraft Spauldersを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x2a3c7831, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8957] = { "Anthionの遺言", "OrgimmarのMokvarにBoots of Elements・Kilt of Elements・Pauldrons of Elementsを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Mokvarのところへ戻り、彼に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "俺たちの命が、くだらないメダルひとつのせいで失われかけているなんて信じられん！それで、AnthionがBodleyについて話したのは確かなのか？\n\nまあ、お前は仕事を果たしたんだ、さっさと報酬を渡してしまおう。", 0x4e493fc8, 0x875c90e9, 0xbf3e43cf, 0x323bc67b, 0xfbf11a33, "....." },
  [8958] = { "Anthionの遺言", "IronforgeのDelianaにDreadmist Sandals・Dreadmist Leggings・Dreadmist Mantleを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x87706275, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8959] = { "Anthionの遺言", "IronforgeのDelianaにBoots of Valor・Legplates of Valor・Spaulders of Valorを返して下さい。", "Valthalakの魂はこの護符に封じ込められた。自分たちを待つ呪いも知らず、我々は欲に駆られ、愚かにも護符を三つに分けてしまったのだ。\n\nValthalakの魔法を止めるただ一つの方法は、この護符を元に戻すことだ。Delianaのところへ戻り、彼女に伝えてくれ。残りの破片を見つけるには、Bodleyだけが頼りだと。手筈を整えた君への報酬については、彼女と話してほしい。\n\n私は、これで眠りにつこう。君に最高の幸運あれ。君にはあらゆる幸運が必要だろうからね!", "戻ったか、{name}。突き止めたことを、すべて聞かせてもらわねばならん。だがまずは報酬の手配をしよう。", "私たちの命がこの馬鹿げたメダルのせいですっかり犠牲になっているだなんて、信じられないわ! それで、AnthionがBodleyについて話したことは確かなの?\n\nじゃ、あなたは仕事を終えたのだから、忘れないうちに報酬を渡しましょう。", 0x4e493fc8, 0x0882f310, 0x84b4d2d2, 0x323bc67b, 0xfbf11a33, "....." },
  [8960] = { "Bodleyの不幸な運命", "Blackrock Mountainへ行き、Extra-Dimensional Ghost Revealerを使ってBlackrock Spireの近くにいるBodleyを見つけて下さい。", "それで、私たちはメダルの残りを見つけなきゃならないのね? Bodleyの発見は少しばかり頭が痛いわね。彼はBlackrock Spireへまた入るためにBlackrock Mountainへ戻っていったの。そして二度と戻らなかった。\n\nゴブリンの幽霊探知装置を持って行くといいわ。最悪の事態が起きているに違いないから。", nil, "私のことが見えるとは嬉しいねえ。ついに人に話しかけられる!\n\n{name}、助けてくれるのか? 我々が犯した過ちを正し、物事を正しく直してくれると? すでにTop Piece of Lord Valthalak's Amuletを持っているというのが本当なら、他の二つの部分の正確な方角を示すことが出来ると思うよ。すべて繋ぎ合わせて、何もかも終わりにできる。\n\nおお、ところで。こんにちは、私の名はBodleyだ。君に会えてよかった!", 0x87a6a36a, 0x180c9e9b, 0x8261f568, nil, 0xe7724fe3, "...m." },
  [8961] = { "三人の炎の王", "Hallowed Brazierも合わせてIncendicite of Incendius・Ember of Emberseer・Cinder of Cyndersを集め、Blackrock Mountain内にいるBodleyのところへ戻って下さい。", "Lord Valthalakを召喚するには、まず二番目三番目の護符を集める必要がある。そのためには、火鉢とその火をおこすのに特別な石炭を手に入れることが必要だ。\n\n三人の炎の貴族がいるんだ。Blackrock DepthsのLord Incedius、Blackrock SpireのPyroguard Emberseer、SilithusのThe Duke of Cynders、彼らが我々の必要とする物を持っている。彼らの骸からそれぞれかけらを集めて、Hallowed Brazierを持って帰ってきてくれ。君がArgent Dawnから尊敬されているのなら、火鉢は彼らから買える。", "あの最後の仕事を受けたのは、我らの愚かさ……そして破滅だった。護符に封じられていたLord Valthalakの魂を、うっかり奪いさえしなければ。強欲に駆られて仲間内でそれを分け合うような者が、我らの傭兵団にいなければ。今日も私は生きて、麦酒をあおったり、子供を抱き上げて放り上げたりしていただろうに。\n\n{name}、我らの古い傭兵団の卑劣な者たちの強欲を、お前の破滅にまでしてはならんぞ。", "感激だよ、{class}。でももう時間を無駄にしていられない。次の仕事を頼むつもりだよ。行動を起こす前に、もっと大切な部材が必要になるだろうからね。\n\n行く手にある試練に挑む準備ができたと感じたら、また話しかけてくれ。", 0x167dcafa, 0x0f60b72c, 0x3179a164, 0x84feb208, 0xed97d865, "....." },
  [8962] = { "重要な素材", "Druidical Remainsを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々の中で最も名高いドルイドだったMor Grayhoofには、Cenarion Circleに親しい友が大勢いたが、その何人かはsilithidの犠牲になった。Silithus南東部のHive'Regal周辺に棲むsilithidから、Druidical Remainsを取り戻してきてくれ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "見事な働きだ、{name}。私はこのremainsの本質をbrazierに込めよう。\n\nあとはBlackrock Spireの下層、Tazz'Alaorの中でWar Master Vooneが居座る部屋へ行き、brazierを使って、かつての同志Mor Grayhoofの穢れた魂を呼び出すだけだ。奴からamuletの欠片を奪い取るまで、奴は安らげない。", 0x12929852, 0x54ea5e08, 0x5f376fc5, 0x4cb4edd2, 0x0846230d, "....." },
  [8963] = { "重要な素材", "Starbreeze Village Relicを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々のプリーストであるIsalienは、WinterspringのStarbreeze Villageで育った。Winterspring南部のFrostwhisper GorgeにいるFrostmaul giantsから、Starbreeze Village Relicを集めてきてくれ。奴らは時折、北へ襲撃に出ることで知られている。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "見事な働きだ、{name}。私はこのrelicの本質をbrazierに込めよう。\n\nあとはDire Maulの東棟にあるShrine of Eldretharrへ行き、brazierを使って、かつての同志Isalienの魂を呼び出すだけだ。彼女の魂は、Valthalakのamuletの欠片と、その中に宿る奴の魂の一部を手にしたことで穢されてしまった。", 0x12929852, 0x2bfd2a67, 0xd1a876ad, 0x4cb4edd2, 0xbdf7eff4, "....." },
  [8964] = { "重要な素材", "Brilliant Sword of Zealotryを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友たちの亡骸を呼び出せるほど強い、焦点となるものがな。\n\n兄弟のJarienとSothosは、Scarlet Crusadeの教えを信じていた。彼らはあの邪悪な組織の中で騎士になることを望んでいた。Eastern PlaguelandsのTyr's Handへ行き、そこにいるpraetoriansからBrilliant Sword of Zealotryを取り戻してくるのだ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "見事な働きだ、{name}。私はこのswordの本質をbrazierに込めよう。\n\nあとはStratholmeのThe Scarlet Bastionの中にあるThe Crimson Throneへ入り、brazierを使って、かつての同志JarienとSothosの亡骸を呼び出すだけだ。彼らの魂は、Valthalakのamuletの欠片とその中に宿る奴の魂を手にしたことで、さらに歪められてしまった。", 0x12929852, 0xcc126ac4, 0xfe9af6d8, 0x4cb4edd2, 0x64c9a62c, "....." },
  [8965] = { "重要な素材", "Soul Ashes of the Banishedを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。火鉢とそれに火を灯す手段は手に入ったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々と共に旅をしていたogreのネクロマンサー、Kormokは、Hillsbrad Foothillsの南の沖にあるPurgation Isleの、追放された死者たちの魂を呼び出すことを楽しんでいた。そこへ行き、その亡骸からSoul Ashes of the Banishedを取ってくるのだ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "見事な働きだ、{name}。私はこのashesの本質をbrazierに込めよう。\n\nあとはScholomanceのRas Frostwhisperの部屋へ入り、brazierを使って、かつての同志Kormokの魂を呼び出すだけだ。amuletの欠片と、その中に宿るValthalakの魂が、奴をさらに深く穢してしまった。お前が力ずくで奪い取るまで、奴は安らげない。", 0x12929852, 0x012d2346, 0x5ff0800a, 0x4cb4edd2, 0x4690693f, "....." },
  [8966] = { "Left Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってMor Grayhoofの魂を召喚し、討ち取って下さい。Left Piece of Lord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "私の友人Mor Grayhoofは、Lord Valthalakのアミュレットの欠片と、それに宿る堕落した霊の断片に取り憑かれた最初の犠牲者だった。Valthalakの呪文書とアミュレットを盗んだ後、我々はBlackrock Spireの上層から命からがら逃げ出した。その途中で、Morは尖塔の下層へ落ちてしまった。\n\n後になって、彼が落下を生き延びたものの、War Master Vooneに捕らえられて拷問を受けていたことが分かった。数人のspectral assassinsが忍び込み、Vooneの目の前で彼を殺したのだ。", "では、成し遂げたのか？Lord Valthalakの護符の左側の欠片を取り戻し、ついに我が古き仲間Mor Grayhoofの魂を鎮めたというのか？", "偉大なことを成し遂げたな、{name}。一つの魂は安らかに眠ったが、すべてを終わらせるにはまだ多くの仕事が残っている。\n\n残念ながら、amuletの右の欠片を持ったまま死んだ者の居場所は分からない。だが案ずるな。生前の私は占術をかじっていた。だからお前にもう一つ務めがある。それが最後の欠片を嗅ぎ出すことを可能にしてくれるだろう。", 0xd2fe617c, 0x4dd76fd6, 0x9e7edcce, 0xe0b53132, 0xedbb54f3, "....." },
  [8967] = { "Left Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってIsalienの魂を召喚し、討ち取って下さい。Left Piece of Lord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "後日、我々が自分たちで生き延びるためにできることをしていた頃、我々の仲間でナイトエルフのプリーストだったIsalienが、ナイトエルフの祖先の都、今ではDire Maulとして知られる場所へ向かったことが分かった。我々が集めた話によると、彼女がそこへ行ったのは個人的な理由もあったが、自分が持っていたアミュレットの欠片の秘密を解き明かすためでもあった。\n\nだが、彼女はたどり着けなかった。彼女がShrine of EldretharrでAlzzin the Wildshaperとその手勢に待ち伏せされたという知らせが我々のもとに届いたのだ。", "まさかもう、Isalienの魂の救済と、Lord Valthalakの護符の左側の欠片の回収を成し遂げたというのか、{name}？", "Isalienの魂を安らわせてくれて感謝する、{name}。これで彼女も女神のもとで安らぎを得られるかもしれん。だが、この厄介な事態から抜け出すには、まだ我々の前に多くの仕事が残っている。\n\n残念ながら、amuletの右の欠片を持ったまま死んだ者の居場所は分からない。だが案ずるな。生前の私は占術をかじっていた。だからお前にもう一つ務めがある。それが最後の欠片を嗅ぎ出すことを可能にしてくれるだろう。", 0xd2fe617c, 0xc6bd3d59, 0x17f28d94, 0xfb4c13f9, 0xe022c7bf, "....." },
  [8968] = { "Left Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってJarienとSothosを召喚し、討ち取って下さい。Left Piece of Lord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "兄弟のJarienとSothosは、我々の傭兵団が解散するとScarlet Crusadeに加わることにした。彼らはLeft Piece of Lord Valthalak's Amuletを持って行った。いなくなってせいせいしたが、あの欠片は取り戻さねばならん。\n\n我々が集めた情報によれば、彼らはScarlet Bastionにある自分の部屋で入団の儀式に失敗したため、実はGrand Crusader Dathrohan自身に殺されたのだそうだ。\n\nいずれにせよ、我々は……つまりお前は、アミュレットのその欠片を取り戻さねばならないのだ。", "ということは、{class}、あの2人の愚か者の魂をすでに鎮め、Lord Valthalakの護符の左側の欠片を取り戻したというのか？", "あの2人の魂がようやく安らぎを得たのは、結局のところ良かったのだろうな。生きている間は好きになれなかったがね。ともかく、目当てのものは手に入った。それは間違いなくいいことだ!\n\n残念ながら、amuletの右側の欠片を持ったまま死んだ者がどこにいるのかは分からない。だが心配はいらない。生前、僕は占術をかじっていてね。だから君にもう一つ頼みがある。それで最後の欠片を探り出せるはずだ。", 0xd2fe617c, 0x8de2cfff, 0xc9ff8f09, 0xc06de4b6, 0xa21d339f, "....." },
  [8969] = { "Left Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってKormokの魂を召喚し、討ち取って下さい。Left Piece of Lord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "さて、必要なものは揃った。お前が誰を呼び出すことになるのか話す時だ。\n\nKormokはogreにしてはまともな奴だった。死霊術に手を染めるまではな。それ以来、一団のほとんど全員にとって薄気味悪いことになった。だから、奴が自分のアミュレットの欠片を持って新しい住処、Scholomanceへ戻ったときも、驚きはしなかった。\n\nだが、そこでさえ、いや、おそらくそこだからこそ、奴はspectral assassinsから逃れられなかった。奴らは奴の師、Ras Frostwhisperの目の前で奴を殺したのだ。", "護符の左側の欠片を持って戻ったのなら、称賛しよう、{name}。だがそうでないなら、どうかそれを片付けてくれ。無駄にできる時間はないのだからな！", "よくやった、{name}! Kormokはogreにしては悪い奴じゃなかった、少なくとも生きている間はね。だから相応の安らぎを得られるといいんだが。だが、僕たちの前にはまだやるべきことが残っている。\n\n残念ながら、amuletの右側の欠片を持ったまま死んだ者がどこにいるのかは分からない。だが心配はいらない。生前、僕は占術をかじっていてね。だから君にもう一つ頼みがある。それで最後の欠片を探り出せるはずだ。", 0xd2fe617c, 0xff116265, 0x96ff3f47, 0xb72a79f1, 0xa1598e04, "....." },
  [8970] = { "君の未来にAlcaz島が見える……", "Strashaz nagaからBloodkelpを20個集め、Blackrock Mountain内のBodleyに渡して下さい。", "さっきも言ったように、{class}、私は生きていた頃、占い師になろうかと考えたことがあった。だが、想像するほど儲かるものではなかった。主に危険だし、試薬は珍しくて高価だからな。とはいえ、アミュレットの最後の欠片と、それと共にあるかつての戦友の霊の場所を突き止められるくらいの知識はある。\n\nそこでお前の出番だ、{name}。Dustwallow Marshの沖にあるAlcaz Islandへ行き、そこに住むStrashaz nagaからBloodkelpを集めてきてくれ。", "Bloodkelpだ、{name}。それも大量にな。私の占術の呪文に力を与えるにはそれが要る。集めるにはAlcaz Islandへ、少なくとも友を数人は連れて行く必要があるだろう……あのStrashazどもは厄介な連中だからな！", "正直なところ、{name}、君が無事に戻ってくるとは思わなかったよ。もっとも、今の君にとってAlcaz Islandなんて心配事のうちにも入らないんだろうね。\n\nよし、少し待ってくれ……占術というのは、指を鳴らせば正確な答えが返ってくるようなものじゃないんだ。", 0x6dbbaa62, 0x88efedff, 0x3fc8d09a, 0x14e2ded2, 0xa85b3bd9, "....." },
  [8977] = { "Delianaのもとへ戻る", "Extra-Dimensional Ghost RevealerをIronforgeのDelianaのところへ持って行って下さい。", "一緒に仕事ができて楽しかったよ、{name}。これが完成品だ。\n\n今取り組んでることの役に立つといいな。それと、もしよければ評判を広めてくれよ。客が増えるのは大歓迎だからさ！", "戻ったのか？", "素晴らしい! よくやった、{name}。あのゴブリンの細工を信用していいものか分からんが、ほかに選択肢はない。", 0x643770f8, 0x0989804d, 0x8ef11743, 0xcc21545f, 0xeaa54941, "....." },
  [8978] = { "Mokvarの元へ", "Extra-Dimensional Ghost Revealerを持って、OrgrimmarのMokvarのところへ戻って下さい。", "君との仕事は素晴らしかったよ、{name}。これが完成品だ。\n\n今君が取り組んでることの助けになるといいな。それからちょっと、もしよかったら普及を手伝ってくれよ。お客が増えるのは一向に構わないからさ!", "装置を持って戻ったのか？", "装置を持ち帰ってきてくれたのか! {name}、君のひたむきさには感心するよ。素晴らしい仕事だ。", 0xe98a7707, 0x96fafb49, 0x8ef11743, 0x74918fbc, 0xb9626688, "....." },
  [8979] = { "Fenstadの直感", "UndercityのApothecariumにいるApothecary Zingeに、Cologne BottleとPerfume Bottleを1本ずつ渡して下さい。", "最近のこの振る舞いの原因が分かった気がする。運河の悪臭に混じって、風に乗ってくる新しい香りを嗅いだかね? 流行り出した新しいコロンや香水だ。\n\n我々の思考は、何か汚らわしい錬金術で曇らされているのだ。\n\n確かめる方法は一つしかない。コロンと香水を一瓶ずつ、私の友人Apothecary Zingeのところへ持って行ってくれ。Royal Apothecary Societyが真相を突き止めてくれるだろう。\n\n戻ってきたら、購入代金は払い戻そう。", "どのようなご用でしょうか？", "またFenstadの妄執か。Royal Apothecary Societyには、奴のちょっとした調べ物をしてやる以外にすることがないとでも思っているのか?\n\nいいだろう、今回もまた付き合ってやる。", 0x34e8d6bc, 0x5a4c8b77, 0xce3ed502, 0x8e5652a8, 0x13f63991, "....." },
  [8980] = { "Zingeの判断", "Undercityの銀行の外にいるFenstad Argyleのところへ戻って下さい。", "これは予想外だ。結局のところ、Fenstadは何かをつかんでいたのかもしれない。精神を操る薬に使われる物質の痕跡が見つかった。\n\n香水にこういうものが少し含まれていること自体は珍しくない。だが、私が検出した材料のいくつかは……これは本格的な錬金術だ。Royal Apothecary Societyの一員ほどの腕前が要る。", nil, "やはり私は正しかったか。一刻も無駄にはできない。この汚された香りの出所を突き止めねばならん。\n\nこれを受け取れ。コロンと香水の代金だ。", 0x0c198352, 0x9d0c1525, 0x0974aa35, nil, 0x12fe93ba, "...m." },
  [8981] = { "贈り物", nil, nil, "お気に入りの指導者に、愛と敬慕の贈り物を届けに来たのか？", "素晴らしい！ 素晴らしい！ これを他の贈り物の山に加えておくよ。\n\nこんなにたくさん集まるとは思わなかった！ 君は本当に自分の指導者たちを慕っているんだね。\n\nさて、数にもう一つ加えておこう……", 0x14816d02, nil, nil, 0x23d358e8, 0x80214021, ".mm.." },
  [8982] = { "発生源の追跡", "UndercityのInnkeeper Normanと話して下さい。", "誰が供給者なのか探さなくてはいけない。Apothecary Katrinaが鞄にこのパルファムをしまい込んでいるのに気が付いたんだ。彼女はそれを宿屋のNormanから買ったと教えてくれたよ。", nil, "ああ、そうだ、香水とコロンはついこの間仕入れたばかりでね。棚にどれだけ置いておけるか分かったものじゃないよ。誰もがいくらあっても足りないという様子でね。\n\n私に言わせれば、何がそんなに大したことなのか、さっぱり分からんがね。", 0xc4ef4d74, 0xf180276e, 0x58f5480b, nil, 0xb26b7d5d, "...m." },
  [8983] = { "発生源の追跡", "UndercityのMage Quarter内にある裁縫屋のMara Rennickと話して下さい。", "うちの商品に何か問題があるって? まあ、これほど多くの人が何かをこんなに欲しがるのは見たことがないけどね。\n\n仕入れはMara Rennickという商人からだよ。彼女は町に来たばかりなんだ。\n\nMage Quarterの仕立屋に届けなきゃならない品物があるって言ってたよ。", nil, "悪いが、香水とコロンは在庫を全部、宿屋の主人のNormanに売ってしまってね。欲しいなら彼に話してみるといい。まだ残っていればの話だがね。\n\nだが、ぐずぐずしない方がいいよ。あの香水には抗えないと分かるはずだ。", 0xc4ef4d74, 0x162efe68, 0x7cd7419b, nil, 0x95662805, "...m.", nil, nil, nil, nil, 0xf8ee00a2 },
  [8984] = { "原因は暴かれた", "Apothecary Staffron Lerentを見つけて下さい。彼はHillsbrad FoothillsのRavenholdt Manorを過ぎたところにいます。", "いいか、はぐれ者の薬剤師がどう動こうと、私の知ったことではない。そいつが我々の努力を台無しにしているのなら、真っ先に正しい方向を教えてやろう。\n\nそいつが無実なら、隠すことなど何もないはずだろう?\n\n私はApothecary Staffron Lerentから品物を買った。奴はHillsbradの上の丘陵にあるRavenholdt Manorの先の、人目につかない場所で働いている。正直に言うと、少し変わった奴だと思ったよ。", nil, "そうだ、あの香りを作ったのは私だ。素晴らしい香りだろう? 抗いがたい。\n\nAllianceとHordeのウォリアーたちが等しくこの恋の情に囚われれば、奴らにはShadow Councilの台頭を止める力など残っていない。\n\n奴らは弱り、備えを失う。愛する者を案じるうちに、その鋭さは鈍っていくのだ。\n\n答えはあまりにも単純だった。なぜ思い至るまでにこれほどかかったのか? すべての者の弱点は心を通じてある。そして避けられぬものを、お前に止める術はない。", 0xf2e77961, 0xec6dc2fa, 0xe02ed5b0, nil, 0x904005d0, "...m." },
  [8985] = { "もっと重要な素材", "Starbreeze Village Relicを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。最後のアミュレットの欠片の在り処は分かったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々のプリーストであるIsalienは、WinterspringのStarbreeze Villageで育った。Winterspring南部のFrostwhisper GorgeにいるFrostmaul giantsから、Starbreeze Village Relicを集めてきてくれ。奴らは時折、北へ襲撃に出ることで知られている。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "よくやってくれた、{name}。このrelicの精髄をbrazierに込めておこう。\n\n後は、Dire Maulの東側の区画にあるShrine of Eldretharrへ行き、brazierを使って僕のかつての仲間、Isalienの霊を呼び出すだけだ。彼女の霊は、Valthalakのamuletの欠片と、その中に宿る奴の魂の一部を手にしたことで、堕落してしまっている。\n\nああ、そうだ。君がAlcaz Isleへ行った時のbloodkelpが少し余っていたから、君のために薬にしておいたよ。好きなものを選んでくれ!", 0x72f64feb, 0x2bfd2a67, 0x64d46ffb, 0x4cb4edd2, 0x2743ec43, "....." },
  [8986] = { "もっと重要な素材", "Druidical Remainsを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。最後のアミュレットの欠片の在り処は分かったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々の中で最も名高いドルイドだったMor Grayhoofには、Cenarion Circleに親しい友が大勢いたが、その何人かはsilithidの犠牲になった。Silithus南東部のHive'Regal周辺に棲むsilithidから、Druidical Remainsを取り戻してきてくれ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "よくやってくれた、{name}。このremainsの精髄をbrazierに込めておこう。\n\n後は、Blackrock Spireの下層、Tazz'AlaorにあるWar Master Vooneの部屋へ行き、brazierを使って僕のかつての仲間、Mor Grayhoofの堕ちた霊を呼び出すだけだ。amuletの欠片を奪い取られるまで、彼は安らぐことができない。\n\nああ、そうだ。君がAlcaz Isleへ行った時のbloodkelpが少し余っていたから、君のために薬にしておいたよ。好きなものを選んでくれ!", 0x72f64feb, 0x54ea5e08, 0x8d3b3891, 0x4cb4edd2, 0x549a6ac2, "....." },
  [8987] = { "もっと重要な素材", "Brilliant Sword of Zealotryを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。最後のアミュレットの欠片の在り処は分かったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友たちの亡骸を呼び出せるほど強い、焦点となるものがな。\n\n兄弟のJarienとSothosは、Scarlet Crusadeの教えを信じていた。彼らはあの邪悪な組織の中で騎士になることを望んでいた。Eastern PlaguelandsのTyr's Handへ行き、そこにいるpraetoriansからBrilliant Sword of Zealotryを取り戻してくるのだ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "よくやってくれた、{name}。このswordの精髄をbrazierに込めておこう。\n\n後は、StratholmeのThe Scarlet Bastionの中にあるThe Crimson Throneへ入り、brazierを使って僕のかつての仲間、JarienとSothosの亡骸を呼び出すだけだ。彼らの魂は、Valthalakのamuletの欠片と、その中に宿る奴の霊を手にしたことで、さらに歪められてしまっている。\n\nああ、そうだ。君がAlcaz Isleへ行った時のbloodkelpが少し余っていたから、君のために薬にしておいたよ。好きなものを選んでくれ!", 0x72f64feb, 0xcc126ac4, 0x704a7554, 0x4cb4edd2, 0x67acddbf, "....." },
  [8988] = { "もっと重要な素材", "Soul Ashes of the Banishedを手に入れ、Blackrock Mountain内のBodleyに渡して下さい。", "{class}、よく聞くのだ。最後のアミュレットの欠片の在り処は分かったが、火鉢に染み込ませる材料がもう一つ必要だ。亡くなったかつての戦友の霊を誘い出せるほど強い、焦点となるものがな。\n\n我々と共に旅をしていたogreのネクロマンサー、Kormokは、Hillsbrad Foothillsの南の沖にあるPurgation Isleの、追放された死者たちの魂を呼び出すことを楽しんでいた。そこへ行き、その亡骸からSoul Ashes of the Banishedを取ってくるのだ。", "もう戻ったのか、{class}。集めてこいと言ったものは持っているのか？", "よくやってくれた、{name}。このashesの精髄をbrazierに込めておこう。\n\n後は、Scholomanceに入り、Ras Frostwhisperの部屋へ行って、brazierを使って僕のかつての仲間、Kormokの霊を呼び出すだけだ。amuletの欠片と、その中に宿るValthalakの霊が、彼をさらに堕落させてしまった。君が力ずくで奪い取るまで、彼は安らぐことがない。\n\nああ、そうだ。君がAlcaz Isleへ行った時のbloodkelpが少し余っていたから、君のために薬にしておいたよ。好きなものを選んでくれ!", 0x72f64feb, 0x012d2346, 0xaf7111dc, 0x4cb4edd2, 0x17135263, "....." },
  [8989] = { "Right Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってMor Grayhoofの魂を召喚し、討ち取って下さい。繋ぎ合わせたLord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "私の友人Mor Grayhoofは、Lord Valthalakのアミュレットの欠片と、それに宿る堕落した霊の断片に取り憑かれた最初の犠牲者だった。Valthalakの呪文書とアミュレットを盗んだ後、我々はBlackrock Spireの上層から命からがら逃げ出した。その途中で、Morは尖塔の下層へ落ちてしまった。\n\n後になって、彼が落下を生き延びたものの、War Master Vooneに捕らえられて拷問を受けていたことが分かった。数人のspectral assassinsが忍び込み、Vooneの目の前で彼を殺したのだ。", "では、成し遂げたのか？Lord Valthalakの護符の右側の欠片を取り戻し、護符を一つに繋ぎ合わせ、ついに我が古き仲間Mor Grayhoofの魂を鎮めたというのか？", "Mor Grayhoofを助けてくれてありがとう、{name}。また一つ霊が安らかに眠り、繋ぎ合わさったamuletも手に入った! だが、一番の難関はまだこれからだ。\n\nこのbrazierをLord Valthalakの呼び出しに同調させるには、もういくつか集めて、ここの僕のところへ持ってきてもらう必要があるものがある。", 0x214733e9, 0xeee7fb11, 0x9e7edcce, 0x99d5db45, 0x7eed579d, "....." },
  [8990] = { "Right Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってIsalienの魂を召喚し、討ち取って下さい。繋ぎ合わせたLord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "後日、我々が自分たちで生き延びるためにできることをしていた頃、我々の仲間でナイトエルフのプリーストだったIsalienが、ナイトエルフの祖先の都、今ではDire Maulとして知られる場所へ向かったことが分かった。我々が集めた話によると、彼女がそこへ行ったのは個人的な理由もあったが、自分が持っていたアミュレットの欠片の秘密を解き明かすためでもあった。\n\nだが、彼女はたどり着けなかった。彼女がShrine of EldretharrでAlzzin the Wildshaperとその手勢に待ち伏せされたという知らせが我々のもとに届いたのだ。", "まさかもう、Isalienの魂の救済と、Lord Valthalakの護符の右側の欠片の回収を成し遂げたというのか、{name}？私に渡す前に、必ず護符の欠片を繋ぎ合わせておいてくれ。", "ありがとう、{name}。Isalienの霊を安らかに眠らせてくれてね。これで彼女も女神のもとで安らぎを見つけられるかもしれない。それに、繋ぎ合わさったamuletも手に入った! だが、一番の難関はまだこれからだ。\n\nこのbrazierをLord Valthalakの呼び出しに同調させるには、もういくつか集めて、ここの僕のところへ持ってきてもらう必要があるものがある。", 0x214733e9, 0x485d6be6, 0x17f28d94, 0xeea25137, 0x9c0c2d93, "....." },
  [8991] = { "Right Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってJarienとSothosを召喚し、討ち取って下さい。繋ぎ合わせたLord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "兄弟のJarienとSothosは、我々の傭兵団が解散するとScarlet Crusadeに加わることにした。彼らはRight Piece of Lord Valthalak's Amuletを持って行った。いなくなってせいせいしたが、あの欠片は取り戻さねばならん。\n\n我々が集めた情報によれば、彼らはScarlet Bastionにある自分の部屋で入団の儀式に失敗したため、実はGrand Crusader Dathrohan自身に殺されたのだそうだ。\n\nいずれにせよ、我々は……つまりお前は、アミュレットのその欠片を取り戻さねばならないのだ。", "ということは、{class}、あの2人の愚か者の魂をすでに鎮め、Lord Valthalakの護符の欠片を繋ぎ合わせたというのか？", "あの2人の魂がようやく安らぎを得たのは、結局のところ良かったのだろうな。生きている間は好きになれなかったがね。ともかく、目当てのものは手に入って、これでamuletは繋ぎ合わさった! だが、一番の難関はまだこれからだ。\n\nこのbrazierをLord Valthalakの呼び出しに同調させるには、もういくつか集めて、ここの僕のところへ持ってきてもらう必要があるものがある。", 0x214733e9, 0xdc8c9f89, 0x56d099b5, 0xd7dc1925, 0xd6ef7d4a, "....." },
  [8992] = { "Right Piece of Lord Valthalak's Amulet", "Brazier of Beckoningを使ってKormokの魂を召喚し、討ち取って下さい。繋ぎ合わせたLord Valthalak's AmuletとBrazier of Beckoningを、Blackrock Mountain内のBodleyに渡して下さい。", "さて、必要なものは揃った。次にお前が誰を呼び出すことになるのか話す時だ。\n\nKormokはogreにしてはまともな奴だった。死霊術に手を染めるまではな。それ以来、一団のほとんど全員にとって薄気味悪いことになった。だから、奴が自分のアミュレットの欠片を持って新しい住処、Scholomanceへ戻ったときも、驚きはしなかった。\n\nだが、そこでさえ、いや、おそらくそこだからこそ、奴はspectral assassinsから逃れられなかった。奴らは奴の師、Ras Frostwhisperの目の前で奴を殺したのだ。", "完成した護符を持って戻ったのなら、称賛しよう、{name}。だがそうでないなら、どうかそれを片付けてくれ。無駄にできる時間はないのだからな！", "よくやった、{name}！Kormokはogreにしてはそれほど悪い奴じゃなかった。少なくとも生きていた間はな。だから、ふさわしい安らぎを得られるといいんだが。そしてついに、amuletが完成したぞ！だが、一番難しい試練はまだこの先に待っている。\n\nbrazierがLord Valthalakを呼び出せるよう同調させるには、あといくつか集めてここに持ってきてもらわなきゃならない品がある。", 0x214733e9, 0x3aabb6e9, 0xacef7398, 0x10c6e76e, 0xc3ab7ea7, "....." },
  [8993] = { "贈り物", nil, nil, "お気に入りの指導者に、愛と敬慕の贈り物を届けに来たのか？", "素晴らしい！ 素晴らしい！ これを他の贈り物の山に加えておくよ。\n\nこんなにたくさん集まるとは思わなかった！ 君は本当に自分の指導者たちを慕っているんだね。\n\nさて、数にもう一つ加えておこう……", 0x14816d02, nil, nil, 0x23d358e8, 0x80214021, ".mm.." },
  [8994] = { "最終準備", "Blackrock Bracer 40個を集め、Flask of Supreme Powerを入手し、Blackrock Mountain内のBodleyに渡して下さい。", "もうすぐだ、{class}。あとはいくつか材料を集めてくるだけだ。そうすれば火鉢を調律し、Lord Valthalakを呼び出せるようにできる。\n\nまずはBlackrock Spireへ向かい、そこにいるオークどもを倒してきてほしい。奴らが身に着けている腕甲には、私が必要とする微量の金属が含まれている。だから、ちょうどいい量を取り出すには、いくつも必要になるだろう。それから、力を吹き込む工程を完了させるために、Flask of Supreme Powerを持ってきてもらわねばならない。\n\n幸運を祈る、{name}!", "ずいぶん遠くまで来たものだ、{name}。何が起ころうとも、これだけは言っておきたかった。ありがとう！お前は我らの傭兵団The Veiled Bladeの生き残りを助けようと、その身を死の危険にさらしてくれた。私に言わせれば、お前はもう我らの一員だ。", "これで揃ったな。bracersから金属を取り出して、この最後の材料をbrazierに込めよう。そうすれば、君がLord Valthalakを召喚して、ようやく奴の魂のamuletを返してやる準備が整う。\n\nずいぶん遠くまで来たものだ、{name}。終わりが見えてきた今、しくじってくれるなよ!", 0x3f8c901b, 0x0516611a, 0x4ffdc9e4, 0x457c2492, 0x802d61e6, "....." },
  [8995] = { "私が悪かった、Lord Valthalak", "Brazier of Beckoningを使い、Lord Valthalakを召喚して下さい。彼を片付け、死体にLord Valthalak's Amuletを使って下さい。その後、Lord Valthalak's AmuletをSpirit of Lord Valthalakに渡して下さい。", "すべての準備が整った、{name}。\n\n生前、Lord Valthalakは、今ではThe Beastの部屋になっている場所に住んでいた。そこへ行ってBrazier of Beckoningを使い、Lord Valthalakを呼び出すのだ。それで奴は再び肉体を得るから、もう一度倒さねばならない。私ならまずThe Beastを片付けるだろう。それに、Blackrock Spireの上層を生き延びられるだけの仲間を必ず連れて行くことだ。\n\nValthalakを始末したら、奴の亡骸にアミュレットを使うのだ。霊が一つに戻れば、奴はおそらくアミュレットも返してほしがるだろう。\n\n幸運を祈る!", "{class}よ、よくも我が眠りを妨げたな！", "貴様がこれを我から盗んだ元の一味ではないと我が知っていること、貴様にとっては幸運だったな。\n\n我のものは今、取り返させてもらうぞ、定命の者よ! amuletを我に渡せ!", 0x091595e0, 0xa4136e10, 0x6f4bc425, 0xe9e4a06e, 0x4490e060, "....." },
  [8996] = { "Bodleyの元へ", "Blackrock Mountain内にいるBodleyのところへ戻り、Brazier of Beckoningを渡して下さい。", "今回はそなたの無礼を見逃してやろう、{class}。そなたは今日、気高いことを成し遂げたのだからな。盗まれた我が霊の残りを我に返したのだ。明らかにひ弱な性質の{race}でありながら、そなたは我から盗んだ者たちが示さなかった、そしておそらく決して示せなかったであろう勇気を示した!\n\n我の気が変わってそなたをその場で殺す前に、奴らのもとへ戻るがよい。戻って奴らに伝えよ。奴らは安全だとな……今のところは。", "{name}、戻ってきたな、しかもまだ生きている！まあ、少なくとも我らのうち一人はそうというわけだ。\n\n何もかも話してもらわねばならんぞ！", "奴が本当にそこまで言ったのか? いやはや、亡霊の暗殺者や追跡者を引き上げさせるとは信じられない。将来、生きている仲間たちにさらに害を及ぼすとほのめかしたにしてもだ。\n\n今日はすごい日だ、{name}! 君は、成し遂げられる者などほとんどいないことをやってのけて、僕たちの過去の罪を、少なくとも一部は晴らしてくれた。\n\nありがとう! 感謝のしるしに、これを受け取ってほしい。これを使えば、君がもう訪れた同じ呪われた場所で、それにいくつか他の場所でも、霊を呼び出すことができる。", 0x19e87ba8, 0xfac84935, 0x82549069, 0xa6049caa, 0xe9f484cc, "....." },
  [8997] = { "振り出しに戻る", "IronforgeのThe High SeatにいるDelianaと話して下さい。", "それじゃあ、これでお別れね、友よ。でも、時々戻ってきて話したくなったら、私はいつでもここにいるわ。たぶん、仲間がBlackrock Spireの襲撃に加わるのを待ちながら、ぶらぶらしている時にでもね。\n\n泣き出す前に行って。IronforgeのDelianaのところへ戻って、何があったのか伝えてちょうだい。", nil, "あなたが無事に戻ってきてくれて、とても嬉しいです、{name}。少しくたびれてはいるようですが、元気そうですね。\n\nさあ、起きたことをすべて聞かせてください。", 0x88f51e42, 0xaae0b291, 0x56a6ee73, nil, 0xa0774fc6, "...m." },
  [8998] = { "始まりの場所へ", "OrgrimmarのValley of WisdomにあるGrommash HoldにいるMokvarと話して下さい。", "これでさよならじゃないかと思ってたよ、我が友よ。でも時々君が戻って話をしに来るんじゃないかと、いつもここにいるつもりだった。大方、Blackrock Spire襲撃に友達が加わるのを待ちながら、そこらをうろついてたんだろうけどね。\n\n行け、私が泣き出す前に。OrgrimmarのMokvarのところへ戻って、何が起こったのか伝えてくれ。", nil, "そなたが生き延びたのを見て嬉しく思うぞ、{name}。元気そうだな、少しばかり貫禄が増したようだが。\n\nさあ、起きたことをすべて我に聞かせよ。", 0x88f51e42, 0xe5b7a9bf, 0xac3be72a, nil, 0x8aaef27b, "...m." },
  [8999] = { "最高のものは最後に", "Wildheart CowlとWildheart VestをDelianaに渡して下さい。", "すごい話ね、{name}！あなたには感謝するわ。関わった人たちみんなも、心から感謝しているはずよ。これでやっと、夜は両目を閉じて眠れるかもしれないわ。\n\n報酬のことだけど、あなたがきっと気に入る品がいくつかあると思うの。", "取り決め通り、新しいFeralheart CowlとVestと引き換えに、お前のWildheartの装備を渡す用意はできているか？", "寂しくなるわ、{name}。あなたにはとても大きな恩があるの。一生かかっても返せそうにないわ。\n\n新しい頭と胴の防具を気に入ってくれるといいわ。そして、この先ずっとあなたを守ってくれますように。", 0x48402900, 0xd8200b75, 0x03db6ed6, 0x7a344d64, 0x2cf1dd7a, "....." },
})
